import { ChevronDown, Search, Trash2 } from "lucide-react";
import { useContext, useEffect, useState } from "react";
import { twMerge } from "tailwind-merge";
import db, { Item, Randomizer } from "../models/db";
import { getIconByType } from "./header";
import { ScriptItemsContext, ScriptItemType } from "./tabs/script";

export default function RandomizerCard({ item }: { item: ScriptItemType }) {
  const { setItem, removeItem } = useContext(ScriptItemsContext);
  const [show, setShow] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [allItems, setAllItems] = useState<Item[]>([]);
  const [selectedItems, setSelectedItems] = useState<number[]>([]);
  const [originalItems, setOriginalItems] = useState<number[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);

  useEffect(() => {
    loadItems();
    if (item.item?.id) {
      loadRandomizer(item.item.id);
    } else {
      setOriginalItems([]);
      setSelectedItems([]);
    }
  }, [item.item?.id]);

  async function loadItems() {
    const items = await db.items
      .filter((i) =>
        ["text", "image", "video", "audio", "doc", "contact"].includes(i.type)
      )
      .toArray();
    
    // Oculta items com "Maturador" no título (mesma lógica do main.tsx)
    const filteredItems = items.filter(
      (i) => !i.title?.toLowerCase().includes("maturador")
    );
    
    setAllItems(filteredItems);
  }

  async function loadRandomizer(id: number) {
    const rand = await db.randomizers.get(id);
    if (rand) {
      const existingItems = rand.items || [];
      setSelectedItems(existingItems);
      setOriginalItems([...existingItems]);
      setSaveError(null);
      return;
    }
    setSelectedItems([]);
    setOriginalItems([]);
  }

  function handleItemClick(itemId: number) {
    setSaveError(null);

    if (selectedItems.includes(itemId)) {
      setSelectedItems(selectedItems.filter((id) => id !== itemId));
    } else {
      setSelectedItems([...selectedItems, itemId]);
    }
  }

  function areNumberArraysEqual(a: number[], b: number[]) {
    if (a.length !== b.length) return false;
    // Compara na ordem exata, não ordenado (para manter a ordem das mensagens)
    return a.every((value, index) => value === b[index]);
  }

  const hasSelection = selectedItems.length > 0;
  const isDirty = !areNumberArraysEqual(selectedItems, originalItems);
  const canSave = hasSelection && (isDirty || !item.item?.id);

  async function handleSave() {
    if (!canSave) {
      if (!hasSelection) {
        setSaveError("Selecione pelo menos uma ação para salvar.");
      }
      return;
    }

    setIsSaving(true);
    setSaveError(null);

    try {
      const randomizerData: Randomizer = {
        id: item.item?.id,
        type: "randomizer",
        title: "Randomizar",
        items: selectedItems,
        itemType: "randomizer",
      };

      const savedId = await db.randomizers.put(randomizerData);

      // Atualiza o item com o ID salvo
      const updatedRandomizer = { ...randomizerData, id: savedId };
      setItem({
        ...item,
        item: updatedRandomizer,
      });

      // Atualiza originalItems para refletir o que foi salvo
      setOriginalItems([...selectedItems]);

      // Força recarregar do banco para garantir sincronização
      await loadRandomizer(savedId);
    } catch (error) {
      console.error("Erro ao salvar randomizador:", error);
      setSaveError("Não foi possível salvar. Tente novamente.");
    } finally {
      setIsSaving(false);
    }
  }

  const filteredItems = allItems.filter((i) => {
    // Garante que não mostra itens do maturador (dupla verificação)
    if (i.title?.toLowerCase().includes("maturador")) {
      return false;
    }
    // Filtra por termo de busca
    return i.title?.toLowerCase().includes(searchTerm.toLowerCase());
  });

  return (
    <div className="w-full flex flex-col gap-2">
      <div className="w-full flex flex-col gap-5 rounded p-2 bg-secondary">
        <button
          onClick={() => setShow(!show)}
          className="w-full flex items-center justify-between gap-2"
        >
          <span>Selecione as ações</span>
          <ChevronDown
            className={twMerge(
              "size-4 text-gray-400 duration-300 ease-in-out",
              show ? "rotate-180" : "rotate-0"
            )}
          />
        </button>

        {show && (
          <>
            <div className="w-full flex items-center gap-2 bg-neutral rounded px-5 py-1 cursor-pointer">
              <label htmlFor="search-randomizer">
                <Search className="w-5 text-gray-400" />
              </label>
              <input
                id="search-randomizer"
                className="w-full bg-transparent py-1 focus:outline-none"
                type="text"
                placeholder="Buscar..."
                value={searchTerm}
                onChange={(event) => setSearchTerm(event.target.value)}
              />
            </div>

            <div className="flex w-full flex-col gap-2 overflow-auto max-h-40 pr-1">
              {filteredItems.length === 0 ? (
                <span className="text-xs text-gray-500 p-2 text-center">
                  Nenhuma ação disponível. Crie ações primeiro!
                </span>
              ) : (
                filteredItems.map((actionItem) => {
                  const Icon = getIconByType(actionItem.type);
                  const isSelected = selectedItems.includes(actionItem.id!);

                  return (
                    <div
                      key={actionItem.id}
                      onClick={() => handleItemClick(actionItem.id!)}
                      className={twMerge(
                        "w-full gap-2 p-2 rounded cursor-pointer",
                        isSelected ? "bg-primary/50" : "bg-neutral"
                      )}
                    >
                      <button className="w-full flex items-center gap-2 whitespace-nowrap overflow-hidden">
                        <Icon className="size-3" />
                        <span className="text-ellipsis overflow-hidden">
                          {actionItem.title}
                        </span>
                      </button>
                    </div>
                  );
                })
              )}
            </div>

            <div className="w-full border-t border-white/5 pt-2">
              <button
                onClick={handleSave}
                disabled={!canSave || isSaving}
                className={twMerge(
                  "w-full rounded bg-primary py-2 text-sm font-medium text-white transition",
                  !canSave || isSaving
                    ? "cursor-not-allowed bg-primary/40"
                    : "hover:bg-primary/90"
                )}
              >
                {isSaving ? "Salvando..." : "Salvar seleção"}
              </button>
              {saveError && (
                <p className="mt-1 text-xs text-red-500">{saveError}</p>
              )}
            </div>
          </>
        )}
      </div>

      <div className="flex items-center justify-between gap-2 px-2">
        <span className="text-xs text-gray-400">
          {selectedItems.length}{" "}
          {selectedItems.length === 1
            ? "ação selecionada"
            : "ações selecionadas"}
        </span>
        <button
          onClick={() => removeItem(item.id)}
          className="h-full flex items-center pl-1"
        >
          <Trash2 className="size-4 text-red-500" />
        </button>
      </div>
    </div>
  );
}
