import { Youtube } from "lucide-react";
import { getBaseUrl } from "../../lib/base-url";
import { LoginTab } from "../providers/header-context";
import { CardAnual } from "./cards/saver/card-anual";
import { CardMensal } from "./cards/saver/card-mensal";

const baseUrl = getBaseUrl();

export default function LoginModelSaver({
  setModelTab,
}: {
  setModelTab: (tab: LoginTab) => void;
}) {
  return (
    <div className="w-full flex items-center flex-col gap-5">
      <div className="flex items-center gap-2">
        <img
          src={baseUrl + "/assets/logo_revsaver.png"}
          alt="Logo"
          className="w-10"
        />
        <img
          src={baseUrl + "/assets/revsaver_texto.png"}
          alt="Logo"
          className="w-36"
        />
      </div>

      <div className="max-w-2xl flex items-center justify-center flex-col gap-1 text-center">
        <h1 className="font-bold text-xl">
          Salve todos os contatos de uma vez com apenas 1 clique!
        </h1>
        <h3 className="text-sm">
          Com a revSaver, você nunca mais vai perder tempo salvando contato por
          contato. Simplifique sua vida e acabe com a dor de cabeça de uma vez
          por todas!
        </h3>
      </div>

      <div className="w-full flex items-center justify-center gap-5">
        <CardMensal />
        <CardAnual />
      </div>

      <button
        onClick={() => setModelTab("saver_video")}
        className="w-fit px-20 py-2 rounded bg-primary text-center text-white flex items-center gap-2 animate-pulse"
      >
        <Youtube className="size-5" />
        <span className="font-bold">O QUE É O REVSAVER?</span>
      </button>
    </div>
  );
}
