import { ChevronLeft, Zap } from "lucide-react";
import { getBaseUrl } from "../../lib/base-url";
import { LoginTab } from "../providers/header-context";
import { CardAnual } from "./cards/revzap/card-anual";
import { CardMensal } from "./cards/revzap/card-mensal";
import { urls } from "../utils/checkout";

const baseUrl = getBaseUrl();

export function LoginModelPlansVideo({
  setModelTab,
}: {
  setModelTab: (tab: LoginTab) => void;
}) {
  return (
    <div className="w-full flex items-center flex-col gap-5">
      <div className="flex items-center gap-2">
        <img src={baseUrl + "/assets/logo.webp"} alt="Logo" className="h-10" />
      </div>

      <div className="max-w-2xl flex items-center flex-col gap-1 text-center">
        <h1 className="font-bold text-xl">
          Mais de 10.558 usuários já transformaram seu atendimento com a RevZap
          completa.
        </h1>
      </div>

      <div className="w-[42rem] max-w-full aspect-video">
        <iframe
          credentialless=""
          sandbox="allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox"
          className="z-10 w-full h-full rounded bg-black"
          src={urls.video.revzap}
          width="100%"
          height="300"
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
          referrerPolicy="strict-origin-when-cross-origin"
          allowFullScreen
        ></iframe>
      </div>

      <button
        onClick={() => setModelTab("plans")}
        className="w-fit px-20 py-2 rounded bg-primary text-center text-white flex items-center gap-2 animate-pulse"
      >
        <Zap className="size-5" />
        <span className="font-bold">PLANOS REVZAP</span>
      </button>
    </div>
  );
}

export function LoginModelPlans({
  setModelTab,
}: {
  setModelTab: (tab: LoginTab) => void;
}) {
  return (
    <div className="w-full flex flex-col gap-3">
      <button
        onClick={() => setModelTab("plans_video")}
        className="w-fit flex items-center gap-2"
      >
        <ChevronLeft className="size-4" />
        <span>Voltar</span>
      </button>

      <div className="w-full flex items-center gap-5">
        <CardMensal />
        <CardAnual />
      </div>
    </div>
  );
}
