// Debug bridge (DEV only): permite rodar diagnósticos via Console mesmo sem WPP exposto.
// Fica eliminado do bundle quando DEV !== "true" (dotenv-webpack + terser).
const REVZAP_DEV_DEBUG = process.env.DEV === "true";

/**
 * Log condicional que só aparece quando DEV="true"
 * @param prefix - Prefixo do log (ex: "[getGroups]")
 * @param args - Argumentos para console.log
 */
const devLog = (...args: any[]) => {
  if (REVZAP_DEV_DEBUG) {
    console.log(...args);
  }
};

/**
 * Warning condicional que só aparece quando DEV="true"
 * @param prefix - Prefixo do warning
 * @param args - Argumentos para console.warn
 */
const devWarn = (...args: any[]) => {
  if (REVZAP_DEV_DEBUG) {
    console.warn(...args);
  }
};

/**
 * Error sempre aparece (mesmo em produção), mas com contexto adicional em DEV
 * @param args - Argumentos para console.error
 */
const devError = (...args: any[]) => {
  console.error(...args);
};

// Expor o banco de dados globalmente para o whatsapp-functions.ts
(window as any).db = db;

function waitForElement(
  selector: string,
  callback: (element: Element) => void,
) {
  const element = document.querySelector(selector);
  if (element) {
    callback(element);
  } else {
    setTimeout(() => waitForElement(selector, callback), 300);
  }
}

