waitForElement("#pane-side", async () => {
  const element = document.querySelector("#app > div");
  if (element) {
    const div = document.createElement("header");
    div.id = "ext-header";
    element.insertBefore(div, element.firstChild);

    const targetElement = document.querySelector(
      "#app > div > .x78zum5.xdt5ytf.x5yr21d > .x78zum5.xdt5ytf.x5yr21d > div > header",
    ) as HTMLElement | null;

    if (targetElement) {
      targetElement.style.backgroundColor = "#6F1FF0";
    }
  }

  await startTriggers();
  addHeader();
  changeChat();
  await getActiveScriptWait();
  await startSheduleShoots();
  window.dispatchEvent(new CustomEvent(REVZAP_WINDOW_EVENTS.Chat.OnChangeChat));

  // Verifica se há nova versão disponível na Chrome Store (fire-and-forget, falha silenciosa)
  void initUpdateChecker();

  // Verifica e reinicia o maturador se estiver ativo após recarregamento
  setTimeout(async () => {
    try {
      // Primeiro verifica no storage
      const res = await chrome.storage.local.get("maturadorStatus");
      let status = res.maturadorStatus;

      // Se não encontrar no storage, verifica no DB local
      if (!status?.ativo) {
        const config = await db.maturador_config.limit(1).first();
        if (config?.ativo) {
          devLog(
            "[Maturador] Maturador ativo encontrado no DB local, atualizando storage...",
          );
          // Atualiza o storage com o estado do DB
          await chrome.storage.local.set({
            maturadorStatus: {
              ativo: true,
              whatsapp: "", // Será preenchido pelo background
              delayMin: config.intervaloMin || 1,
              delayMax: config.intervaloMax || 2,
              updatedAt: Date.now(),
            },
          });
          status = { ativo: true };
        }
      }

      if (status?.ativo) {
        devLog(
          "[Maturador] Maturador estava ativo, reiniciando após recarregamento...",
        );
        await chrome.runtime.sendMessage({
          action: "maturador.startShoot",
        });
      } else {
        devLog("[Maturador] Maturador não está ativo após recarregamento");
      }
    } catch (error) {
      devError(
        "[Maturador] Erro ao verificar maturador após recarregamento:",
        error,
      );
    }
  }, 3000); // Aumentado para 3 segundos para garantir que o DB está pronto
});

window.addEventListener("addStep", (e) => {
  const { id, users } = (e as CustomEvent<{ id: number[]; users: string }>)
    .detail;

  id.forEach(async (id) => {
    await addUsersToStep(id, users);
  });
});

window.addEventListener("delStep", (e) => {
  const { id, users } = (e as CustomEvent<{ id: number[]; users: string }>)
    .detail;

  id.forEach(async (id) => {
    await delUsersToStep(id, users);
  });
});

window.addEventListener(
  REVZAP_WINDOW_EVENTS.Audio.ConvertRequest,
  async (e) => {
    const { id, content, fileName } = (
      e as CustomEvent<{ id: number; content: string; fileName: string }>
    ).detail;

    if (!content) return;

    const isOgg = validateAudioIsOgg(content);

    if (!isOgg) {
      const convertedFile = await convertAudioToOgg({
        file: content,
        fileName,
      });

      await updateAudio(id, convertedFile.base64);

      window.dispatchEvent(
        new CustomEvent(REVZAP_WINDOW_EVENTS.Audio.ConvertComplete, {
          detail: { content: convertedFile.base64 },
        }),
      );
    } else {
      window.dispatchEvent(
        new CustomEvent(REVZAP_WINDOW_EVENTS.Audio.ConvertComplete, {
          detail: { content },
        }),
      );
    }
  },
);

let isInputChatBlocked = false;
let inputBlockObserver: MutationObserver | null = null;
let inputBlockObserverScheduled = false;

const scheduleApplyInputBlock = () => {
  if (!isInputChatBlocked) return;
  if (inputBlockObserverScheduled) return;
  inputBlockObserverScheduled = true;
  window.setTimeout(() => {
    inputBlockObserverScheduled = false;
    void applyBlockInputChat();
  }, 50);
};

const applyBlockInputChat = async () => {
  if (!isInputChatBlocked) return;

  const isChatComposer = (el: HTMLElement): boolean => {
    const ariaLabel = el.getAttribute("aria-label") || "";
    const placeholder = el.getAttribute("aria-placeholder") || "";

    // Excluir explicitamente a caixa de pesquisa / Meta AI
    if (ariaLabel.includes("Caixa de texto de pesquisa")) return false;
    if (placeholder.includes("Meta AI") || placeholder.includes("pesquise"))
      return false;

    // Incluir apenas campos de conversa
    if (ariaLabel.startsWith("Digitar na conversa com")) return true;
    if (placeholder === "Digite uma mensagem") return true;

    return false;
  };

  const getPatternInput = (): HTMLElement | null => {
    // Pega todos os possíveis editores de texto
    const candidates = document.querySelectorAll<HTMLElement>(
      "[contenteditable='true'][role='textbox'][data-lexical-editor='true']",
    );

    for (const el of candidates) {
      if (isChatComposer(el)) {
        return el;
      }
    }

    // Fallback para seletor antigo se não encontrar com data-lexical-editor
    const fallback = document.querySelector<HTMLElement>(
      '[aria-placeholder="Digite uma mensagem"]',
    );
    if (fallback) return fallback;

    return null;
  };

  let patternInput = getPatternInput();

  if (!patternInput) {
    await new Promise((resolve) => setTimeout(resolve, 250));
    patternInput = getPatternInput();
  }

  if (!patternInput) return;

  const parent = patternInput.parentElement;
  if (!parent) return;

  const plusIcon = document.querySelector(
    ".x100vrsf.x1vqgdyp.x78zum5.x6s0dn4.xpvyfi4",
  ) as HTMLElement;

  const stickerIcon = document.querySelector(
    ".x78zum5.x98rzlu.xpvyfi4.x1fns5xo.x6s0dn4.xl56j7k.x1c9tyrk.xeusxvb.x1pahc9y.x1ertn4p.xbelrpt",
  ) as HTMLElement;

  const micIcon = document.querySelector(
    ".x9f619.x78zum5.x6s0dn4.xl56j7k.xpvyfi4.x2lah0s.x1c4vz4f.x1fns5xo.x1ba4aug.x1c9tyrk.xeusxvb.x1pahc9y.x1ertn4p.x1pse0pq.xpcyujq",
  ) as HTMLElement;

  if (plusIcon) {
    plusIcon.style.pointerEvents = "none";
    plusIcon.style.display = "none";
  }

  if (stickerIcon) {
    stickerIcon.style.pointerEvents = "none";
    stickerIcon.style.display = "none";
  }

  if (micIcon) {
    micIcon.style.pointerEvents = "none";
    micIcon.style.display = "none";
  }

  // Hide the input
  patternInput.style.pointerEvents = "none";
  patternInput.style.display = "none";

  // Hide placeholder if it exists as a sibling
  const placeholder = parent.querySelector(
    '[aria-hidden="true"]',
  ) as HTMLElement;
  if (placeholder && placeholder.innerText === "Digite uma mensagem") {
    placeholder.style.display = "none";
  }

  const warningText =
    "Você tem um script em andamento neste chat: quer encerrar está ação neste chat?";

  // Check if button already exists in parent
  const existingButton = parent.querySelector(".message-input-revzap");
  if (existingButton) return;

  const stopButton = document.createElement("button");
  stopButton.type = "button";
  stopButton.className = "message-input-revzap";
  stopButton.textContent = "PARA SCRIPT";
  stopButton.title = warningText;
  stopButton.style.margin = "0";
  stopButton.style.padding = "10px 14px";
  stopButton.style.border = "none";
  stopButton.style.borderRadius = "8px";
  stopButton.style.background = "#ef4444";
  stopButton.style.color = "#fff";
  stopButton.style.fontSize = "13px";
  stopButton.style.fontWeight = "600";
  stopButton.style.cursor = "pointer";
  stopButton.style.display = "flex";
  stopButton.style.alignItems = "center";
  stopButton.style.justifyContent = "center";
  stopButton.style.gap = "6px";
  stopButton.style.width = "100%";
  stopButton.style.boxSizing = "border-box";
  stopButton.style.alignSelf = "stretch";
  // Ensure button takes available space like the input did
  stopButton.style.flex = "1";

  const stopScript = () => {
    if (stopButton.disabled) return;

    stopButton.disabled = true;
    stopButton.textContent = "Parando...";
    stopButton.style.opacity = "0.85";
    window.dispatchEvent(new CustomEvent(REVZAP_WINDOW_EVENTS.Chat.Pause));

    window.setTimeout(() => {
      stopButton.disabled = false;
      stopButton.textContent = "Parar script";
      stopButton.style.opacity = "1";
    }, 3000);
  };

  stopButton.addEventListener("click", stopScript);

  parent.appendChild(stopButton);
};

window.addEventListener(REVZAP_WINDOW_EVENTS.Chat.BlockInput, async () => {
  isInputChatBlocked = true;

  if (!inputBlockObserver) {
    inputBlockObserver = new MutationObserver(() => {
      scheduleApplyInputBlock();
    });
    if (document.body) {
      inputBlockObserver.observe(document.body, {
        childList: true,
        subtree: true,
      });
    }
  }

  await applyBlockInputChat();
});

