import { createContext, useEffect, useRef, useState } from "react";
import db, { Item, ItemType, Randomizer, Script } from "../../models/db";
import AddMenuScript from "../add-menu-script";
import { getIconByType } from "../header";
import { useScriptSet } from "../hooks/script-set";
import Loading from "../loading";
import ScriptItem from "../script-item";
import { SelectGroup } from "../selects/group";
import SortableListScript from "../sortable-list-script";

// Função auxiliar para conversão de unidades de tempo para segundos
const convertToSeconds = (
  value: number,
  unit: "segundos" | "minutos" | "horas"
): number => {
  switch (unit) {
    case "minutos":
      return value * 60;
    case "horas":
      return value * 3600;
    default:
      return value;
  }
};

// Função auxiliar para conversão de segundos para outras unidades
const convertFromSeconds = (
  seconds: number,
  unit: "segundos" | "minutos" | "horas"
): number => {
  switch (unit) {
    case "minutos":
      return seconds / 60;
    case "horas":
      return seconds / 3600;
    default:
      return seconds;
  }
};

type ScriptItemsDataType = Exclude<ItemType, "group" | "script">;

export type ScriptWait = {
  stepId: number;
  chatId: string;
  lastIndex: number;
  scriptId: number;
  script: Script;
  isShooting?: boolean;
  executionType?: "manual" | "automation" | "trigger";
};

export type ScriptItemType = {
  id: number;
  index: number;
  type: ScriptItemsDataType;
  item?: Item | StepItem | Randomizer;
  delay?: number;
  delayUnit?: "segundos" | "minutos" | "horas";
  stepId?: number;
};

type StepItem = {
  type: "addStep" | "removeStep";
  itemType: "addStep" | "removeStep";
  stepId: number;
  id?: number;
  title: string;
  index: number;
  users: string[];
};

type ScriptItemsContextType = {
  addItem: (itemType: ScriptItemsDataType) => void;
  setItem: (item: ScriptItemType) => void;
  removeItem: (id: number) => void;
};

export const ScriptItemsContext = createContext({} as ScriptItemsContextType);

const validateErrors = {
  title: "Digite um título!",
  items: "Organize o seu script!",
};

export default function MenuScriptTab({ item }: { item?: Script }) {
  const [items, setItems] = useState<ScriptItemType[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const titleRef = useRef<HTMLInputElement>(null);
  const groupRef = useRef<HTMLSelectElement>(null);
  const itemsRef = useRef<HTMLDivElement>(null);
  const {
    saveItem,
    removeItem: removeItemScript,
    errors,
  } = useScriptSet({ item, validateErrors });
  const Icon = getIconByType("script");

  useEffect(() => {
    getAllItems().finally(() => setIsLoading(false));
  }, []);

  useEffect(() => {
    if (errors.title && titleRef.current) {
      scrollToElement(titleRef.current);
    } else if (errors.items && itemsRef.current) {
      scrollToElement(itemsRef.current);
    }
  }, [errors]);

  function scrollToElement(element: HTMLElement) {
    element.scrollIntoView({
      behavior: "smooth",
      block: "center",
    });
  }

  async function getAllItems() {
    if (!item) return;

    const arr = item.items?.map((i) => ({ id: i.id, type: i.type }));

    const promises =
      arr?.map(async (i) => {
        if (!i?.id) return undefined;

        if (i.type === "addStep" || i.type === "removeStep") {
          const steps = await db.steps.get(i.id);
          if (!steps) return undefined;

          return {
            ...steps,
            type: i.type,
            itemType: i.type,
            stepId: i.id,
          } as StepItem;
        }

        if (i.type === "randomizer") {
          const randomizer = await db.randomizers.get(i.id);
          if (!randomizer) return undefined;
          return { ...randomizer };
        }

        const singleItem = await db.items.get(i.id);

        if (!singleItem) return undefined;

        return singleItem;
      }) ?? [];

    const res = await Promise.all(promises);

    const obj: ScriptItemType[] = [];

    item.items?.map((i, index) => {
      if (i.type === "wait") {
        obj.push({
          id: index + 1,
          index,
          type: "wait",
          item: {
            type: "wait",
            title: "Aguarde a resposta do usuário...",
            itemType: "wait",
          },
        });

        return;
      }

      if (i.type === "delay") {
        const delayInSeconds = i.delay && i.delay / 1000;
        // Tentar recuperar a unidade original do banco, ou usar "segundos" como padrão
        const savedUnit = (i as any).delayUnit || "segundos";
        const delayValue = delayInSeconds
          ? convertFromSeconds(delayInSeconds, savedUnit)
          : 0;
        const unitLabel =
          savedUnit === "segundos"
            ? "segundos"
            : savedUnit === "minutos"
              ? "minutos"
              : "horas";

        obj.push({
          id: index + 1,
          index,
          type: "delay" as ScriptItemsDataType,
          item: {
            type: "delay",
            title: `Aguardar ${delayValue || 0} ${unitLabel}...`,
            itemType: "delay",
          },
          delay: delayValue,
          delayUnit: savedUnit,
        });
        return;
      }

      const foundItem = res.find((r) => {
        if (
          r?.type === "addStep" ||
          r?.type === "removeStep" ||
          i.type === "addStep" ||
          i.type === "removeStep"
        ) {
          return (r as StepItem)?.stepId === i.id && r?.type === i.type;
        }

        return r?.id === i.id;
      });

      if (!foundItem && !i.delay) return;

      const delayInSeconds = i.delay && i.delay / 1000;
      // Tentar recuperar a unidade original do banco, ou usar "segundos" como padrão
      const savedUnit = (i as any).delayUnit || "segundos";
      const delayValue = delayInSeconds
        ? convertFromSeconds(delayInSeconds, savedUnit)
        : undefined;

      obj.push({
        id: index + 1,
        index,
        type: (foundItem?.type || "delay") as ScriptItemsDataType,
        item: foundItem
          ? { ...foundItem, type: foundItem.type as ScriptItemsDataType }
          : {
              type: "delay",
              title: `Aguardar ${delayValue || 0} ${savedUnit}...`,
              itemType: "delay",
            },
        delay: delayValue,
        delayUnit: savedUnit,
      });
    });

    setItems(obj);
  }

  function addItem(itemType: ScriptItemsDataType): void {
    setItems((prevItems) => [
      ...prevItems,
      {
        id: Date.now(),
        index: prevItems.length,
        type: itemType,
      },
    ]);
  }

  function setItem(item: ScriptItemType): void {
    setItems((prevItems) => {
      const result = [...prevItems];
      const index = prevItems.findIndex((obj) => obj.id === item.id);

      if (index !== -1) {
        result[index] = { ...result[index], ...item };
      } else {
        result.push(item);
      }

      return result;
    });
  }

  function removeItem(id: number): void {
    setItems((prevItems) => prevItems.filter((i) => i.id !== id));
  }

  async function handleClick(): Promise<void> {
    const title = titleRef.current?.value;
    const groupId = Number(groupRef.current?.value) || undefined;

    const newItem = {
      title,
      items: items.map((i) => {
        // Converter delay para segundos baseado na unidade, depois para milissegundos
        let delayInMs: number | undefined = undefined;
        if (i.delay !== undefined && i.delay !== null) {
          const delayInSeconds = convertToSeconds(
            i.delay,
            i.delayUnit || "segundos"
          );
          delayInMs = delayInSeconds * 1000;
        }

        const baseItem: any = {
          id: i.item?.id,
          index: i.index,
          delay: delayInMs,
        };

        // Adicionar delayUnit ao baseItem se existir
        if (i.delayUnit) {
          baseItem.delayUnit = i.delayUnit;
        }

        switch (i.type) {
          case "wait":
            return { ...baseItem, type: "wait" };
          case "addStep":
            return { ...baseItem, type: "addStep" };
          case "removeStep":
            return { ...baseItem, type: "removeStep" };
          case "randomizer":
            return { ...baseItem, type: "randomizer" };
          case "delay":
            return { ...baseItem, type: "delay" };
          default:
            return { ...baseItem, type: undefined };
        }
      }),
    };

    await saveItem({ newItem: newItem as Partial<Script>, groupId });
  }

  return (
    <ScriptItemsContext.Provider
      value={{
        addItem,
        setItem,
        removeItem,
      }}
    >
      <div className="w-full h-full flex flex-col items-center gap-5 overflow-auto">
        <div className="w-full flex items-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
          <Icon className="size-4" />
          <span className="text-center text-sm">Configurar script</span>
        </div>

        <div className="w-full flex flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
          <label htmlFor="title">Título</label>
          <input
            ref={titleRef}
            className="w-full rounded p-2 bg-secondary focus:outline-none"
            type="text"
            id="title"
            defaultValue={item?.title}
            placeholder="Digite um título..."
          />
          {errors.title && <p className="text-red-500">{errors.title}</p>}
        </div>

        <div className="w-full flex flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
          <div className="w-full flex items-center justify-between">
            <span>Fluxo do script</span>
            <AddMenuScript />
          </div>

          <div className="w-full flex flex-col gap-2" ref={itemsRef}>
            {isLoading && <Loading />}

            <SortableListScript items={items} setItems={setItems}>
              {items?.map((i) => (
                <ScriptItem key={i.id} item={i} />
              ))}
            </SortableListScript>
          </div>

          {errors.items && <p className="text-red-500">{errors.items}</p>}
        </div>

        {Object.keys(errors).length > 0 && (
          <p className="text-red-500 text-sm text-center">
            Há erros no formulário, corrija-os para poder salvar.
          </p>
        )}

        <SelectGroup ref={groupRef} defaultId={item?.id} type="script" />

        <button
          onClick={removeItemScript}
          className="w-full bg-neutral text-red-500 text-center p-2 rounded"
        >
          Excluir
        </button>

        <button
          onClick={handleClick}
          className="w-full bg-primary text-white text-center p-2 rounded"
        >
          Salvar
        </button>
      </div>
    </ScriptItemsContext.Provider>
  );
}
