import { useContext, useEffect, useState } from "react";
import db, { Shoot } from "../../models/db";
import { HeaderContext, MenuTabType } from "../providers/header-context";

type Validate = {
  [key: string]: string | undefined;
};

type ItemSet = {
  item?: Shoot;
  validateErrors: Validate;
};

type Set = {
  newItem: Partial<Shoot>;
  ignoreKeys?: string[];
  errors?: Validate;
  tab?: MenuTabType | null;
};

export function useShootSet({ item, validateErrors }: ItemSet) {
  const [errors, setErrors] = useState<Validate>({});
  const { setTab } = useContext(HeaderContext);

  useEffect(() => {
    if (item) {
      setErrors({});
    }
  }, [item]);

  function validateForm(
    newItem: Partial<Shoot>,
    ignoreKeys?: string[]
  ): boolean {
    const newErrors: { [key: string]: string | undefined } = {};

    for (const [key, value] of Object.entries(newItem)) {
      if (ignoreKeys && ignoreKeys.includes(key)) continue;
      if (key in validateErrors && !value) {
        newErrors[key] = validateErrors[key];
      }
    }

    setErrors(newErrors);

    return Object.keys(newErrors).length === 0;
  }

  async function saveItem({ newItem, errors, tab }: Set) {
    if (!validateForm(newItem)) {
      if (errors) setErrors((prev) => ({ ...prev, ...errors }));
      return;
    }

    if (errors && Object.keys(errors).length > 0) {
      setErrors((prev) => ({ ...prev, ...errors }));
      return;
    }

    let newItemID;

    if (item?.id) {
      newItemID = await db.shoots.put({
        ...(newItem as Shoot),
        id: item.id,
        status: undefined,
      });
    } else {
      newItemID = await db.shoots.add(newItem as Shoot);
    }

    if (newItemID !== undefined && tab !== null) {
      setTab(tab || "main");
    }

    const result = await db.shoots.get(newItemID);

    return result;
  }

  async function removeItem() {
    if (!item) return;

    if (window.confirm("Deseja realmente excluir este item?")) {
      if (item.id) {
        await db.shoots.delete(item.id);

        setTab("shoot_list");
      }
    }
  }

  return { saveItem, removeItem, errors, setErrors };
}
