import { twMerge } from "tailwind-merge";
import { getIconByType } from "./header";
import { useContext } from "react";
import { HeaderContext } from "./providers/header-context";
import { Copy, Settings2 } from "lucide-react";
import { Shoot } from "../models/db";
import db from "../models/db";

export default function ShootCard({
  item,
  className,
}: {
  item: Shoot;
  className?: string;
}) {
  const Icon = getIconByType("shoot");
  const { setActiveItem, setTab } = useContext(HeaderContext);

  function handleClickActive(e: React.MouseEvent<HTMLDivElement, MouseEvent>) {
    e.stopPropagation();

    setActiveItem({ shoot: item });
    setTab("shoot");
  }

  function handleClick() {
    setActiveItem({ shoot: item });
    setTab("shooting");
  }

  async function handleDuplicate(
    e: React.MouseEvent<HTMLDivElement, MouseEvent>
  ) {
    e.stopPropagation();

    try {
      const newShoot = {
        ...item,
        status: undefined,
        id: undefined,
        title: `${item.title} (cópia)`,
      };

      await db.shoots.add(newShoot);

      window.dispatchEvent(
        new CustomEvent("showErrorMessage", {
          detail: { message: "Item duplicado com sucesso." },
        })
      );
    } catch (error) {
      console.error("Erro ao duplicar shoot:", error);
    }
  }

  return (
    <button
      onClick={handleClick}
      className={twMerge(
        "w-full flex items-center h-12 justify-between gap-3 rounded-lg p-2 text-foreground duration-300",
        item.status === "shooted"
          ? "bg-primary/50 hover:bg-primary/75"
          : item.status === "shooting"
            ? "bg-primary/50 hover:bg-primary/75 animate-pulse"
            : "bg-neutral hover:bg-primary/50",
        className
      )}
    >
      <div className="flex items-center gap-3">
        <Icon className="size-3" />
        <span className="text-sm">{item.title}</span>
      </div>
      <div className="flex items-center gap-3">
        <div
          onClick={handleDuplicate}
          className="px-2 py-1 duration-300 hover:bg-white/50 rounded"
        >
          <Copy className="w-4 min-w-4" />
        </div>
        <div
          onClick={handleClickActive}
          className="px-2 py-1 duration-300 hover:bg-white/50 rounded"
        >
          <Settings2 className="w-4 min-w-4" />
        </div>
      </div>
    </button>
  );
}
