import { Check } from "lucide-react";
import { urls } from "../../../utils/checkout";

export function CardAnual() {
  return (
    <div className="min-w-72 flex-1 p-5 flex flex-col gap-5 rounded bg-black text-white">
      <div className="w-full flex items-center justify-between">
        <h3 className="font-bold text-lg">Plano anual</h3>
        <span className="text-xs rounded-full p-2 bg-primary text-white">
          Mais vendido
        </span>
      </div>

      <div className="flex flex-col gap-1">
        <span className="text-sm">
          De <s>R$970,80</s> por apenas
        </span>
        <h3 className="text-2xl font-bold">12x de R$29,90/mês</h3>
        <span className="text-sm">ou 257,20/ano</span>
      </div>

      <a
        href={urls.premium.anual}
        rel="noopener noreferrer"
        target="_blank"
        className="w-full p-2 rounded bg-primary text-white hover:bg-primary/70 duration-300 text-center"
      >
        Assinar agora
      </a>

      <hr className="w-full border-t border-solid border-gray-600" />

      <div className="w-full flex flex-col gap-2">
        <div className="flex items-center gap-2">
          <Check className="size-4 text-primary" />
          <span>1 usuário por licença</span>
        </div>
        <div className="flex items-center gap-2">
          <Check className="size-4 text-primary" />
          <span>12 meses de acesso</span>
        </div>
        <div className="flex items-center gap-2">
          <Check className="size-4 text-primary" />
          <span>Renovação automática</span>
        </div>
      </div>
    </div>
  );
}
