import { useLiveQuery } from "dexie-react-hooks";
import { Bookmark } from "lucide-react";
import { createPortal } from "react-dom";
import { useEffect, useRef, useState } from "react";
import db from "../models/db";
import {
  addUsersToStep,
  delUsersToStep,
  getActiveChat,
} from "./utils/functions";

export default function StepChatButton() {
  const [show, setShow] = useState(false);
  const [chatId, setChatId] = useState<string>();
  // allChatIds contém TODAS as variantes do chat ativo (wid/@c.us, lid/@lid, raw)
  // para permitir match com qualquer formato armazenado na etapa.
  const [allChatIds, setAllChatIds] = useState<string[]>([]);
  const [total, setTotal] = useState(0);
  const [anchorRect, setAnchorRect] = useState<DOMRect | null>(null);
  const anchorRef = useRef<HTMLDivElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  const steps = useLiveQuery(() => db.steps.toArray(), [], []);

  const getCompareKey = (id?: string) => {
    if (!id) return "";
    // Para grupos, mantemos o id completo (inclui sufixo @g.us).
    if (id.endsWith("@g.us")) return id;
    // Para contatos, usamos a parte antes do @ para igualar @c.us vs @lid.
    const num = id.split("@")[0] || id;
    // Normaliza variante brasileira 13 dígitos → 12 dígitos (mesmo que getStepUserKey):
    // 55 (país) + DDD (2) + 9 (extra) + 8 = 13 → remove o 9 do DDN → 12.
    if (num.length === 13 && num.startsWith("55")) {
      return num.slice(0, 4) + num.slice(5);
    }
    return num;
  };

  const findMatchingUserId = (users: string[], id?: string) => {
    if (!id) return undefined;
    const key = getCompareKey(id);
    return users.find((u) => getCompareKey(u) === key);
  };

  // Tenta match contra TODAS as variantes do chat ativo (wid, lid, raw).
  // Necessário porque a etapa pode armazenar @lid enquanto o chat ativo resolve
  // para @c.us (ou vice-versa) — os números são completamente diferentes.
  const findMatchInStep = (users: string[]) => {
    for (const id of allChatIds) {
      const match = findMatchingUserId(users, id);
      if (match) return match;
    }
    // Fallback: tenta com chatId principal
    return findMatchingUserId(users, chatId);
  };

  const handleClickOutside = (event: MouseEvent) => {
    if (modalRef.current && !modalRef.current.contains(event.target as Node)) {
      setShow(false);
    }
  };

  useEffect(() => {
    if (show) {
      document.addEventListener("mousedown", handleClickOutside);
    } else {
      document.removeEventListener("mousedown", handleClickOutside);
    }
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [show]);

  useEffect(() => {
    const handler = (e: Event) => {
      const { chatId, allIds } = (
        e as CustomEvent<{
          chatId?: string | null;
          allIds?: string[];
        }>
      ).detail;
      // console.warn("[StepChatButton] activeChatContextChanged", {
      //   chatId,
      //   allIds,
      // });
      setChatId(chatId ?? undefined);
      setAllChatIds(allIds ?? (chatId ? [chatId] : []));
    };

    window.addEventListener("activeChatContextChanged", handler);
    window.dispatchEvent(new Event("requestActiveChatContext"));

    // Fallback: mantém o caminho antigo caso o tracking ainda não esteja ativo.
    // NÃO sobrescreve allChatIds se já temos dados (evita race condition).
    getActiveChat().then((chat) => {
      if (chat) {
        // console.warn("[StepChatButton] getActiveChat fallback", { chat });
        setChatId((prev) => prev ?? chat);
        setAllChatIds((prev) => (prev.length > 0 ? prev : [chat]));
      }
    });

    return () => {
      window.removeEventListener("activeChatContextChanged", handler);
    };
  }, []);

  useEffect(() => {
    if (!show) {
      setAnchorRect(null);
      return;
    }

    const updateRect = () => {
      const rect = anchorRef.current?.getBoundingClientRect() ?? null;
      setAnchorRect(rect);
    };

    updateRect();

    window.addEventListener("resize", updateRect);
    window.addEventListener("scroll", updateRect, true);

    const observer = new MutationObserver(updateRect);
    observer.observe(document.body, {
      childList: true,
      subtree: true,
      attributes: true,
    });

    return () => {
      window.removeEventListener("resize", updateRect);
      window.removeEventListener("scroll", updateRect, true);
      observer.disconnect();
    };
  }, [show]);

  useEffect(() => {
    if (chatId || allChatIds.length > 0) {
      const count = steps.filter((step) =>
        Boolean(findMatchInStep(step.users ?? [])),
      ).length;
      // console.warn("[StepChatButton] total recalculado", {
      //   chatId,
      //   allChatIds,
      //   stepsCount: steps.length,
      //   matchCount: count,
      //   stepsUsers: steps.map((s) => ({
      //     id: s.id,
      //     title: s.title,
      //     users: s.users?.slice(0, 5),
      //   })),
      // });
      setTotal(count);

      // Se o total deu 0 mas temos um chatId e etapas carregadas, pode ser
      // race condition (MAIN world ainda não resolveu @lid → @c.us).
      // Re-solicita os dados do chat ativo após delay.
      if (count === 0 && chatId && steps.length > 0) {
        const retryTimer = setTimeout(() => {
          // console.warn("[StepChatButton] retry requestActiveChatContext");
          window.dispatchEvent(new Event("requestActiveChatContext"));
        }, 1200);
        return () => clearTimeout(retryTimer);
      }
    }
  }, [steps, chatId, allChatIds]);

  async function toggleSelectedStep(stepId?: number) {
    try {
      if (chatId && stepId) {
        const step = steps.find((i) => i.id === stepId);

        if (step) {
          const existing = findMatchInStep(step.users);
          if (existing) {
            // Remove usando o ID exato encontrado na etapa para garantir remoção correta
            // (inclusive variantes @c.us vs @lid e números BR com/sem dígito 9)
            await delUsersToStep(stepId, existing);
          } else {
            // Usa addUsersToStep atômico para evitar duplicatas
            await addUsersToStep(stepId, chatId!);
          }
        }
      }
    } catch (error) {
      console.error(error);
      window.dispatchEvent(
        new CustomEvent("showErrorMessage", {
          detail: { message: "Erro ao alternar o step.", details: error },
        }),
      );
    }
  }

  return (
    <div
      ref={anchorRef}
      className="relative w-10 flex items-center justify-center m-2"
    >
      <button
        onClick={() => {
          setShow(!show);
        }}
        className="p-2"
      >
        <div className="relative">
          <Bookmark
            className="size-5"
            fill={total > 0 ? "currentColor" : "transparent"}
          />

          {/* {total > 1 && (
            <div className="absolute bottom-full left-full translate-y-1/2 translate-x-0.5 pointer-events-none">
              <span className="text-xs font-bold">{total > 99 ? "99+" : total}</span>
            </div>
          )} */}
        </div>
      </button>

      {show &&
        anchorRect &&
        createPortal(
          <div
            ref={modalRef}
            className="min-w-56 p-3 rounded bg-neutral flex max-h-96 flex-col gap-2 shadow-lg overflow-y-auto"
            style={{
              position: "fixed",
              top: Math.round(anchorRect.bottom + 12),
              left: Math.round(anchorRect.right),
              transform: "translateX(-100%)",
              zIndex: 2147483647,
            }}
          >
            {steps?.length > 0 ? (
              steps
                .sort((a, b) => a.index - b.index)
                .map((item) => (
                  <Item
                    key={item.id}
                    title={item.title}
                    selected={!!findMatchInStep(item.users ?? [])}
                    onClick={() => toggleSelectedStep(item.id)}
                  />
                ))
            ) : (
              <p className="text-sm text-center">Nenhuma etapa encontrada</p>
            )}
          </div>,
          document.body,
        )}
    </div>
  );
}

function Item({
  title,
  selected,
  ...props
}: {
  title: string;
  selected?: boolean;
} & React.ButtonHTMLAttributes<HTMLButtonElement>) {
  return (
    <button
      className="w-56 flex items-center gap-2 p-3 rounded bg-neutral whitespace-nowrap duration-300 hover:bg-primary/50"
      {...props}
    >
      <Bookmark
        className="size-4 min-w-4 min-h-4"
        fill={selected ? "currentColor" : "transparent"}
      />
      <span className="text-sm capitalize text-ellipsis overflow-hidden">
        {title}
      </span>
    </button>
  );
}
