import { useLiveQuery } from "dexie-react-hooks"
import { useState, useEffect } from "react"
import db, {
  Item,
  Script,
  GroupItemType,
  Index
} from "../../models/db"

export type IndexedItem = (Item | Script) & {
  index?: number,
  itemType: "item" | "script"
}

export type IndexedContainer = {
  id: number,
  index: number
  groupId?: number
  title?: string
  color?: string
  items: IndexedItem[]
}

export default function useGetIndexes(newIndexes?: boolean) {
  const [indexedItems, setIndexedItems] = useState<IndexedContainer[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const groups = useLiveQuery(() => db.groups.toArray(), [])
  const items = useLiveQuery(() => db.items.filter((i) => !i.hidden).toArray(), [])
  const scripts = useLiveQuery(() => db.scripts.toArray(), [])
  const indexes = useLiveQuery(() => db.indexes.orderBy("index").toArray(), [])

  useEffect(() => {
    if (!newIndexes) return

    let isCancelled = false

    if (!groups || !items || !scripts) return

    const updateIndexes = async () => {
      const indexes = await db.indexes
        .orderBy("index")
        .toArray()

      if (isCancelled) return

      const removeIndexes: number[] = []

      removeIndexes.push(...indexes.filter(x => x.id !== undefined && x.itemType == "group" && !groups.find(i => i.id == x.itemId)).map(x => x.id!))
      removeIndexes.push(...indexes.filter(x => x.id !== undefined && x.itemType == "item" && !items.find(i => i.id == x.itemId)).map(x => x.id!))
      removeIndexes.push(...indexes.filter(x => x.id !== undefined && x.itemType == "script" && !scripts.find(i => i.id == x.itemId)).map(x => x.id!))

      if (removeIndexes.length) {
        if (isCancelled) return
        await db.indexes.bulkDelete(removeIndexes)
      }

      const len = indexes.length
      const addItems: { itemId?: number, itemType: "item" | "group" | "script" }[] = []

      groups.map(i => {
        const find = indexes.find(x => x.itemId == i.id && x.itemType == "group")
        if (!find) {
          addItems.push({ itemId: i.id, itemType: "group" })
        }
      })

      items.map(i => {
        const find = indexes.find(x => x.itemId == i.id && x.itemType == "item")
        if (!find) {
          addItems.push({ itemId: i.id, itemType: "item" })
        }
      })

      scripts.map(i => {
        const find = indexes.find(x => x.itemId == i.id && x.itemType == "script")
        if (!find) {
          addItems.push({ itemId: i.id, itemType: "script" })
        }
      })

      const itemsMapped = addItems.map((i, idx) => ({ ...i, index: len + idx, itemId: i.itemId as number }))

      if (itemsMapped.length) {
        if (isCancelled) return
        await db.indexes.bulkAdd(itemsMapped)
      }
    }

    updateIndexes()

    return () => {
      isCancelled = true
    }
  }, [groups, items, scripts])

  useEffect(() => {
    if (!groups || !items || !scripts || !indexes) return

    const obj: IndexedContainer[] = []

    indexes.map(index => {
      if (!index.id) return

      switch (index.itemType) {
        case "group":
          const group = groups.find(group => group.id == index.itemId)

          if (group) {
            obj.push({
              id: index.id,
              index: index.index,
              groupId: group.id,
              title: group.title,
              color: group.color,
              items: group.items.map(i => {
                let item
                if (i.type == "item") {
                  item = items.find(x => x.id == i.id)
                } else if (i.type == "script") {
                  item = scripts.find(x => x.id == i.id)
                }

                if (item) {
                  return { ...item, itemType: i.type }
                }
              }).filter(i => i !== undefined)
            })
          }
          break
        case "item":
          const item = items.find(item => item.id == index.itemId)

          if (!item?.id) break

          if (groups.find(group => group.items.find(i => i.id == item.id && i.type == "item"))) {
            break
          }

          obj.push({
            id: index.id,
            index: index.index,
            title: item.title,
            items: [{ ...item, itemType: "item" }]
          })
          break
        case "script":
          const script = scripts.find(script => script.id == index.itemId)

          if (!script?.id) break

          if (groups.find(group => group.items.find(i => i.id == script.id && i.type == "script"))) {
            break
          }

          obj.push({
            id: index.id,
            index: index.index,
            title: script.title,
            items: [{ ...script, itemType: "script" }]
          })
          break
      }
    })

    setIndexedItems(obj)
    setIsLoading(false)
  }, [groups, items, scripts, indexes])

  function arrayMove<T>(array: T[], from: number, to: number) {
    const newArray = [...array]
    const startIndex = to < 0 ? newArray.length + to : to

    const item = newArray.splice(from, 1)[0]
    newArray.splice(startIndex, 0, item)

    return newArray
  }

  function updateContainerIndex(oldId: number | string, newId: number | string) {
    setIndexedItems(items => {
      const oldIndex = items.findIndex(item => item.id === oldId)
      const newIndex = items.findIndex(item => item.id === newId)

      const newItems = arrayMove(items, oldIndex, newIndex)

      const result = newItems.map((item, index) => ({
        ...item,
        index
      }))

      const formatted: Index[] = result.map(i => {
        const itemId = i.groupId || i.items[0].id
        const itemType: Index["itemType"] = i.groupId ? "group" : i.items[0].itemType

        if (!itemId) return

        return {
          id: i.id,
          index: i.index,
          itemId,
          itemType
        }
      }).filter(i => i !== undefined)

      db.indexes.bulkPut(formatted)

      return result
    })
  }

  function updateItemsIndex(groupId: number, oldId: number | string, newId: number | string, oldType: "item" | "script", newType: "item" | "script") {
    const group = groups?.find(group => group.id == groupId)

    if (!group) return

    setIndexedItems(items => {
      const result = items.map(item => {
        if (item.groupId == groupId) {
          const oldIndex = item.items.findIndex(i => i.id === oldId && i.itemType === oldType)
          const newIndex = item.items.findIndex(i => i.id === newId && i.itemType === newType)

          const newItems = arrayMove(item.items, oldIndex, newIndex)

          const result = newItems.map((i, index) => ({
            ...i,
            index
          }))

          const formatted: GroupItemType[] = result.map(i => {
            return {
              id: i.id!,
              index: i.index,
              type: i.itemType
            }
          })

          db.groups.update(groupId, { ...group, items: formatted })

          return { ...item, items: result }
        }

        return item
      })

      return result
    })
  }

  return { indexedItems, updateContainerIndex, updateItemsIndex, isLoading }
}