import { useEffect, useRef } from "react"
import { getIconByType } from "../header"
import { Step } from "../../models/db"
import { useStepSet } from "../hooks/step-set"
import StepCard from "../step-card"
import SortableListStep from "../sortable-list-step"
import useGetSteps from "../hooks/get-steps"

const validateErrors = {
  title: "Digite um título!"
}

export default function MenuStepTab({ item }: { item?: Step }) {
  const { steps, updateStepIndex } = useGetSteps()
  const titleRef = useRef<HTMLInputElement>(null)
  const { saveItem, removeItem, errors } = useStepSet({ item, validateErrors })
  const Icon = getIconByType("step")

  useEffect(() => {
    if (titleRef.current) {
      titleRef.current.value = item?.title || ""
    }
  }, [item])

  async function handleClick() {
    const title = titleRef.current?.value!
    const count = steps.length

    const newItem = {
      title,
      users: [],
      index: count
    }

    await saveItem({ newItem })
  }

  return (
    <div className="w-full h-full flex flex-col items-center gap-5 overflow-auto">
      <div className="w-full flex items-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
        <Icon className="size-4" />
        <span className="text-center text-sm">Configurar etapa</span>
      </div>

      <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <label htmlFor="title">Título</label>
        <input
          ref={titleRef}
          type="text"
          id="title"
          defaultValue={item?.title}
          className="w-full rounded p-2 bg-secondary focus:outline-none"
          placeholder="Digite um título..."
        />
        {errors.title && <p className="text-red-500">{errors.title}</p>}
      </div>

      {item && (
        <button onClick={removeItem} className="w-full bg-neutral text-red-500 text-center p-2 rounded">Excluir</button>
      )}

      <button onClick={handleClick} className="w-full bg-primary text-white text-center p-2 rounded">Salvar</button>

      <div className="w-full flex items-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
        <Icon className="size-4" />
        <span className="text-center text-sm">Minhas etapas</span>
      </div>

      <div className="w-full flex flex-col gap-2">
        <SortableListStep items={steps} update={updateStepIndex}>
          {steps
            .filter(step => step.id !== item?.id)
            .sort((a, b) => a.index - b.index)
            .map(item => (
              <StepCard key={item.id} item={item} />
            ))}
        </SortableListStep>
      </div>
    </div>
  )
}