import { Youtube } from "lucide-react";
import { getBaseUrl } from "../../lib/base-url";
import { LoginTab } from "../providers/header-context";
import { CardAnual } from "./cards/maturador/card-anual";
import { CardMensal } from "./cards/maturador/card-mensal";
import { MaturadorDebug } from "./debug/maturador-debug";

const baseUrl = getBaseUrl();

// Variável para ativar/desativar o debug do maturador
const DEBUG_MATURADOR = false;

export default function LoginModelMaturador({
  setModelTab,
}: {
  setModelTab: (tab: LoginTab) => void;
}) {
  return (
    <div className="w-full flex items-center flex-col gap-5">
      <div className="flex items-center gap-2">
        <img
          src={baseUrl + "/assets/logo_revprotect.png"}
          alt="Logo"
          className="w-10"
        />
        <img
          src={baseUrl + "/assets/revprotect_texto.png"}
          alt="Logo"
          className="w-36"
        />
      </div>

      <div className="max-w-2xl flex items-center justify-center flex-col gap-1 text-center">
        <h1 className="font-bold text-xl">
          Mantenha seus chips WhatsApp sempre ativos e seguros!
        </h1>
        <h3 className="text-sm">
          Com o RevPROTECT, você automatiza o envio de mensagens entre seus
          números para simular atividade humana e evitar bloqueios. Mantenha
          seus chips sempre aquecidos e prontos para uso!
        </h3>
      </div>

      <div className="w-full flex items-center justify-center gap-5">
        <CardMensal />
        <CardAnual />
      </div>

      {DEBUG_MATURADOR && <MaturadorDebug />}

      <button
        onClick={() => setModelTab("maturador_video")}
        className="w-fit px-20 py-2 rounded bg-primary text-center text-white flex items-center gap-2 animate-pulse"
      >
        <Youtube className="size-5" />
        <span className="font-bold">O QUE É O REVPROTECT?</span>
      </button>
    </div>
  );
}
