import { twMerge } from "tailwind-merge";

export default function StepCardHeader({
  text,
  total,
  selected,
  ...props
}: {
  text: string;
  total: number;
  selected?: boolean;
} & React.HTMLAttributes<HTMLButtonElement>) {
  return (
    <button
      className={twMerge(
        "h-9 w-fit rounded flex items-center px-3 justify-center gap-1 text-sm hover:bg-primary duration-300",
        selected ? "bg-primary" : "bg-primary/70"
      )}
      {...props}
    >
      <span className="text-nowrap">{text}</span>
      <span className="bg-zinc-50 dark:bg-zinc-900 rounded-full px-1 py-0.5">
        {total}
      </span>
    </button>
  );
}
