import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent,
} from '@dnd-kit/core'
import {
  SortableContext,
  verticalListSortingStrategy
} from '@dnd-kit/sortable'
import db from '../models/db'
import { IndexedContainer } from './hooks/get-indexes'

export default function SortableListMain({
  children,
  items,
  update
}: {
  children: React.ReactNode,
  items: IndexedContainer[],
  update: (oldId: number | string, newId: number | string) => void
}) {
  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 5
      }
    })
  )

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event

    if (active.id !== over?.id && over) {
      const activeItem = items.find(i => i.id === active.id)
      const overItem = items.find(i => i.id === over.id)

      if (activeItem && !activeItem.groupId && overItem?.groupId) {
        addGroup(activeItem, overItem.groupId)
      } else {
        update(active.id, over.id)
      }
    }
  }

  async function addGroup(item: IndexedContainer, groupId: number) {
    const itemId = item.items[0].id
    const type = item.items[0].itemType

    if (item.groupId || !itemId) return

    const group = await checkGroupAssociation(itemId, type)

    if (group?.id) {
      await db.removeGroupItem(group.id, itemId)
    }

    await db.addGroupItem(groupId, { id: itemId, type: type })
  }

  async function checkGroupAssociation(itemId: number, type: "item" | "script") {
    return await db.groups.toArray()
      .then(groups => groups.find(i => i.items?.find(x => x.id === itemId && x.type === type)))
  }

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCenter}
      onDragEnd={handleDragEnd}
    >
      <SortableContext
        items={items}
        strategy={verticalListSortingStrategy}
      >
        {children}
      </SortableContext>
    </DndContext>
  )
}