import { useContext, useEffect, useRef, useState } from "react";
import AddMenuLabel from "./add-menu-label";
import { HeaderContext, MenuTabType } from "./providers/header-context";
import { Ellipsis, ChevronDown, ChevronRight, Blocks } from "lucide-react";
import { SessionContext } from "./providers/session-context";

export default function AddMenuSettings() {
  const [show, setShow] = useState(false);
  const [showOtherProducts, setShowOtherProducts] = useState(false);
  const { setTab } = useContext(HeaderContext);
  const { session } = useContext(SessionContext);
  const modalRef = useRef<HTMLDivElement>(null);

  const handleClickOutside = (event: MouseEvent) => {
    if (modalRef.current && !modalRef.current.contains(event.target as Node)) {
      setShow(false);
    }
  };

  useEffect(() => {
    if (show) {
      document.addEventListener("mousedown", handleClickOutside);
    } else {
      document.removeEventListener("mousedown", handleClickOutside);
      setShowOtherProducts(false);
    }
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [show]);

  function handleClick(itemType: MenuTabType) {
    setShow(false);
    setTab(itemType);
  }

  return (
    <div className="relative">
      <button
        onClick={() => setShow(!show)}
        className="group px-5 py-2 bg-neutral rounded duration-300 hover:bg-primary/50"
      >
        <Ellipsis className="size-5" />
      </button>

      {show && (
        <div
          ref={modalRef}
          className="z-10 absolute top-full translate-y-3 right-0 p-3 rounded bg-neutral flex flex-col gap-2 shadow-lg"
        >
          <AddMenuLabel itemType="group" onClick={() => handleClick("group")} />
          <AddMenuLabel itemType="step" onClick={() => handleClick("step")} />
          <AddMenuLabel
            itemType="shot-triggers-list"
            onClick={() => handleClick("shot-triggers-list")}
          />
          <AddMenuLabel
            itemType="shoot_list"
            onClick={() => handleClick("shoot_list")}
          />

          <div className="w-full flex flex-col gap-2">
            <button
              type="button"
              onClick={() => setShowOtherProducts((v) => !v)}
              aria-expanded={showOtherProducts}
              className="w-full flex items-center gap-2 p-3 rounded bg-neutral whitespace-nowrap duration-300 hover:bg-primary/50"
            >
              <Blocks className="size-4 min-w-4 min-h-4" />
              <span className="text-sm capitalize flex-1 text-left">
                Outros produtos
              </span>
              {showOtherProducts ? (
                <ChevronDown className="size-4 min-w-4 min-h-4 opacity-80" />
              ) : (
                <ChevronRight className="size-4 min-w-4 min-h-4 opacity-80" />
              )}
            </button>

            {showOtherProducts && (
              <div className="pl-4 flex flex-col gap-2">
                <AddMenuLabel
                  itemType="saver"
                  className="py-2"
                  onClick={() => handleClick("saver")}
                />
                <AddMenuLabel
                  itemType="maturador"
                  className="py-2"
                  onClick={() => handleClick("maturador")}
                />
              </div>
            )}
          </div>

          <AddMenuLabel
            itemType="settings"
            onClick={() => handleClick("settings")}
          />

          {session?.logged && (
            <AddMenuLabel
              itemType="account"
              onClick={() => handleClick("account")}
            />
          )}
        </div>
      )}
    </div>
  );
}
