import { useEffect, useState } from "react";
import { twMerge } from "tailwind-merge";
import { getIconByType } from "./header";
import { ChevronDown, Search } from "lucide-react";
import { SelectedShoot } from "./tabs/shoot";
import useGetIndexes, { IndexedItem } from "./hooks/get-indexes";
import { Item, ShootItem, ShotTriggersItem } from "../models/db";

export default function ItemsSelect({
  setItems,
  defaultItems,
}: {
  setItems: (items: SelectedShoot[]) => void;
  defaultItems?: ShootItem[] | ShotTriggersItem[];
}) {
  const [show, setShow] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [selecteds, setSelecteds] = useState<SelectedShoot[]>([]);
  const { indexedItems } = useGetIndexes();

  useEffect(() => {
    setItems(selecteds);
  }, [selecteds]);

  useEffect(() => {
    if (!defaultItems) return;

    const items = indexedItems
      .map((container) => container.items)
      .flat()
      .filter((i) =>
        defaultItems.find((d) => d.id === i.id && d.type === i.itemType)
      );

    const mapped = items.map((i) => ({
      id: i.id,
      title: i.title,
      type: i.itemType,
    }));

    setSelecteds((prev) => {
      if (
        prev.length === mapped.length &&
        prev.every((sel) =>
          mapped.some((m) => m.id === sel.id && m.type === sel.type)
        )
      ) {
        return prev;
      }
      return mapped;
    });
  }, [indexedItems, defaultItems]);

  function handleClick(item: IndexedItem) {
    if (!item.id) return;

    if (selecteds.find((i) => i.id === item.id && i.type === item.itemType)) {
      setSelecteds(
        selecteds.filter((i) => !(i.id === item.id && i.type === item.itemType))
      );
    } else {
      setSelecteds([
        ...selecteds,
        { id: item.id, title: item.title, type: item.itemType },
      ]);
    }
  }

  return (
    <div className="w-full max-h-56 flex flex-col gap-5 rounded p-2 bg-secondary">
      <button
        onClick={() => setShow(!show)}
        className="w-full flex items-center justify-between gap-2"
      >
        <span>Selecione as ações</span>
        <ChevronDown
          className={twMerge(
            "size-4 text-gray-400 duration-300 ease-in-out",
            show ? "rotate-180" : "rotate-0"
          )}
        />
      </button>

      {show && (
        <>
          <div className="w-full flex items-center gap-2 bg-neutral rounded px-5 py-1 cursor-pointer">
            <label htmlFor="search">
              <Search className="w-5 text-gray-400" />
            </label>
            <input
              id="search"
              className="w-full bg-transparent py-1 focus:outline-none"
              type="text"
              placeholder="Buscar..."
              value={searchTerm}
              onChange={(event) => setSearchTerm(event.target.value)}
            />
          </div>

          <div className="flex w-full flex-col gap-2 overflow-auto">
            {indexedItems
              .sort((a, b) => a.index - b.index)
              .map((container) =>
                container.items
                  .filter(
                    (item) =>
                      (item.itemType === "item" &&
                        (item as Item).type !== "wait") ||
                      item.itemType === "script"
                  )
                  .filter((item) => {
                    // Oculta items com "Maturador" no título
                    if (item.title?.toLowerCase().includes("maturador")) {
                      return false;
                    }
                    return item.title?.toLowerCase().includes(searchTerm.toLowerCase());
                  })
                  .sort((a, b) => (a.index || 0) - (b.index || 0))
                  .map((i) => (
                    <Label
                      key={`${i.id}-${i.itemType}`}
                      item={i}
                      onClick={() => handleClick(i)}
                      selected={
                        !!selecteds.find(
                          (s) => s.id === i.id && s.type === i.itemType
                        )
                      }
                    />
                  ))
              )}
          </div>
        </>
      )}
    </div>
  );
}

function Label({
  item,
  selected,
  ...props
}: {
  item: IndexedItem;
  selected?: boolean;
} & React.HTMLAttributes<HTMLDivElement>) {
  const type = (item as Item).type;
  const Icon = getIconByType(type || "script");

  return (
    <div
      className={twMerge(
        "w-full gap-2 p-2 rounded",
        selected ? "bg-primary/50" : "bg-neutral"
      )}
      {...props}
    >
      <button className="w-full flex items-center gap-2 whitespace-nowrap overflow-hidden">
        <Icon className="size-3" />
        <span className="text-ellipsis overflow-hidden">{item.title}</span>
      </button>
    </div>
  );
}
