import { twMerge } from "tailwind-merge";
import { getIconByType } from "./header";
import { CSSProperties, useContext } from "react";
import { Step } from "../models/db";
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { HeaderContext } from "./providers/header-context";
import { Settings2 } from "lucide-react";

export default function StepCard({
  item,
  className,
}: {
  item: Step;
  className?: string;
}) {
  const Icon = getIconByType("step");
  const { setActiveItem, setTab } = useContext(HeaderContext);

  const { active, attributes, listeners, setNodeRef, transform, transition } =
    useSortable({ id: item.id! });

  const style: CSSProperties = {
    transform: active
      ? `translate3d(${transform?.x}px, ${transform?.y}px, 0)`
      : CSS.Transform.toString(transform),
    transition,
  };

  function handleClickActive() {
    setActiveItem({ step: item });
    setTab("step");
  }

  return (
    <button
      ref={setNodeRef}
      style={style}
      onClick={handleClickActive}
      className={twMerge(
        "w-full flex items-center justify-between gap-3 rounded p-2 bg-neutral text-foreground",
        className
      )}
      {...attributes}
      {...listeners}
    >
      <div className="flex items-center gap-3 whitespace-nowrap overflow-hidden">
        <Icon className="size-3" fill="currentColor" />
        <span className="text-sm text-ellipsis overflow-hidden">
          {item.title}
        </span>
      </div>
      <div className="flex items-center gap-3">
        <Settings2 className="w-4 min-w-4" />
      </div>
    </button>
  );
}
