import { Upload } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { toBase64 } from "../../lib/to-base64";
import { Item } from "../../models/db";
import { getIconByType } from "../header";
import { useItemSet } from "../hooks/item-set";
import { SelectGroup } from "../selects/group";

const validateErrors = {
  title: "Digite um título!",
  content: "Importe um arquivo!",
};

export default function MenuDocTab({ item }: { item?: Item }) {
  const [file, setFile] = useState<{
    content: string;
    filename: string;
  }>();
  const [fileError, setFileError] = useState<string>();
  const titleRef = useRef<HTMLInputElement>(null);
  const groupRef = useRef<HTMLSelectElement>(null);
  const captionRef = useRef<HTMLTextAreaElement>(null);
  const { saveItem, removeItem, errors } = useItemSet({ item, validateErrors });
  const Icon = getIconByType("doc");

  useEffect(() => {
    if (item?.content && item?.filename) {
      setFile({
        content: item.content,
        filename: item.filename,
      });
    }
  }, [item]);

  async function handleClick() {
    const title = titleRef.current?.value;
    const groupId = Number(groupRef.current?.value);
    const caption = captionRef.current?.value;
    const content = file?.content;
    const filename = file?.filename;

    const newItem: Partial<Item> = {
      type: "doc",
      title,
      content,
      filename,
      caption,
    };

    await saveItem({ newItem, groupId });
  }

  async function handleFileChange(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];

    if (file) {
      const twentyMB = 20 * 1024 * 1024;
      if (file.size > twentyMB) {
        setFile(undefined);
        setFileError("O arquivo excede 20 MB. Escolha um arquivo menor.");
        return;
      }

      setFileError(undefined);
      const content = await toBase64(file);
      setFile({ filename: file.name, content });
    }
  }

  return (
    <div className="w-full h-full flex flex-col items-center gap-5 overflow-auto">
      <div className="w-full flex items-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
        <Icon className="size-4" />
        <span className="text-center text-sm">Configurar documento</span>
      </div>

      <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <label htmlFor="title">Título</label>
        <input
          ref={titleRef}
          type="text"
          id="title"
          defaultValue={item?.title}
          className="w-full rounded p-2 bg-secondary focus:outline-none"
          placeholder="Digite um título..."
        />
        {errors.title && <p className="text-red-500">{errors.title}</p>}

        <label htmlFor="content">Importar arquivo</label>
        <div className="w-full flex items-center justify-center">
          <label
            htmlFor="dropzone-file"
            className="w-full h-24 flex flex-col items-center justify-center gap-3 rounded cursor-pointer bg-secondary p-2"
          >
            <Upload className="size-8" />
            <input
              id="dropzone-file"
              type="file"
              className="hidden"
              onChange={handleFileChange}
            />
            {file && (
              <span className="text-sm text-gray-400 truncate w-full text-center">
                {file.filename}
              </span>
            )}
          </label>
        </div>

        {errors.content ||
          (fileError && (
            <p className="text-red-500">{errors.content || fileError}</p>
          ))}
      </div>

      <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <label htmlFor="caption">Legenda</label>
        <textarea
          ref={captionRef}
          name="caption"
          id="caption"
          rows={2}
          defaultValue={item?.caption}
          className="rounded p-2 bg-secondary focus:outline-none"
          placeholder="Digite uma legenda..."
        ></textarea>
      </div>

      <SelectGroup ref={groupRef} defaultId={item?.id} />

      {item && (
        <button
          onClick={removeItem}
          className="w-full bg-neutral text-red-500 text-center p-2 rounded"
        >
          Excluir
        </button>
      )}

      <button
        onClick={handleClick}
        className="w-full bg-primary text-white text-center p-2 rounded"
      >
        Salvar
      </button>
    </div>
  );
}
