import { ChevronDown, MessageSquare, Search, X } from "lucide-react";
import { useCallback, useEffect, useState } from "react";
import { twMerge } from "tailwind-merge";

type Chat = {
  id: string;
  name: string;
  participants?: number;
};

function getGroups(canSend = false): Promise<Chat[]> {
  return new Promise((resolve) => {
    const handler = (e: Event) => {
      const { data } = (e as CustomEvent<{ data: Chat[] }>).detail;

      if (data) {
        window.removeEventListener("getGroupsComplete", handler);
        resolve(data);
      }
    };

    window.addEventListener("getGroupsComplete", handler);
    window.dispatchEvent(new CustomEvent("getGroups", { detail: { canSend } }));
  });
}

export default function ChatsSelect({
  setItems,
  label = "Selecionar",
  defaultItem,
  withoutParticipants = false,
  canSend = true,
}: {
  label?: string;
  setItems: (selecteds: string[]) => void;
  defaultItem?: string[];
  withoutParticipants?: boolean;
  canSend?: boolean;
}) {
  const [show, setShow] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [chats, setChats] = useState<Chat[]>([]);
  const [selecteds, setSelecteds] = useState<string[]>(defaultItem || []);
  const [visibleCount, setVisibleCount] = useState(12);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    setIsLoading(true);
    getGroups(canSend)
      .then((groups) => {
        setChats(groups);
      })
      .finally(() => {
        setIsLoading(false);
      });
  }, []);

  useEffect(() => {
    // Propagate selection changes upstream; setItems is treated as stable
    setItems(selecteds);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selecteds]);

  // Resetar visibleCount quando searchTerm mudar
  useEffect(() => {
    setVisibleCount(12);
  }, [searchTerm]);

  const handleClick = useCallback((itemId: string) => {
    setSelecteds((prev) =>
      prev.includes(itemId)
        ? prev.filter((id) => id !== itemId)
        : [...prev, itemId]
    );
  }, []);

  const handleClearSearch = useCallback(() => {
    setSearchTerm("");
  }, []);

  const handleLoadMore = useCallback(() => {
    setVisibleCount((prev) => prev + 12);
  }, []);

  // Filtrar chats baseado no termo de pesquisa
  const filteredChats = chats.filter((chat) =>
    chat.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Aplicar limite de visibilidade
  const visibleChats = filteredChats.slice(0, visibleCount);

  return (
    <div className="w-full max-h-80 flex flex-col gap-5 rounded p-2 bg-secondary text-sm">
      <button
        onClick={() => setShow(!show)}
        className="w-full flex items-center justify-between gap-2"
      >
        <span>{label}</span>
        <ChevronDown
          className={twMerge(
            "size-4 text-gray-400 duration-300 ease-in-out",
            show ? "rotate-180" : "rotate-0"
          )}
        />
      </button>

      {show && (
        <>
          <div className="w-full flex items-center gap-2 bg-neutral rounded px-5 py-1">
            <label htmlFor="search" className="cursor-pointer">
              <Search className="w-5 text-gray-400" />
            </label>
            <input
              id="search"
              className="w-full bg-transparent py-1 focus:outline-none"
              type="text"
              placeholder="Buscar..."
              value={searchTerm}
              onChange={(event) => setSearchTerm(event.target.value)}
            />
            {searchTerm && (
              <button
                onClick={handleClearSearch}
                className="text-gray-400 hover:text-white transition-colors"
              >
                <X className="w-4" />
              </button>
            )}
          </div>

          <div className="flex flex-col h-full overflow-auto gap-y-1">
            {isLoading ? (
              <div className="w-full text-center py-4 text-gray-400">
                Carregando grupos...
              </div>
            ) : filteredChats.length === 0 ? (
              <div className="w-full text-center py-4 text-gray-400">
                {searchTerm
                  ? "Nenhum grupo encontrado"
                  : "Nenhum grupo disponível"}
              </div>
            ) : (
              <div className="flex w-full flex-col gap-2">
                {visibleChats.map((item) => (
                  <Label
                    key={item.id}
                    item={item}
                    selected={selecteds.includes(item.id)}
                    onClick={() => handleClick(item.id)}
                    withoutParticipants={withoutParticipants}
                  />
                ))}
              </div>
            )}

            {!isLoading && visibleCount < filteredChats.length && (
              <button
                onClick={handleLoadMore}
                className="w-full mt-2 p-2 bg-primary text-white rounded hover:bg-primary/90 transition-colors"
              >
                Ver mais
              </button>
            )}
          </div>
        </>
      )}
    </div>
  );
}

function Label({
  item,
  selected,
  withoutParticipants = false,
  ...props
}: {
  item: Chat;
  selected?: boolean;
  withoutParticipants?: boolean;
} & React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={twMerge(
        "w-full gap-2 p-2 rounded transition-colors",
        selected
          ? "bg-primary/50 hover:bg-primary/60"
          : "bg-neutral hover:bg-neutral/80"
      )}
      {...props}
    >
      <button className="w-full flex items-center justify-between gap-2">
        <div className="w-full flex items-center gap-2 whitespace-nowrap overflow-hidden">
          <MessageSquare className="size-3" />
          <span className="text-ellipsis overflow-hidden">{item.name}</span>
        </div>
        {item.participants && !withoutParticipants && (
          <span className="font-bold text-xs bg-neutral px-2 py-1 rounded">
            {item.participants}
          </span>
        )}
      </button>
    </div>
  );
}
