import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import Header from "./components/header";
import { HeaderProvider } from "./components/providers/header-context";
import {
  Session,
  SessionProvider,
} from "./components/providers/session-context";
import StepChatButton from "./components/step-chat-button";
import { ScriptWait } from "./components/tabs/script";
import { SheduleShoot } from "./components/tabs/shoot";
import {
  getSelectedItems,
  getShootingById,
} from "./components/utils/functions";
import { REVZAP_WINDOW_EVENTS } from "../core/bridge/windowEvents";
import db from "./models/db";

export function addHeader() {
  const element = document.getElementById("ext-header");

  if (element) {
    const elementRoot = createRoot(element);

    elementRoot.render(
      <StrictMode>
        <SessionProvider>
          <HeaderProvider>
            <Header />
          </HeaderProvider>
        </SessionProvider>
      </StrictMode>,
    );
  }
}

export function changeChat() {
  let chatButtonsRoot: ReturnType<typeof createRoot> | undefined;

  const observer = new MutationObserver((mutations) => {
    mutations.forEach(() => {
      const elementFooter = document.querySelector("footer");

      if (elementFooter) {
        if (document.getElementById("ext-footer")) return;

        const newElement = document.createElement("div");
        newElement.id = "ext-footer";
        elementFooter.appendChild(newElement);
      }

      let elementButtons = null;

      elementButtons = document.querySelector(
        '#main header div:has(> div > [role="button"]):nth-child(1)',
      );

      const headerDiv = document.querySelector(
        "#main header > div.x1c4vz4f.x2lah0s.xdl72j9.xqsn43r > div.x78zum5.x6s0dn4.x1afcbsf.x14ug900",
      );

      // Data: 19/12/2025
      // Segunda tentativa, caso a primeira falhe devido a mudanças no layout.
      // O icone etapas havia parada de ser injetado.
      const root = document.querySelector(".x1c4vz4f.x2lah0s.xdl72j9.xlese2p");
      const secondChance =
        root?.querySelector(".x78zum5.x6s0dn4.x1afcbsf.x14ug900") ?? null;

      if (headerDiv) {
        elementButtons = headerDiv;
      } else if (secondChance) {
        // Data: 19/12/2025
        elementButtons = secondChance;
      }

      if (elementButtons && !document.getElementById("ext-chat-buttons")) {
        const newElement = document.createElement("div");
        newElement.className = "flex items-center";
        newElement.id = "ext-chat-buttons";
        newElement.title = "Adicione este chat a uma etapa do seu processo";

        if (elementButtons.firstElementChild) {
          elementButtons.insertBefore(
            newElement,
            elementButtons.firstElementChild,
          );
        } else {
          elementButtons.appendChild(newElement);
        }

        chatButtonsRoot = createRoot(newElement);

        chatButtonsRoot.render(
          <StrictMode>
            <div className="flex items-center gap-2">
              <StepChatButton />
            </div>
          </StrictMode>,
        );
      } else {
        if (chatButtonsRoot) {
          chatButtonsRoot.unmount();
          chatButtonsRoot = undefined;
        }
      }
    });
  });

  const elementObserver = document.querySelector("#app");

  if (elementObserver) {
    observer.observe(elementObserver, {
      childList: true,
      subtree: true,
    });
  }
}

let triggerScheduled = false;
let isStarting = false;

function scheduleStartTriggers() {
  if (triggerScheduled) return;

  triggerScheduled = true;

  setTimeout(async () => {
    await startTriggers();
    triggerScheduled = false;
  }, 100);
}

async function checkSession() {
  return await chrome.runtime
    .sendMessage({ action: "session" })
    .then((response) => {
      let session: Session;

      if (response?.logged) {
        session = response;
      } else {
        session = { logged: false };
      }

      return session;
    });
}

window.addEventListener(REVZAP_WINDOW_EVENTS.Session.CheckRequest, async () => {
  const session = await checkSession();

  window.dispatchEvent(
    new CustomEvent(REVZAP_WINDOW_EVENTS.Session.CheckComplete, {
      detail: { session },
    }),
  );
});

function removeFunctions(obj: any) {
  return JSON.parse(
    JSON.stringify(obj, (key, value) =>
      typeof value === "function" ? undefined : value,
    ),
  );
}

export async function startTriggers() {
  if (isStarting) return;
  isStarting = true;

  try {
    const triggers = await db.shotTriggers.toArray();

    const transformedTriggers = [];

    for (const trigger of triggers) {
      const transformedItems = [];

      for (const item of trigger.items) {
        const selectedItems = await getSelectedItems([
          {
            id: item.id,
            type: item.type,
          },
        ]);

        transformedItems.push(selectedItems[0]);
      }

      transformedTriggers.push({
        ...trigger,
        items: transformedItems,
      });
    }

    window.dispatchEvent(
      new CustomEvent(REVZAP_WINDOW_EVENTS.Triggers.Start, {
        detail: { triggers: transformedTriggers },
      }),
    );
  } finally {
    isStarting = false;
  }
}

export async function startSheduleShoots() {
  const result = await chrome.storage.local.get("sheduleShoots");
  const sheduleShoots: SheduleShoot[] = result.sheduleShoots || [];

  try {
    for (const shootId of sheduleShoots) {
      const scheduledDate = new Date(shootId.schedule);
      const now = new Date();

      // dif in ms: positive => scheduledDate in future, negative => past
      const diffMs = scheduledDate.getTime() - now.getTime();

      // Considera como "perdido" apenas se estiver muito no passado (> 1 minuto)
      if (diffMs < -60000) {
        window.dispatchEvent(
          new CustomEvent(REVZAP_WINDOW_EVENTS.Errors.ShowErrorMessage, {
            detail: {
              message:
                "Você tem um disparo agendado que foi realizado enquanto o navegador estava fechado.",
            },
          }),
        );

        const updatedSheduleShoots = sheduleShoots.filter(
          (item) =>
            item.triggerId !== shootId.triggerId ||
            item.schedule !== shootId.schedule,
        );

        await chrome.storage.local.set({ sheduleShoots: updatedSheduleShoots });

        continue;
      }

      // Se a data já chegou (ou chegou há menos de 1 minuto), dispare imediatamente
      if (diffMs <= 0) {
        const shoot = await getShootingById(Number(shootId.triggerId));

        if (!shoot?.items) {
          // Remove entrada inválida
          const updatedSheduleShoots = sheduleShoots.filter(
            (item) =>
              item.triggerId !== shootId.triggerId ||
              item.schedule !== shootId.schedule,
          );
          await chrome.storage.local.set({
            sheduleShoots: updatedSheduleShoots,
          });
          continue;
        }

        const items = await getSelectedItems(shoot?.items);

        // Dispara o evento para iniciar o envio imediatamente
        window.dispatchEvent(
          new CustomEvent(REVZAP_WINDOW_EVENTS.Schedules.StartSheduleShoots, {
            detail: { shoot, schedule: shootId.schedule, items },
          }),
        );

        // Remove a entrada para não processá-la novamente
        const updatedSheduleShoots = sheduleShoots.filter(
          (item) =>
            item.triggerId !== shootId.triggerId ||
            item.schedule !== shootId.schedule,
        );

        await chrome.storage.local.set({ sheduleShoots: updatedSheduleShoots });

        continue;
      }

      // Data no futuro -> agenda via evento que criará um interval
      const shoot = await getShootingById(Number(shootId.triggerId));

      if (!shoot?.items) continue;

      const items = await getSelectedItems(shoot?.items);

      if (shoot) {
        window.dispatchEvent(
          new CustomEvent(REVZAP_WINDOW_EVENTS.Schedules.StartSheduleShoots, {
            detail: { shoot, schedule: shootId.schedule, items },
          }),
        );
      }
    }
  } catch (error) {
    console.error(error);
    window.dispatchEvent(
      new CustomEvent(REVZAP_WINDOW_EVENTS.Errors.ShowErrorMessage, {
        detail: {
          message:
            "Erro ao iniciar disparos agendados, entre em contato com o suporte",
        },
      }),
    );
  }
}

export async function getActiveScriptWait() {
  const result = await chrome.storage.local.get("activeScriptWait");
  const activeScriptWait = result.activeScriptWait as ScriptWait[];

  if (
    !activeScriptWait ||
    !Array.isArray(activeScriptWait) ||
    activeScriptWait.length === 0
  )
    return;

  for (const wait of activeScriptWait) {
    const item = await getSelectedItems([
      {
        id: wait.scriptId,
        type: "script",
      },
    ]);

    window.dispatchEvent(
      new CustomEvent(REVZAP_WINDOW_EVENTS.ScriptWait.Start, {
        detail: { ...wait, script: item[0], isTrigger: false },
      }),
    );
  }
}

db.shotTriggers.hook("updating", (modifications, primKey, obj, transaction) => {
  const safeModifications = removeFunctions(modifications);

  transaction.on?.("complete", () => {
    scheduleStartTriggers();
  });

  return safeModifications;
});
