import { Upload, Plus, Trash2, Loader } from "lucide-react";
import { useContext, useEffect, useRef, useState } from "react";
import db, { Shoot, ShootItem } from "../../models/db";
import ChatsSelect from "../chats-select";
import { getIconByType } from "../header";
import { useShootSet } from "../hooks/shoot-set";
import ItemsSelect from "../items-select";
import { HeaderContext } from "../providers/header-context";
import StepsSelect from "../steps-select";
import {
  getAllChats,
  getGroupsDetails,
  getParticipantsOnGroup,
  getSelectedItems,
  getStepById,
} from "../utils/functions";

export type SelectedShoot = {
  id: number | undefined;
  title: string;
  type: "item" | "script";
};

type ActionGroup = {
  groupId: string;
  items: SelectedShoot[];
};

export type ContactSource = {
  type: "group" | "step" | "spreadsheet" | "selectedGroups" | "allContacts";
  ids: string[] | number[];
};

export type ShootContact = {
  chatId: string;
  userId?: string;
  source?: ContactSource;
  server?: string | null;
};

export type ShootingChat = ShootContact & {
  sent?: boolean;
  error?: boolean;
  server: string;
};

export type SheduleShoot = {
  schedule: string;
  triggerId: string;
};

const validateErrors = {
  title: "Digite um título!",
  interval1: "Digite um intervalo!",
  items: "Selecione ao menos uma ação!",
};

// Funções auxiliares para conversão de unidades de tempo
const convertToSeconds = (
  value: number,
  unit: "segundos" | "minutos" | "horas",
): number => {
  switch (unit) {
    case "minutos":
      return value * 60;
    case "horas":
      return value * 3600;
    default:
      return value;
  }
};

const convertFromSeconds = (
  seconds: number,
  unit: "segundos" | "minutos" | "horas",
): number => {
  switch (unit) {
    case "minutos":
      return seconds / 60;
    case "horas":
      return seconds / 3600;
    default:
      return seconds;
  }
};

export default function MenuShootTab({ item }: { item?: Shoot }) {
  const [state, setState] = useState({
    itemsSelected: [] as SelectedShoot[],
    withAdmin: false,
    withSpredsheet: false,
    diynamicInterval: false,
    withGroups: false,
    withSteps: false,
    withSelectedGroups: false,
    withAllContacts: false,
    chats: [] as string[],
    steps: [] as number[],
    date: "",
    time: "",
    showSchedule: false,
    contacts: undefined as { id: string; server?: string | null }[] | undefined,
    interval1Unit: "segundos" as "segundos" | "minutos" | "horas",
    interval2Unit: "segundos" as "segundos" | "minutos" | "horas",
    randomizeActions: false,
    actionGroups: [
      { groupId: crypto.randomUUID(), items: [] },
    ] as ActionGroup[],
  });
  const [isSubmittingShoot, setIsSubmittingShoot] = useState(false);

  const refs = {
    titleRef: useRef<HTMLInputElement>(null),
    interval1Ref: useRef<HTMLInputElement>(null),
    interval2Ref: useRef<HTMLInputElement>(null),
    dateRef: useRef<HTMLInputElement>(null),
    timeRef: useRef<HTMLInputElement>(null),
    stepsRef: useRef<HTMLDivElement>(null),
    chatsRef: useRef<HTMLDivElement>(null),
    contactsRef: useRef<HTMLDivElement>(null),
    itemsRef: useRef<HTMLDivElement>(null),
    groupsSectionRef: useRef<HTMLDivElement>(null),
    stepsSectionRef: useRef<HTMLDivElement>(null),
    spreadsheetSectionRef: useRef<HTMLDivElement>(null),
    selectedGroupsRef: useRef<HTMLDivElement>(null),
    allContactsRef: useRef<HTMLDivElement>(null),
  };

  const { setTab, setActiveItem } = useContext(HeaderContext);
  const Icon = getIconByType("shoot");
  const isShooting = item?.status === "shooting";
  const { saveItem, removeItem, errors, setErrors } = useShootSet({
    item,
    validateErrors,
  });

  useEffect(() => {
    if (item) {
      setState((prevState) => ({
        ...prevState,
        withAdmin: false,
        withSpredsheet: false,
        diynamicInterval: false,
        withGroups: false,
        withSelectedGroups: false,
        withSteps: false,
        withAllContacts: false,
      }));

      if (item?.schedule) {
        const d = new Date(item.schedule);
        setState((prevState) => ({
          ...prevState,
          date: d.toISOString().slice(0, 10),
          time: d.toTimeString().slice(0, 5),
          showSchedule: true,
        }));
      }

      if (item?.contacts?.length) {
        const groupContacts = item.contacts.filter(
          (contact) => (contact as ShootContact).source?.type === "group",
        );
        const stepContacts = item.contacts.filter(
          (contact) => (contact as ShootContact).source?.type === "step",
        );
        const spreadsheetContacts = item.contacts.filter(
          (contact) => (contact as ShootContact).source?.type === "spreadsheet",
        );
        const selectedGroupsContacts = item.contacts.filter(
          (contact) =>
            (contact as ShootContact).source?.type === "selectedGroups",
        );

        const allContactsContacts = item.contacts.filter(
          (contact) => (contact as ShootContact).source?.type === "allContacts",
        );

        if (groupContacts.length > 0) {
          setState((prevState) => ({
            ...prevState,
            withGroups: true,
            chats: groupContacts.map((contact) => contact.chatId),
          }));
        }

        if (stepContacts.length > 0) {
          setState((prevState) => ({
            ...prevState,
            withSteps: true,
            steps:
              ((stepContacts[0] as ShootContact).source?.ids as number[]) || [],
          }));
        }

        if (selectedGroupsContacts.length > 0) {
          setState((prevState) => ({
            ...prevState,
            withSelectedGroups: true,
            contacts: selectedGroupsContacts.map((contact) => ({
              id: contact.chatId,
              server: contact.server || "@c.us",
            })),
          }));
        }

        if (spreadsheetContacts.length > 0) {
          setState((prevState) => ({
            ...prevState,
            withSpredsheet: true,
            contacts: spreadsheetContacts.map((contact) => ({
              id: contact.chatId,
              server: contact.server || "@c.us",
            })),
          }));
        }

        if (allContactsContacts.length > 0) {
          setState((prevState) => ({
            ...prevState,
            withAllContacts: true,
            contacts: allContactsContacts.map((contact) => ({
              id: contact.chatId,
              server: contact.server || "@c.us",
            })),
          }));
        }
      }

      if (item?.interval?.length) {
        if (refs.interval1Ref.current) {
          refs.interval1Ref.current.value = item.interval[0].toString();
        }

        if (item.interval.length === 2) {
          setState((prevState) => ({
            ...prevState,
            diynamicInterval: true,
          }));

          if (refs.interval2Ref.current) {
            refs.interval2Ref.current.value = item.interval[1].toString();
          }
        }
      }

      if ((item as any).randomizeActions && (item as any).actionGroups) {
        setState((prevState) => ({
          ...prevState,
          randomizeActions: true,
          actionGroups: (item as any).actionGroups.map((group: any[]) => ({
            groupId: crypto.randomUUID(),
            items: group.map((g: any) => ({
              id: g.id,
              title: "",
              type: g.type,
            })),
          })),
        }));
      }
    }
  }, [item]);

  const scrollToElement = (element: HTMLElement) => {
    element.scrollIntoView({
      behavior: "smooth",
      block: "center",
    });
  };

  useEffect(() => {
    if (errors.title && refs.titleRef.current) {
      scrollToElement(refs.titleRef.current);
    } else if (errors.interval && refs.interval1Ref.current) {
      scrollToElement(refs.interval1Ref.current);
    } else if (errors.chats && refs.groupsSectionRef.current) {
      scrollToElement(refs.groupsSectionRef.current);
    } else if (errors.steps && refs.stepsSectionRef.current) {
      scrollToElement(refs.stepsSectionRef.current);
    } else if (errors.contacts && refs.spreadsheetSectionRef.current) {
      scrollToElement(refs.spreadsheetSectionRef.current);
    } else if (errors.items && refs.itemsRef.current) {
      scrollToElement(refs.itemsRef.current);
    } else if (errors.date && refs.dateRef.current) {
      scrollToElement(refs.dateRef.current);
    } else if (errors.target && refs.chatsRef.current) {
      scrollToElement(refs.chatsRef.current);
    } else if (errors.selectedGroups && refs.selectedGroupsRef.current) {
      scrollToElement(refs.selectedGroupsRef.current);
    } else if (errors.allContacts && refs.allContactsRef.current) {
      scrollToElement(refs.allContactsRef.current);
    }
  }, [errors]);

  async function handleOptionChange(option: string) {
    switch (option) {
      case "groups":
        setState((prevState) => ({
          ...prevState,
          withGroups: !prevState.withGroups,
          chats: prevState.withGroups ? [] : prevState.chats,
        }));
        break;
      case "steps":
        setState((prevState) => ({
          ...prevState,
          withSteps: !prevState.withSteps,
          steps: prevState.withSteps ? [] : prevState.steps,
        }));
        break;
      case "spreadsheet":
        setState((prevState) => ({
          ...prevState,
          withSpredsheet: !prevState.withSpredsheet,
          contacts: prevState.withSpredsheet ? undefined : prevState.contacts,
        }));
        break;
      case "selectedGroups":
        setState((prevState) => ({
          ...prevState,
          withSelectedGroups: !prevState.withSelectedGroups,
          contacts: prevState.withSelectedGroups ? [] : prevState.contacts,
        }));
        break;
      case "allContacts": {
        const allChats = await getAllChats("all", false);

        if (allChats && allChats.length > 0) {
          setState((prevState) => ({
            ...prevState,
            withAllContacts: !prevState.withAllContacts,

            contacts: allChats.map((chat) => ({
              id: chat.id,
              server: chat.server,
            })),
          }));
        }

        break;
      }
    }
  }

  async function handleClick(shooting?: boolean) {
    if (shooting) {
      if (isSubmittingShoot) return;
      setIsSubmittingShoot(true);
    }

    try {
      const title = refs.titleRef.current?.value;
      const interval1 = refs.interval1Ref.current?.value;
      const interval2 = refs.interval2Ref.current?.value;

      const errors: { [key: string]: string } = {};
      const interval = [1];

      if (!title) {
        errors.title = "Digite um título!";
      }

      if (!interval1 || Number(interval1) < 1) {
        errors.interval = "O intervalo deve ser maior que 0!";
      } else {
        const value = Number(interval1);
        interval[0] = convertToSeconds(value, state.interval1Unit);
      }

      if (state.diynamicInterval) {
        if (!interval2 || Number(interval2) < 1) {
          errors.interval = "O intervalo final deve ser maior que 0!";
        } else {
          const value1 = convertToSeconds(
            Number(interval1),
            state.interval1Unit,
          );
          const value2 = convertToSeconds(
            Number(interval2),
            state.interval2Unit,
          );

          if (value2 <= value1) {
            errors.interval = "O intervalo final deve ser maior que o inicial!";
          } else {
            interval[1] = value2;
          }
        }
      }

      if (
        !state.withGroups &&
        !state.withSteps &&
        !state.withSpredsheet &&
        !state.withSelectedGroups &&
        !state.withAllContacts
      ) {
        errors.target = "Selecione pelo menos uma opção de alvo!";
      } else {
        if (state.withGroups && state.chats.length === 0) {
          errors.chats = "Selecione ao menos uma pasta!";
        }

        if (state.withSteps && state.steps.length === 0) {
          errors.steps = "Selecione ao menos uma etapa!";
        }

        if (state.withSpredsheet && !state.contacts?.length) {
          errors.contacts = "Selecione uma planilha com contatos válidos!";
        }

        if (state.withSelectedGroups && !state.chats?.length) {
          errors.selectedGroups = "Selecione ao menos um grupo!";
        }
      }

      if (!state.randomizeActions) {
        if (!state.itemsSelected.length) {
          errors.items = "Selecione ao menos uma ação!";
        }
      } else {
        const hasEmptyGroup = state.actionGroups.some(
          (group) => group.items.length === 0,
        );
        if (hasEmptyGroup || state.actionGroups.length === 0) {
          errors.items =
            "Cada grupo deve ter ao menos uma ação! Remova grupos vazios.";
        }
      }

      if (state.showSchedule) {
        if (!state.date || !state.time) {
          errors.date = "Preencha a data e a hora para agendar o disparo.";
        } else {
          const schedule = `${state.date}T${state.time}`;
          const now = new Date();
          const scheduled = new Date(schedule);

          if (scheduled < now) {
            errors.date =
              "A data e hora agendadas devem ser posteriores ao momento atual.";
          } else {
            if (schedule) {
              const existing = await db.shoots
                .where("schedule")
                .equals(schedule)
                .first();

              if (existing && (!item || existing.id !== item.id)) {
                errors.date =
                  "Já existe um disparo agendado para este dia e hora.";
              }
            }
          }
        }
      }

      const finalContacts: ShootContact[] = [];

      // Buscar participantes de grupos
      if (state.withGroups && state.chats && state.chats.length > 0) {
        const participants = await getParticipantsOnGroup(
          state.chats,
          state.withAdmin,
        );

        if (participants.length === 0) {
          errors.chats =
            "Nenhum participante encontrado nos grupos selecionados. Verifique se os grupos possuem membros.";
          setErrors(errors);
          return;
        }

        const groupContacts = participants.map((participant) => {
          return {
            chatId: participant.id.replace("@c.us", ""),
            userId: participant.id.replace("@c.us", "")?.replace("@g.us", ""),
            source: {
              type: "group" as const,
              ids: state.chats,
            },
            server: participant.server || "@c.us",
          };
        });
        finalContacts.push(...groupContacts);
      }

      // Buscar usuários das etapas
      if (state.withSteps && state.steps && state.steps.length > 0) {
        const stepUsers = new Map<
          string,
          { chatId: string; stepIds: number[] }
        >();

        for (const stepId of state.steps) {
          const step = await getStepById(stepId);

          if (!step) continue;

          if (!step.users || step.users.length === 0) {
            errors.steps = `A etapa selecionada não possui usuários.`;
            setErrors(errors);
            return;
          }

          step.users.forEach((user) => {
            if (!user || typeof user !== "string") {
              return;
            }

            const cleanChatId = user.replace("@c.us", "");

            if (!stepUsers.has(cleanChatId)) {
              stepUsers.set(cleanChatId, {
                chatId: cleanChatId,
                stepIds: [stepId],
              });
            } else {
              const existing = stepUsers.get(cleanChatId);
              if (existing) {
                existing.stepIds.push(stepId);
              }
            }
          });
        }

        const stepContacts = Array.from(stepUsers.values()).map(
          ({ chatId, stepIds }) => {
            return {
              chatId,
              userId: chatId.replace("@g.us", ""),
              source: {
                type: "step" as const,
                ids: stepIds,
              },
              server: chatId.includes("@g.us")
                ? "@g.us"
                : chatId.includes("@lid")
                  ? "@lid"
                  : "@c.us",
            };
          },
        );
        finalContacts.push(...stepContacts);
      }

      // Adicionar contatos da planilha
      if (state.withSpredsheet && state.contacts && state.contacts.length > 0) {
        const spreadsheetContacts = state.contacts.map((participant) => {
          return {
            chatId: participant.id
              .replace("@c.us", "")
              .replace("@g.us", "")
              .replace("@lid", ""),
            userId: participant.id
              .replace("@c.us", "")
              ?.replace("@g.us", "")
              .replace("@lid", ""),
            source: {
              type: "spreadsheet" as const,
              ids: [],
            },
            server: participant.server || "@c.us",
          };
        });
        finalContacts.push(...spreadsheetContacts);
      }

      // Adicionar grupos selecionados
      if (state.withSelectedGroups && state.chats && state.chats.length > 0) {
        const groupsDetails = await getGroupsDetails(state.chats);

        const selectedGroupsContacts = groupsDetails.map((group) => {
          return {
            chatId: group.id,
            userId: group.name,
            server: "@g.us",
            source: {
              type: "selectedGroups" as const,
              ids: state.chats,
            },
          };
        });
        finalContacts.push(...selectedGroupsContacts);
      }

      // Adicionar todos os contatos
      if (
        state.withAllContacts &&
        state.contacts &&
        state.contacts.length > 0
      ) {
        const allContactsMapped = state.contacts.map((contact) => {
          return {
            chatId: contact.id,
            userId: contact.id.replace("@c.us", "")?.replace("@g.us", ""),
            server: contact.server || "@c.us",
            source: {
              type: "allContacts" as const,
              ids: [],
            },
          };
        });
        finalContacts.push(...allContactsMapped);
      }

      // Remover duplicados por chatId+server
      const uniqueContactsMap = new Map<string, ShootContact>();

      for (const contact of finalContacts) {
        const normalizedChatId = contact.chatId
          .replace("@c.us", "")
          .replace("@g.us", "")
          .replace("@lid", "");

        const normalizedServer = contact.server || "@c.us";
        const key = `${normalizedChatId}|${normalizedServer}`;

        if (!uniqueContactsMap.has(key)) {
          uniqueContactsMap.set(key, {
            ...contact,
            chatId: normalizedChatId,
            server: normalizedServer,
          });
        }
      }

      const deduplicatedContacts = Array.from(uniqueContactsMap.values());

      setErrors(errors);

      const schedule =
        state.date && state.time ? `${state.date}T${state.time}` : undefined;

      const newItem = {
        title,
        contacts: deduplicatedContacts ?? item?.contacts,
        interval,
        items: state.randomizeActions
          ? []
          : state.itemsSelected.map(({ id, type }) => ({
              id: id || 0,
              type,
            })),
        status: item?.status || undefined,
        schedule,
        withAdmin: state.withAdmin,
        randomizeActions: state.randomizeActions,
        actionGroups: state.randomizeActions
          ? state.actionGroups.map((group) =>
              group.items.map(({ id, type }) => ({
                id: id || 0,
                type,
              })),
            )
          : undefined,
      };

      if (Object.keys(errors).length > 0) return;

      const result = await saveItem({
        newItem,
        errors,
        tab: shooting ? null : "shoot_list",
      });

      if (schedule) {
        const storageResult = await chrome.storage.local.get("sheduleShoots");
        const sheduleShoots =
          storageResult.sheduleShoots || ([] as SheduleShoot[]);

        sheduleShoots.push({
          schedule,
          triggerId: result?.id?.toString() || "",
        } as SheduleShoot);

        await chrome.storage.local.set({ sheduleShoots });

        if (!result) return;

        const items = await getSelectedItems(result?.items);
        let actionGroupsItems: any[][] | undefined;

        if (result?.randomizeActions && result?.actionGroups?.length) {
          const resolvedGroups: any[][] = [];
          for (const group of result.actionGroups as ShootItem[][]) {
            const groupItems = await getSelectedItems(group);
            resolvedGroups.push(groupItems.filter(Boolean));
          }
          actionGroupsItems = resolvedGroups;
        }

        window.dispatchEvent(
          new CustomEvent("startSheduleShoots", {
            detail: {
              shoot: result,
              schedule,
              items,
              randomizeActions: result?.randomizeActions,
              actionGroups: actionGroupsItems,
            },
          }),
        );
      }

      if (shooting && result) {
        setActiveItem({ shoot: result });
        setTab("shooting");
      }
    } finally {
      if (shooting) {
        setIsSubmittingShoot(false);
      }
    }
  }

  function handleFileChange(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];

    if (file) {
      const reader = new FileReader();
      reader.readAsText(file as Blob);

      reader.onload = function () {
        const text = reader.result as string;
        const lines = text.split("\n");

        const validContacts: Set<{ id: string; server: string | null }> =
          new Set();

        lines.forEach((line) => {
          const columns = line.includes(";")
            ? line.split(";")
            : line.split(",");

          if (columns.length > 0) {
            const rawValue = columns[0]?.trim() ?? "";

            const serverMatch = rawValue.match(/@(c\.us|g\.us|lid)$/);
            const server = serverMatch ? serverMatch[0] : null;

            const phoneNumber = rawValue
              .replace(/@(c\.us|g\.us|lid)$/, "")
              .replace(/\D/g, "");

            if (phoneNumber === "") return;

            validContacts.add({
              id: phoneNumber,
              server,
            });
          }
        });

        const arrayContacts = Array.from(validContacts);

        if (arrayContacts.length === 0) {
          setErrors((prev) => ({
            ...prev,
            contacts: "Nenhum contato válido encontrado.",
          }));
          return;
        }

        setState((prev) => ({
          ...prev,
          contacts: arrayContacts,
        }));
      };
    }
  }

  return (
    <div className="w-full h-full flex flex-col items-center gap-5 overflow-auto">
      <div className="w-full flex items-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
        <Icon className="size-4" />
        <span className="text-center text-sm">Configurar disparo</span>
      </div>

      {isShooting ? (
        <p className="text-center text-sm">
          Este disparo já está em andamento. Não é possível editar seu conteúdo
          no momento. Aguarde a finalização para poder realizar alterações.
        </p>
      ) : (
        <>
          <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
            <label htmlFor="title">Título</label>
            <input
              ref={refs.titleRef}
              type="text"
              id="title"
              defaultValue={item?.title}
              className="w-full rounded p-2 bg-secondary focus:outline-none"
              placeholder="Digite um título..."
            />
            {errors.title && <p className="text-red-500">{errors.title}</p>}
          </div>

          <div
            ref={refs.chatsRef}
            className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm"
          >
            <div className="flex flex-col gap-y-2">
              <div className="w-full flex items-center justify-between gap-2">
                <label htmlFor="allContacts" className="w-full">
                  Enviar para todos seus contatos
                </label>
                <div className="relative flex">
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input
                      id="allContacts"
                      type="checkbox"
                      className="sr-only peer/check"
                      checked={state.withAllContacts}
                      onChange={() => handleOptionChange("allContacts")}
                    />
                    <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
                  </label>
                </div>
              </div>
            </div>

            {state.withAllContacts && (
              <div ref={refs.allContactsRef}>
                <span className="text-xs text-gray-400">
                  Esta opção irá enviar para todos os contatos sincronizados com
                  o seu WhatsApp Web. Atualmente, são{" "}
                  <b>{state.contacts?.length || 0}</b> contatos sincronizados.
                </span>
              </div>
            )}

            <div className="flex flex-col gap-y-2">
              <div className="w-full flex items-center justify-between gap-2">
                <label htmlFor="groups" className="w-full">
                  Enviar para usuários de grupos
                </label>
                <div className="relative flex">
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input
                      id="groups"
                      type="checkbox"
                      className="sr-only peer/check"
                      checked={state.withGroups}
                      onChange={() => handleOptionChange("groups")}
                    />
                    <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
                  </label>
                </div>
              </div>
            </div>

            {state.withGroups && (
              <div ref={refs.groupsSectionRef}>
                <ChatsSelect
                  setItems={(chats: string[]) => {
                    setState((prev) => ({ ...prev, chats }));
                  }}
                  defaultItem={Array.from(
                    new Set(
                      item?.contacts
                        ?.filter((contact) => contact.source?.type === "group")
                        .flatMap(
                          (contact) => contact.source?.ids as string[],
                        ) || [],
                    ),
                  )}
                  label="Selecione os grupos"
                  canSend={false}
                />
                {errors.chats && <p className="text-red-500">{errors.chats}</p>}
              </div>
            )}

            <div className="w-full flex items-center justify-between gap-2">
              <label htmlFor="steps" className="w-full">
                Enviar para usuários de etapas
              </label>
              <div className="relative flex">
                <label className="relative inline-flex items-center cursor-pointer">
                  <input
                    id="steps"
                    type="checkbox"
                    className="sr-only peer/check"
                    checked={state.withSteps}
                    onChange={() => handleOptionChange("steps")}
                  />
                  <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
                </label>
              </div>
            </div>

            {state.withSteps && (
              <div ref={refs.stepsSectionRef}>
                <StepsSelect
                  setItems={(steps: number[]) =>
                    setState((prev) => ({ ...prev, steps }))
                  }
                  defaultItem={Array.from(
                    new Set(
                      item?.contacts
                        ?.filter((contact) => contact.source?.type === "step")
                        .flatMap(
                          (contact) => contact.source?.ids as number[],
                        ) || [],
                    ),
                  )}
                />
                {errors.steps && <p className="text-red-500">{errors.steps}</p>}
              </div>
            )}

            <div className="flex flex-col gap-y-2 w-full">
              <div className="w-full flex items-center justify-between gap-2">
                <label htmlFor="spreadsheet" className="w-full">
                  Importar contatos de planilha
                </label>
                <div className="relative flex">
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input
                      id="spreadsheet"
                      type="checkbox"
                      className="sr-only peer/check"
                      checked={state.withSpredsheet}
                      onChange={() => handleOptionChange("spreadsheet")}
                    />
                    <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
                  </label>
                </div>
              </div>
            </div>

            {state.withSpredsheet && (
              <div ref={refs.spreadsheetSectionRef}>
                <span className="text-xs text-gray-400">
                  Baixe este documento para entender melhor esta funcionalidade.{" "}
                  <a
                    className="text-primary underline"
                    target="_blank"
                    rel="noreferrer"
                    href="https://docs.google.com/spreadsheets/d/1v8RaSebq402AxNOZcjFCnSpLvWS0tYtQlRwYdmoplZE/edit?usp=sharing"
                  >
                    Exemplo de planilha
                  </a>
                </span>
                <div className="w-full flex items-center justify-center">
                  <label
                    htmlFor="dropzone-file"
                    className="w-full min-h-24 flex flex-col items-center justify-center gap-3 rounded cursor-pointer bg-secondary p-2"
                  >
                    <div className="flex flex-col items-center gap-1">
                      <Upload className="size-8" />
                      <span className="text-center">.csv</span>
                    </div>
                    <input
                      id="dropzone-file"
                      type="file"
                      accept=".csv"
                      className="hidden"
                      onChange={handleFileChange}
                    />
                    {state.contacts && state.contacts.length > 0 && (
                      <span className="text-sm text-gray-400 truncate w-full text-center">
                        {" "}
                        <b>{state.contacts.length || 0}</b> contatos importados.
                      </span>
                    )}
                  </label>
                </div>
                <span className="text-xs text-gray-400">
                  Os números de telefone devem conter apenas dígitos, com entre
                  11 e 15 números no total (incluindo DDI e número). Ex:{" "}
                  <code>5511999999999</code>
                </span>
                {errors.contacts && (
                  <p className="text-red-500">{errors.contacts}</p>
                )}
              </div>
            )}

            <div className="flex flex-col gap-y-2">
              <div className="w-full flex items-center justify-between gap-2">
                <label htmlFor="selectedGroups" className="w-full">
                  Enviar para grupos
                </label>
                <div className="relative flex">
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input
                      id="selectedGroups"
                      type="checkbox"
                      className="sr-only peer/check"
                      checked={state.withSelectedGroups}
                      onChange={() => handleOptionChange("selectedGroups")}
                    />
                    <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
                  </label>
                </div>
              </div>
            </div>

            {state.withSelectedGroups && (
              <div ref={refs.selectedGroupsRef}>
                <ChatsSelect
                  setItems={(chats: string[]) => {
                    setState((prev) => ({ ...prev, chats }));
                  }}
                  defaultItem={Array.from(
                    new Set(
                      item?.contacts
                        ?.filter(
                          (contact) =>
                            contact.source?.type === "selectedGroups",
                        )
                        .flatMap(
                          (contact) => contact.source?.ids as string[],
                        ) || [],
                    ),
                  )}
                  label="Selecione os grupos"
                  withoutParticipants
                  canSend
                />
                {errors.selectedGroups && (
                  <p className="text-red-500">{errors.selectedGroups}</p>
                )}
              </div>
            )}

            {errors.target && <p className="text-red-500">{errors.target}</p>}
          </div>

          {state.withGroups && (
            <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
              <div className="w-full flex items-center justify-between gap-2">
                <label htmlFor="withAdmin" className="w-full">
                  Remover ADM do grupo
                </label>
                <div className="relative flex">
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input
                      id="withAdmin"
                      type="checkbox"
                      className="sr-only peer/check"
                      checked={state.withAdmin}
                      onChange={() => {
                        setState((prevState) => ({
                          ...prevState,
                          withAdmin: !prevState.withAdmin,
                        }));
                      }}
                    />
                    <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
                  </label>
                </div>
              </div>
            </div>
          )}

          <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
            <div className="w-full flex items-center justify-between">
              <span>Ações</span>
              <div className="hidden items-center gap-2">
                <label htmlFor="randomize">Randomizar</label>
                <label className="relative inline-flex items-center cursor-pointer">
                  <input
                    id="randomize"
                    type="checkbox"
                    className="sr-only peer/check"
                    checked={state.randomizeActions}
                    onChange={() => {
                      setState((prevState) => ({
                        ...prevState,
                        randomizeActions: !prevState.randomizeActions,
                        actionGroups: !prevState.randomizeActions
                          ? [{ groupId: crypto.randomUUID(), items: [] }]
                          : prevState.actionGroups,
                      }));
                    }}
                  />
                  <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
                </label>
              </div>
            </div>

            {!state.randomizeActions ? (
              <>
                <ItemsSelect
                  setItems={(items) =>
                    setState((prevState) => ({
                      ...prevState,
                      itemsSelected: items,
                    }))
                  }
                  defaultItems={item?.items}
                />
                {state.itemsSelected.length > 1 && (
                  <p className="text-xs text-gray-400">
                    Ao selecionar mais de uma ação, será enviado aleatóriamente
                    para os alvos!
                  </p>
                )}
              </>
            ) : (
              <div className="flex flex-col gap-4">
                {state.actionGroups.map((group, index) => (
                  <div
                    key={group.groupId}
                    className="flex flex-col gap-3 p-3 bg-secondary rounded"
                  >
                    <div className="flex items-center justify-between">
                      <span className="text-xs font-semibold">
                        Grupo {index + 1}
                      </span>
                      {state.actionGroups.length > 1 && (
                        <button
                          onClick={() => {
                            setState((prevState) => ({
                              ...prevState,
                              actionGroups: prevState.actionGroups.filter(
                                (g) => g.groupId !== group.groupId,
                              ),
                            }));
                          }}
                          className="p-1 hover:bg-red-500/20 rounded"
                        >
                          <Trash2 className="size-4 text-red-500" />
                        </button>
                      )}
                    </div>
                    <ItemsSelect
                      key={`items-${group.groupId}`}
                      setItems={(items) => {
                        setState((prevState) => ({
                          ...prevState,
                          actionGroups: prevState.actionGroups.map((g) =>
                            g.groupId === group.groupId ? { ...g, items } : g,
                          ),
                        }));
                      }}
                      defaultItems={group.items.map((g) => ({
                        id: g.id || 0,
                        type: g.type,
                      }))}
                    />
                  </div>
                ))}

                <button
                  onClick={() => {
                    setState((prevState) => ({
                      ...prevState,
                      actionGroups: [
                        ...prevState.actionGroups,
                        { groupId: crypto.randomUUID(), items: [] },
                      ],
                    }));
                  }}
                  className="flex items-center justify-center gap-2 p-2 bg-primary/20 hover:bg-primary/30 rounded"
                >
                  <Plus className="size-4" />
                  <span className="text-xs">Adicionar grupo</span>
                </button>
              </div>
            )}

            {errors.items && <p className="text-red-500">{errors.items}</p>}
          </div>

          <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
            <div className="w-full flex items-center justify-between">
              <span>
                {state.diynamicInterval ? "Intervalo entre" : "Intervalo"}
              </span>

              <div className="flex items-center gap-2">
                <label htmlFor="dynamic">Dinâmico</label>

                <div className="relative flex">
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input
                      id="dynamic"
                      type="checkbox"
                      className="sr-only peer/check"
                      checked={state.diynamicInterval}
                      onChange={() =>
                        setState((prevState) => ({
                          ...prevState,
                          diynamicInterval: !prevState.diynamicInterval,
                        }))
                      }
                    />
                    <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
                  </label>
                </div>
              </div>
            </div>

            <div className="flex items-end justify-between">
              <div className="flex items-end gap-2">
                <input
                  ref={refs.interval1Ref}
                  type="number"
                  id="interval1"
                  defaultValue={item?.interval?.[0]}
                  onChange={(e) => {
                    if (state.diynamicInterval && refs.interval2Ref.current) {
                      const value1 = convertToSeconds(
                        Number(e.target.value),
                        state.interval1Unit,
                      );
                      const value2 = convertToSeconds(
                        Number(refs.interval2Ref.current.value),
                        state.interval2Unit,
                      );

                      if (value1 >= value2 && value2 > 0) {
                        const newValue2 = convertFromSeconds(
                          value1 + 1,
                          state.interval2Unit,
                        );
                        refs.interval2Ref.current.value =
                          Math.ceil(newValue2).toString();
                      }
                    }
                  }}
                  className="w-10 bg-secondary border-none focus:outline-none text-foreground p-1 rounded [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                  placeholder="1"
                />
                <select
                  id="interval1Unit"
                  value={state.interval1Unit}
                  onChange={(e) => {
                    const newUnit = e.target.value as
                      | "segundos"
                      | "minutos"
                      | "horas";
                    const currentValue = Number(
                      refs.interval1Ref.current?.value || 0,
                    );

                    if (currentValue > 0) {
                      const valueInSeconds = convertToSeconds(
                        currentValue,
                        state.interval1Unit,
                      );
                      const newValue = convertFromSeconds(
                        valueInSeconds,
                        newUnit,
                      );
                      if (refs.interval1Ref.current) {
                        refs.interval1Ref.current.value =
                          Math.round(newValue).toString();
                      }
                    }

                    setState((prevState) => ({
                      ...prevState,
                      interval1Unit: newUnit,
                    }));
                  }}
                  className="bg-secondary border-none focus:outline-none text-foreground p-1 rounded text-sm"
                >
                  <option value="segundos">Segundos</option>
                  <option value="minutos">Minutos</option>
                  <option value="horas">Horas</option>
                </select>
              </div>
              {state.diynamicInterval && (
                <>
                  <span>à</span>
                  <div className="flex items-end gap-2">
                    <input
                      ref={refs.interval2Ref}
                      type="number"
                      id="interval2"
                      defaultValue={item?.interval?.[1]}
                      onChange={(e) => {
                        if (refs.interval1Ref.current) {
                          const value1 = convertToSeconds(
                            Number(refs.interval1Ref.current.value),
                            state.interval1Unit,
                          );
                          const value2 = convertToSeconds(
                            Number(e.target.value),
                            state.interval2Unit,
                          );

                          if (value2 <= value1 && value1 > 0) {
                            const newValue1 = convertFromSeconds(
                              value2 - 1,
                              state.interval1Unit,
                            );
                            if (newValue1 >= 1) {
                              refs.interval1Ref.current.value =
                                Math.floor(newValue1).toString();
                            }
                          }
                        }
                      }}
                      className="w-10 bg-secondary border-none focus:outline-none text-foreground p-1 rounded [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                      placeholder="1"
                    />
                    <select
                      id="interval2Unit"
                      value={state.interval2Unit}
                      onChange={(e) => {
                        const newUnit = e.target.value as
                          | "segundos"
                          | "minutos"
                          | "horas";
                        const currentValue = Number(
                          refs.interval2Ref.current?.value || 0,
                        );

                        if (currentValue > 0) {
                          const valueInSeconds = convertToSeconds(
                            currentValue,
                            state.interval2Unit,
                          );
                          const newValue = convertFromSeconds(
                            valueInSeconds,
                            newUnit,
                          );
                          if (refs.interval2Ref.current) {
                            refs.interval2Ref.current.value =
                              Math.round(newValue).toString();
                          }
                        }

                        setState((prevState) => ({
                          ...prevState,
                          interval2Unit: newUnit,
                        }));
                      }}
                      className="bg-secondary border-none focus:outline-none text-foreground p-1 rounded text-sm"
                    >
                      <option value="segundos">Segundos</option>
                      <option value="minutos">Minutos</option>
                      <option value="horas">Horas</option>
                    </select>
                  </div>
                </>
              )}
            </div>
            {errors.interval && (
              <p className="text-red-500">{errors.interval}</p>
            )}
          </div>

          {state.showSchedule && (
            <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
              <span>Agendar disparo</span>
              <div className="w-full gap-x-3 flex items-center justify-between">
                <label htmlFor="date">Data</label>
                <input
                  type="date"
                  id="date"
                  className="w-full rounded p-2 bg-secondary focus:outline-none text-foreground"
                  ref={refs.dateRef}
                  value={state.date}
                  onChange={(e) =>
                    setState((prevState) => ({
                      ...prevState,
                      date: e.target.value,
                    }))
                  }
                />
              </div>
              <div className="w-full gap-x-3 flex items-center justify-between">
                <label htmlFor="time">Hora</label>
                <input
                  type="time"
                  id="time"
                  className="w-full rounded p-2 bg-secondary focus:outline-none text-foreground"
                  ref={refs.timeRef}
                  value={state.time}
                  onChange={(e) =>
                    setState((prevState) => ({
                      ...prevState,
                      time: e.target.value,
                    }))
                  }
                />
              </div>
              {errors.date && <p className="text-red-500">{errors.date}</p>}
            </div>
          )}
        </>
      )}

      {item && (
        <button
          onClick={removeItem}
          className="w-full bg-neutral text-red-500 text-center p-2 rounded"
        >
          Excluir
        </button>
      )}

      {Object.keys(errors).length > 0 && (
        <p className="text-red-500 text-sm text-center">
          Há erros no formulário, corrija-os para poder salvar.
        </p>
      )}

      <button
        onClick={() => handleClick()}
        className="w-full bg-neutral text-primary text-center p-2 rounded"
      >
        Salvar
      </button>

      {!isShooting && (
        <button
          onClick={() =>
            setState((prevState) => ({
              ...prevState,
              showSchedule: !prevState.showSchedule,
            }))
          }
          className="w-full bg-neutral text-primary text-center p-2 rounded"
        >
          {state.showSchedule ? "Cancelar agendamento" : "Agendar"}
        </button>
      )}

      {!state.showSchedule && !isShooting && (
        <button
          onClick={() => handleClick(true)}
          disabled={isSubmittingShoot}
          className="w-full bg-primary text-white text-center p-2 rounded flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {isSubmittingShoot ? (
            <>
              <Loader className="size-4 animate-spin" />
              <span>Preparando...</span>
            </>
          ) : (
            "Disparar"
          )}
        </button>
      )}
    </div>
  );
}
