import { useEffect, useRef, useState } from "react"
import { getIconByType } from "../header"
import db, { Group } from "../../models/db"
import { useLiveQuery } from "dexie-react-hooks"
import GroupCard from "../group-card"
import { useGroupSet } from "../hooks/group-set"
import { Folders } from "lucide-react"

const validateErrors = {
  title: "Digite um título!",
  color: "Selecione uma cor!"
}

export default function MenuGroupTab({ item }: { item?: Group }) {
  const [color, setColor] = useState<string>("#969696")
  const groups = useLiveQuery(() => db.groups.toArray(), [], [])
  const titleRef = useRef<HTMLInputElement>(null)
  const { saveItem, removeItem, errors } = useGroupSet({ item, validateErrors })
  const Icon = getIconByType("group")

  useEffect(() => {
    if (item) {
      setColor(item.color)
    } else {
      setColor("#969696")
    }
  }, [item])

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    setColor(e.target.value)
  }

  async function handleClick() {
    const title = titleRef.current?.value!
    const count = await db.groups.count()

    const newItem = {
      title,
      color,
      items: [],
      index: count
    }

    await saveItem({ newItem })
  }

  return (
    <div className="w-full h-full flex flex-col items-center gap-5 overflow-auto">
      <div className="w-full flex items-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
        <Icon className="size-3" />
        <span className="text-center text-sm">Configurar pasta</span>
      </div>

      <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <label htmlFor="title">Título</label>
        <input
          ref={titleRef}
          type="text"
          id="title"
          defaultValue={item?.title}
          className="w-full rounded p-2 bg-secondary focus:outline-none"
          placeholder="Digite um título..."
        />
        {errors.title && <p className="text-red-500">{errors.title}</p>}

        <label htmlFor="color">Cor da pasta</label>
        <input
          className="w-full h-12 p-1.5 rounded bg-secondary cursor-pointer"
          type="color"
          id="color"
          value={color}
          onChange={handleChange}
        />
        {errors.color && <p className="text-red-500">{errors.color}</p>}
      </div>

      {item && (
        <button onClick={removeItem} className="w-full bg-neutral text-red-500 text-center p-2 rounded">Excluir</button>
      )}

      <button onClick={handleClick} className="w-full bg-primary text-white text-center p-2 rounded">Salvar</button>

      <div className="w-full flex items-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
        <Folders className="size-4" />
        <span className="text-center text-sm">Minhas pastas</span>
      </div>

      <div className="w-full flex flex-col gap-2">
        {groups.filter(group => group.id !== item?.id).map((item) => (
          <GroupCard key={item.id} item={item} />
        ))}
      </div>
    </div>
  )
}