import { useLiveQuery } from "dexie-react-hooks";
import db from "../../models/db";
import { getIconByType } from "../header";
import TriggerCard from "../trigger-cards";
import { Plus } from "lucide-react";
import { useContext } from "react";
import { HeaderContext } from "../providers/header-context";

export default function MenuTriggersListTab() {
	const triggers = useLiveQuery(() => db.shotTriggers.toArray(), [], []);
	const Icon = getIconByType("shot-triggers-list");
	const { setTab } = useContext(HeaderContext);

	function handleClick() {
		setTab("shot-triggers");
	}

	return (
		<div className="w-full h-full flex flex-col items-center gap-5 overflow-auto">
			<button
				onClick={handleClick}
				className="w-full flex items-center justify-center gap-2 bg-primary text-white rounded px-5 py-2"
			>
				<Plus className="size-4" />
				<span>Novo gatilho</span>
			</button>

			<div className="w-full flex items-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
				<Icon className="size-4" />
				<span className="text-center text-sm">Meus gatilhos</span>
			</div>

			<div className="w-full flex flex-col gap-2">
				{triggers.map((item) => (
					<TriggerCard key={item.id} item={item} />
				))}
			</div>
		</div>
	);
}
