import { Upload } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { toBase64 } from "../../lib/to-base64";
import { Item } from "../../models/db";
import { getIconByType } from "../header";
import { useItemSet } from "../hooks/item-set";
import Loading from "../loading";
import { SelectGroup } from "../selects/group";
import { convertAudioToOgg } from "../utils/functions";

const validateErrors = {
  title: "Digite um título!",
  content: "Importe um arquivo!",
};

export default function MenuAudioTab({ item }: { item?: Item }) {
  const [file, setFile] = useState<{
    content: string;
    filename: string;
  }>();
  const titleRef = useRef<HTMLInputElement>(null);
  const groupRef = useRef<HTMLSelectElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const mentionAllRef = useRef<HTMLInputElement>(null);
  const { saveItem, removeItem, errors } = useItemSet({ item, validateErrors });
  const Icon = getIconByType("audio");

  useEffect(() => {
    if (item?.content && item?.filename) {
      setFile({
        content: item.content,
        filename: item.filename,
      });
    }
  }, [item]);

  async function handleClick() {
    setIsLoading(true);
    setError(null);

    const title = titleRef.current?.value;
    const groupId = Number(groupRef.current?.value);
    const mentionAll = mentionAllRef.current?.checked;
    const content = file?.content;
    const filename = file?.filename;

    if (!content || !filename) {
      setError("Por favor, selecione um arquivo de áudio");
      setIsLoading(false);
      return;
    }

    try {
      let audioContent = content;

      // Tenta converter para OGG se possível (usuário logado)
      // Se falhar (usuário não logado), salva o áudio original
      try {
        const convertedFile = await convertAudioToOgg({
          file: file?.content,
          fileName: filename,
        });
        audioContent = convertedFile.base64;
      } catch (conversionError: any) {
        // Se o erro for de autenticação, apenas avisa mas permite salvar
        if (conversionError?.message?.includes("logado")) {
          console.warn("Áudio salvo sem conversão. Será convertido ao enviar.");
        } else {
          // Se for outro erro, repropaga
          throw conversionError;
        }
      }

      const newItem: Partial<Item> = {
        type: "audio",
        title,
        content: audioContent,
        filename,
        mentionAll,
      };

      await saveItem({ newItem, groupId });
    } catch (error: any) {
      const errorMessage =
        error?.message || "Erro ao salvar o áudio. Tente novamente.";
      setError(errorMessage);
      console.error("Erro ao salvar áudio:", error);
    } finally {
      setIsLoading(false);
    }
  }

  function normalizeToMp3(name: string): string {
    if (!name) return "audio.mp3";
    if (name.toLowerCase().endsWith(".mp3")) return name;

    const baseName = name.includes(".")
      ? name.substring(0, name.lastIndexOf("."))
      : name;

    return `${baseName || "audio"}.mp3`;
  }

  function renameFileToMp3(selectedFile: File): File {
    const normalizedName = normalizeToMp3(selectedFile.name);

    if (normalizedName === selectedFile.name) {
      return selectedFile;
    }

    // Cria um novo File com o mesmo conteúdo, apenas alterando o nome/extensão
    return new File([selectedFile], normalizedName, {
      type: selectedFile.type || "audio/mpeg",
      lastModified: selectedFile.lastModified,
    });
  }

  async function handleFileChange(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];

    if (file) {
      const normalizedFile = renameFileToMp3(file);
      const content = await toBase64(normalizedFile);
      setFile({ filename: normalizedFile.name, content });
    }
  }

  return (
    <div className="w-full h-full flex flex-col items-center gap-5 overflow-auto">
      <div className="w-full flex items-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
        <Icon className="size-4" />
        <span className="text-center text-sm">Configurar áudio</span>
      </div>

      <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <label htmlFor="title">Título</label>
        <input
          ref={titleRef}
          type="text"
          id="title"
          defaultValue={item?.title}
          className="w-full rounded p-2 bg-secondary focus:outline-none"
          placeholder="Digite um título..."
        />
        {errors.title && <p className="text-red-500">{errors.title}</p>}

        <label htmlFor="content">Importar arquivo</label>
        <div className="w-full flex items-center justify-center flex-col gap-3">
          <label
            htmlFor="dropzone-file"
            className="w-full h-24 flex flex-col items-center justify-center gap-3 rounded cursor-pointer bg-secondary p-2"
          >
            <Upload className="size-8" />
            <input
              id="dropzone-file"
              type="file"
              className="hidden"
              onChange={handleFileChange}
            />
            {file && (
              <span className="text-sm text-gray-400 truncate w-full text-center">
                {file.filename}
              </span>
            )}
          </label>

          <p className="text-sm text-gray-400 text-center">
            Você pode importar áudios: .mp3 / .ogg / .mpeg / .amr / .aif / .wma
            / .oga / .ogv / .ogx / .wav / .acc{" "}
            {/* REMOVIDO POIS AGORA O AUDIO FOI TRATADO ADEQUANDAMENTE */}
            {/* <a
              href="https://convertio.co/pt/conversor-mp3/"
              rel="noopener noreferrer"
              target="_blank"
              className="text-blue-500"
            >
              clique aqui
            </a>{" "}
            para converter o seu áudio */}
          </p>
        </div>

        {file && (
          <audio
            src={file.content}
            controls
            className="w-full rounded p-2 bg-secondary"
          ></audio>
        )}

        {errors.content && <p className="text-red-500">{errors.content}</p>}
      </div>

      <div className="w-full flex justify-between bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <label htmlFor="mentionAll" className="w-full">
          Mencionar todos?
        </label>
        <div className="relative flex">
          <label className="relative inline-flex items-center cursor-pointer">
            <input
              id="mentionAll"
              ref={mentionAllRef}
              type="checkbox"
              className="sr-only peer/check"
              defaultChecked={item?.mentionAll}
            />
            <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
          </label>
        </div>
      </div>

      <SelectGroup ref={groupRef} defaultId={item?.id} />

      {item && (
        <button
          onClick={removeItem}
          className="w-full bg-neutral text-red-500 text-center p-2 rounded"
          disabled={isLoading}
        >
          Excluir
        </button>
      )}

      {error && <p className="text-red-500">{error}</p>}

      <div className="relative w-full">
        {isLoading && <Loading />}
        <button
          onClick={handleClick}
          className="w-full bg-primary text-white text-center p-2 rounded"
          disabled={isLoading}
        >
          Salvar
        </button>
      </div>
    </div>
  );
}
