import { useRef, useState } from "react";
import db, { ShotTriggers, TriggerCondition } from "../../models/db";
import { getIconByType } from "../header";
import { useTriggerSet } from "../hooks/triggers-set";
import ItemsSelect from "../items-select";
import { Minus, Plus } from "lucide-react";

const validateErrors = {
  title: "Digite um título!",
  items: "Selecione ao menos uma ação!",
  triggerMessage: "Digite o texto para acionar o disparo!",
  condition: "Selecione uma condição!",
};

export type SelectedShoot = {
  id: number | undefined;
  title: string;
  type: "item" | "script";
};

const MenuTriggersTab = ({ item }: { item?: ShotTriggers }) => {
  const Icon = getIconByType("shot-triggers-list");
  const [itemsSelected, setItemsSelected] = useState<SelectedShoot[]>([]);
  const titleRef = useRef<HTMLInputElement>(null);
  const activeRef = useRef<HTMLInputElement>(null);
  const [triggerMessages, setTriggerMessages] = useState<string[]>(
    item?.triggerMessages || [""]
  );
  const [selectedCondition, setSelectedCondition] = useState<TriggerCondition>(
    item?.condition || "equals"
  );
  const [ignoreCase, setIgnoreCase] = useState<boolean>(
    item?.ignoreCase || false
  );
  const [samePerson, setSamePerson] = useState<boolean>(
    item?.samePerson || false
  );
  const [errors, setErrors] = useState<{ [key: string]: string }>({});
  const { saveItem, removeItem } = useTriggerSet({
    item,
    validateErrors,
  });

  const addTriggerMessage = () => {
    setTriggerMessages([...triggerMessages, ""]);
  };

  const handleTriggerMessageChange = (index: number, value: string) => {
    const newTriggerMessages = [...triggerMessages];
    newTriggerMessages[index] = value;
    setTriggerMessages(newTriggerMessages);
  };

  const removeTriggerMessage = (index: number) => {
    setTriggerMessages((prevMessages) =>
      prevMessages.filter((_, i) => i !== index)
    );
  };

  async function handleClick() {
    const title = titleRef.current?.value;
    const active = activeRef.current?.checked;
    const condition = selectedCondition;

    const newErrors: { [key: string]: string } = {};

    if (!title) {
      newErrors.title = "Digite um título!";
    }

    if (triggerMessages.some((msg) => !msg)) {
      newErrors.triggerMessage = "Digite o texto para acionar o disparo!";
    }

    if (!condition) {
      newErrors.condition = "Selecione uma condição!";
    }

    if (itemsSelected.length === 0) {
      newErrors.items = "Selecione ao menos uma ação!";
    }

    setErrors(newErrors);

    if (Object.keys(newErrors).length > 0) {
      return;
    }

    const newItem = {
      title,
      triggerMessages,
      active,
      condition,
      ignoreCase,
      samePerson,
      items: itemsSelected.length
        ? itemsSelected.map(({ id, type }) => ({ id: id!, type }))
        : undefined,
    };

    if (!item) {
      const existTrigger = await db.shotTriggers.toArray();

      if (
        existTrigger.find((trigger) =>
          triggerMessages.some((msg) => trigger.triggerMessages.includes(msg))
        )
      ) {
        newErrors.triggerMessage = "Este disparo já existe!";
        setErrors(newErrors);
        return;
      }
    }

    await saveItem({
      newItem,
      errors: newErrors,
      tab: "shot-triggers-list",
    });
  }

  return (
    <div className="w-full h-full flex flex-col items-center gap-5 overflow-auto">
      <div className="w-full flex items-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
        <Icon className="size-4" />
        <span className="text-center text-sm">Configurar disparo</span>
      </div>

      <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <label htmlFor="title">Título</label>
        <input
          ref={titleRef}
          type="text"
          id="title"
          defaultValue={item?.title || ""}
          className="w-full rounded p-2 bg-secondary focus:outline-none text-sm"
          placeholder="Digite um título..."
        />
        {errors.title && <p className="text-red-500">{errors.title}</p>}
      </div>

      <div className="flex flex-col gap-y-5 w-full bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5">
        <label>Acionar o disparo quando</label>
        <div className="w-full flex justify-between text-sm">
          <label htmlFor="equals" className="w-full">
            O texto for igual a
          </label>
          <div className="relative flex">
            <label className="relative inline-flex items-center cursor-pointer">
              <input
                id="equals"
                type="checkbox"
                className="sr-only peer/check"
                checked={selectedCondition === "equals"}
                onChange={() => setSelectedCondition("equals")}
              />
              <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
            </label>
          </div>
        </div>
        <div className="w-full flex justify-between text-sm">
          <label htmlFor="contains" className="w-full">
            Se o texto contém
          </label>
          <div className="relative flex">
            <label className="relative inline-flex items-center cursor-pointer">
              <input
                id="contains"
                type="checkbox"
                className="sr-only peer/check"
                checked={selectedCondition === "contains"}
                onChange={() => setSelectedCondition("contains")}
              />
              <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
            </label>
          </div>
        </div>
        <div className="w-full flex justify-between text-sm">
          <label htmlFor="startsWith" className="w-full">
            Se o texto começa com
          </label>
          <div className="relative flex">
            <label className="relative inline-flex items-center cursor-pointer">
              <input
                id="startsWith"
                type="checkbox"
                className="sr-only peer/check"
                checked={selectedCondition === "startsWith"}
                onChange={() => setSelectedCondition("startsWith")}
              />
              <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
            </label>
          </div>
        </div>
        {triggerMessages.map((msg, index) => (
          <div key={index} className="w-full flex flex-col gap-2">
            <div className="flex w-full justify-between">
              <label htmlFor={`conditionText${index}`}>
                Texto para a condição
              </label>
              <div className="flex items-center gap-2">
                {index === 0 && (
                  <button
                    type="button"
                    onClick={addTriggerMessage}
                    className="flex items-center w-6 h-6 justify-center bg-accent rounded-full"
                  >
                    <Plus color="#ffffff" className="size-3" />
                  </button>
                )}
                <button
                  type="button"
                  onClick={() => removeTriggerMessage(index)}
                  className="flex items-center w-6 h-6 justify-center bg-accent rounded-full"
                >
                  <Minus color="#ffffff" className="size-3" />
                </button>
              </div>
            </div>
            <input
              type="text"
              id={`conditionText${index}`}
              value={msg}
              onChange={(e) =>
                handleTriggerMessageChange(index, e.target.value)
              }
              className="w-full rounded p-2 bg-secondary focus:outline-none text-sm"
              placeholder="Digite o texto..."
            />
          </div>
        ))}

        {errors.triggerMessage && (
          <p className="text-red-500 text-sm">{errors.triggerMessage}</p>
        )}
        {errors.condition && (
          <p className="text-red-500 text-sm">{errors.condition}</p>
        )}
      </div>

      <div className="w-full flex justify-between gap-y-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <label htmlFor="ignoreCase" className="w-full">
          Ignorar maiúsculas/minúsculas
        </label>
        <div className="relative flex">
          <label className="relative inline-flex items-center cursor-pointer">
            <input
              id="ignoreCase"
              type="checkbox"
              className="sr-only peer/check"
              checked={ignoreCase}
              onChange={() => setIgnoreCase(!ignoreCase)}
            />
            <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
          </label>
        </div>
      </div>

      <div className="w-full flex justify-between gap-y-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <label htmlFor="samePerson" className="w-full">
          Enviar para a mesma pessoa
        </label>
        <div className="relative flex">
          <label className="relative inline-flex items-center cursor-pointer">
            <input
              id="samePerson"
              type="checkbox"
              className="sr-only peer/check"
              checked={samePerson}
              onChange={() => setSamePerson(!samePerson)}
            />
            <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
          </label>
        </div>
      </div>

      <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <span>Ações</span>
        <ItemsSelect setItems={setItemsSelected} defaultItems={item?.items} />
        {errors.items && <p className="text-red-500">{errors.items}</p>}
        {itemsSelected.length > 1 && (
          <p>
            Ao selecionar mais de uma ação, será enviado aleatoriamente para os
            alvos!
          </p>
        )}
      </div>

      <div className="w-full flex justify-between gap-y-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <label htmlFor="active" className="w-full">
          Ativo
        </label>
        <div className="relative flex">
          <label className="relative inline-flex items-center cursor-pointer">
            <input
              id="active"
              ref={activeRef}
              type="checkbox"
              className="sr-only peer/check"
              defaultChecked={item?.active ?? true}
            />
            <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
          </label>
        </div>
      </div>

      {item && (
        <button
          onClick={removeItem}
          className="w-full bg-neutral text-red-500 text-center p-2 rounded"
        >
          Excluir
        </button>
      )}

      <p className="text-sm text-center">
        Quando criar um novo gatilho é necessário a recarregar a página para
        ativar o gatilho!
      </p>
      <button
        onClick={() => handleClick()}
        className="w-full bg-neutral text-primary text-center p-2 rounded"
      >
        Salvar
      </button>
    </div>
  );
};

export default MenuTriggersTab;
