import { ChevronLeft } from "lucide-react";
import { useContext, useMemo } from "react";
import { createPortal } from "react-dom";
import { twMerge } from "tailwind-merge";
import { getBaseUrl } from "../lib/base-url";
import { Script } from "../models/db";
import AddMenuItems from "./add-menu-items";
import AddMenuSettings from "./add-menu-settings";
import { HeaderContext } from "./providers/header-context";
import MenuAccountTab from "./tabs/account";
import MenuAudioTab from "./tabs/audio";
import MenuContactTab from "./tabs/contact";
import MenuDocTab from "./tabs/doc";
import MenuExportTab from "./tabs/export";
import MenuGroupTab from "./tabs/group";
import MenuImageTab from "./tabs/image";
import MenuTriggersListTab from "./tabs/list-triggers";
import MenuMainTab from "./tabs/main";
import MenuMaturadorTab from "./tabs/maturador";
import MenuSaverTab from "./tabs/saver";
import MenuScriptTab from "./tabs/script";
import MenuSettingsTab from "./tabs/settings";
import MenuShootTab from "./tabs/shoot";
import MenuShootListTab from "./tabs/shoot-list";
import MenuShootingTab from "./tabs/shooting";
import MenuStepTab from "./tabs/step";
import MenuTextTab from "./tabs/text";
import MenuTriggersTab from "./tabs/triggers";
import MenuVideoTab from "./tabs/video";

const baseUrl = getBaseUrl();

export default function Menu() {
  const { show, setTab, tab, activeItem } = useContext(HeaderContext);
  const manifestVersion = useMemo(() => {
    try {
      return chrome?.runtime?.getManifest?.().version ?? "";
    } catch (error) {
      console.error("[Menu] Erro ao ler versão do manifest:", error);
      return "";
    }
  }, []);

  function handleClickReturn() {
    switch (tab) {
      case "shoot":
        setTab("shoot_list");
        break;
      case "shooting":
        setTab("shoot_list");
        break;
      case "shot-triggers":
        setTab("shot-triggers-list");
        break;
      default:
        setTab("main");
    }
  }

  const menuContent = (
    <div
      data-menu-container
      className={twMerge(
        "fixed top-0 right-0 z-[9999] w-96 h-[calc(100%-3.5rem)] mt-14 duration-500 ease-in-out transition-transform",
        show ? "translate-x-0" : "translate-x-[calc(100%+20px)]",
      )}
      style={{
        pointerEvents: show ? "auto" : "none",
      }}
    >
      <div className="relative w-full h-full flex flex-col items-center gap-5 bg-[var(--background-default)] p-5 border-l border-solid border-[var(--border-list)]">
        {tab === "main" ? (
          <div className="w-full flex items-center justify-between">
            <AddMenuItems />
            <div className="p-2">
              <img
                src={baseUrl + "/assets/logo.webp"}
                alt="Logo"
                className="w-28"
              />
            </div>
            <AddMenuSettings />
          </div>
        ) : (
          <div className="relative w-full flex items-center justify-center">
            <div className="absolute top-0 left-0 h-full flex items-center">
              <button
                onClick={handleClickReturn}
                className="px-5 py-2 flex items-center justify-center rounded duration-300 hover:bg-primary/50"
              >
                <ChevronLeft className="size-5" />
              </button>
            </div>

            <div className="p-2">
              <img
                src={baseUrl + "/assets/logo.webp"}
                alt="Logo"
                className="w-28"
              />
            </div>

            <div></div>
          </div>
        )}

        {tab === "main" ? (
          <MenuMainTab />
        ) : tab === "group" ? (
          <MenuGroupTab item={activeItem?.group} />
        ) : tab === "text" ? (
          <MenuTextTab
            item={
              activeItem?.item?.type === "text" ? activeItem?.item : undefined
            }
          />
        ) : tab === "audio" ? (
          <MenuAudioTab
            item={
              activeItem?.item?.type === "audio" ? activeItem?.item : undefined
            }
          />
        ) : tab === "image" ? (
          <MenuImageTab
            item={
              activeItem?.item?.type === "image" ? activeItem?.item : undefined
            }
          />
        ) : tab === "video" ? (
          <MenuVideoTab
            item={
              activeItem?.item?.type === "video" ? activeItem?.item : undefined
            }
          />
        ) : tab === "doc" ? (
          <MenuDocTab
            item={
              activeItem?.item?.type === "doc" ? activeItem?.item : undefined
            }
          />
        ) : tab === "contact" ? (
          <MenuContactTab
            item={
              activeItem?.item?.type === "contact"
                ? activeItem?.item
                : undefined
            }
          />
        ) : tab === "script" ? (
          <MenuScriptTab
            item={
              (activeItem?.item as Script) ?? {
                id: activeItem?.script?.id,
                type: "item-error",
              }
            }
          />
        ) : tab === "settings" ? (
          <MenuSettingsTab />
        ) : tab === "account" ? (
          <MenuAccountTab />
        ) : tab === "export" ? (
          <MenuExportTab />
        ) : tab === "step" ? (
          <MenuStepTab item={activeItem?.step} />
        ) : tab === "shoot" ? (
          <MenuShootTab item={activeItem?.shoot} />
        ) : tab === "shoot_list" ? (
          <MenuShootListTab />
        ) : tab === "shooting" && activeItem?.shoot ? (
          <MenuShootingTab item={activeItem.shoot} />
        ) : tab === "shot-triggers-list" ? (
          <MenuTriggersListTab />
        ) : tab === "shot-triggers" ? (
          <MenuTriggersTab item={activeItem?.shotTrigger} />
        ) : tab === "saver" ? (
          <MenuSaverTab />
        ) : (
          tab === "maturador" && <MenuMaturadorTab />
        )}

        <div className="mt-auto w-full">
          <div className="menu-version w-full text-center text-[11px] border-t border-white/10 pt-3">
            {manifestVersion
              ? `Versão: ${manifestVersion}`
              : "Versão: aguarde..."}
          </div>
        </div>
      </div>
    </div>
  );

  return createPortal(menuContent, document.body);
}
