import { useContext, useEffect, useRef, useState } from "react";
import AddMenuLabel from "./add-menu-label";
import { ItemType } from "../models/db";
import { HeaderContext } from "./providers/header-context";
import { SquarePlus } from "lucide-react";

export default function AddMenuItems() {
	const [show, setShow] = useState(false);
	const { setTab } = useContext(HeaderContext);
	const modalRef = useRef<HTMLDivElement>(null);

	const handleClickOutside = (event: MouseEvent) => {
		if (modalRef.current && !modalRef.current.contains(event.target as Node)) {
			setShow(false);
		}
	};

	useEffect(() => {
		if (show) {
			document.addEventListener("mousedown", handleClickOutside);
		} else {
			document.removeEventListener("mousedown", handleClickOutside);
		}
		return () => {
			document.removeEventListener("mousedown", handleClickOutside);
		};
	}, [show]);

	function handleClick(itemType: ItemType) {
		setShow(false);
		setTab(itemType);
	}

	return (
		<div className="relative">
			<button
				onClick={() => setShow(!show)}
				className="px-5 py-2 bg-neutral rounded duration-300 hover:bg-primary/50"
			>
				<SquarePlus className="size-5" />
			</button>

			{show && (
				<div
					ref={modalRef}
					className="z-10 absolute top-full translate-y-3 left-0 p-3 rounded bg-neutral flex flex-col gap-2 shadow-lg"
				>
					<AddMenuLabel itemType="text" onClick={() => handleClick("text")} />
					<AddMenuLabel itemType="audio" onClick={() => handleClick("audio")} />
					<AddMenuLabel itemType="image" onClick={() => handleClick("image")} />
					<AddMenuLabel itemType="video" onClick={() => handleClick("video")} />
					<AddMenuLabel itemType="doc" onClick={() => handleClick("doc")} />
					<AddMenuLabel
						itemType="contact"
						onClick={() => handleClick("contact")}
					/>
					<AddMenuLabel
						itemType="script"
						onClick={() => handleClick("script")}
					/>
				</div>
			)}
		</div>
	);
}
