import { twMerge } from "tailwind-merge";
import { getIconByType, getTitleByType } from "./header";
import { MenuTabType } from "./providers/header-context";

interface AddMenuLabelProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  itemType: MenuTabType;
}

export default function AddMenuLabel({
  itemType,
  className,
  ...props
}: AddMenuLabelProps) {
  const Icon = getIconByType(itemType);
  const title = getTitleByType(itemType);

  return (
    <button
      className={twMerge(
        "w-full flex items-center gap-2 p-3 rounded bg-neutral whitespace-nowrap duration-300 hover:bg-primary/50",
        className,
      )}
      {...props}
    >
      <Icon className="size-4 min-w-4 min-h-4" />
      <span className="text-sm capitalize">{title}</span>
    </button>
  );
}
