import { Eye, EyeOff, Lock } from "lucide-react"
import { forwardRef, useState } from "react"
import { twMerge } from "tailwind-merge"
import { v4 as uuidv4 } from "uuid"

type Props = {
  className?: string
}

const InputPassword = forwardRef<HTMLInputElement, Props>(({ className }, ref) => {
  const [showPassword, setShowPassword] = useState(false)
  const inputId = uuidv4()

  return (
    <div className="w-full flex items-center gap-2 p-2 bg-white rounded text-black">
      <label htmlFor={inputId}>
        <Lock className="size-4" />
      </label>

      <input
        ref={ref}
        id={inputId}
        className={twMerge(
          "w-full flex items-center gap-3 border-none outline-none text-sm",
          className
        )}
        type={showPassword ? "text" : "password"}
      />

      <button onClick={() => setShowPassword(!showPassword)} type="button">
        {showPassword ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
      </button>
    </div>
  )
})

InputPassword.displayName = "InputPassword"

export default InputPassword