import { useEffect, useState } from "react";
import { TrialStatus } from "../providers/session-context";

interface TimeRemaining {
  days: number;
  hours: number;
  minutes: number;
  seconds: number;
  total: number; // em milissegundos
}

export function useTrialCountdown(
  trialEndsAt?: Date,
  trialStatus?: TrialStatus
) {
  const [timeRemaining, setTimeRemaining] = useState<TimeRemaining | null>(
    null
  );
  const [isExpired, setIsExpired] = useState(false);

  useEffect(() => {
    if (!trialEndsAt || trialStatus !== TrialStatus.TRIAL_ACTIVE) {
      setTimeRemaining(null);
      setIsExpired(trialStatus === TrialStatus.TRIAL_EXPIRED);
      return;
    }

    const updateCountdown = () => {
      const now = new Date().getTime();
      const endTime = new Date(trialEndsAt).getTime();
      const difference = endTime - now;

      if (difference <= 0) {
        setTimeRemaining(null);
        setIsExpired(true);
        return;
      }

      const days = Math.floor(difference / (1000 * 60 * 60 * 24));
      const hours = Math.floor(
        (difference % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)
      );
      const minutes = Math.floor((difference % (1000 * 60 * 60)) / (1000 * 60));
      const seconds = Math.floor((difference % (1000 * 60)) / 1000);

      setTimeRemaining({
        days,
        hours,
        minutes,
        seconds,
        total: difference,
      });
      setIsExpired(false);
    };

    // Atualiza imediatamente
    updateCountdown();

    // Atualiza a cada segundo
    const interval = setInterval(updateCountdown, 1000);

    return () => clearInterval(interval);
  }, [trialEndsAt, trialStatus]);

  const formatTimeRemaining = (): string => {
    if (!timeRemaining) {
      return isExpired ? "Teste grátis expirado" : "";
    }

    const { days, hours, minutes, seconds } = timeRemaining;

    if (days > 0) {
      return `${days}d ${hours}h ${minutes}m`;
    } else if (hours > 0) {
      return `${hours}h ${minutes}m ${seconds}s`;
    } else if (minutes > 0) {
      return `${minutes}m ${seconds}s`;
    } else {
      return `${seconds}s`;
    }
  };

  return {
    timeRemaining,
    isExpired,
    formatTimeRemaining,
  };
}
