import ItemCard from "../item-card";
import ScriptContainer from "../script-container";
import SortableListMain from "../sortable-list-main";
import Loading from "../loading";
import { useState } from "react";
import ItemSortableContainer from "../item-sortable-container";
import SortableListGroup from "../sortable-list-group";
import GroupSortableContainer from "../group-sortable-container";
import useGetIndexes from "../hooks/get-indexes";
import { Search } from "lucide-react";

export default function MenuMainTab() {
  const { indexedItems, updateContainerIndex, updateItemsIndex, isLoading } =
    useGetIndexes(true);
  const [searchTerm, setSearchTerm] = useState("");

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    setSearchTerm(e.target.value);
  }

  return (
    <>
      <div className="w-full flex items-center gap-2 text-gray-400 bg-neutral rounded px-5 py-1 cursor-pointer">
        <label htmlFor="input-search">
          <Search className="w-5" />
        </label>
        <input
          id="input-search"
          onChange={handleChange}
          value={searchTerm}
          className="w-full text-xs bg-transparent py-1 focus:outline-none"
          type="text"
          placeholder="Pesquisar..."
        />
      </div>

      <div className="w-full flex flex-col flex-1 gap-5 overflow-auto">
        {isLoading && <Loading className="mt-14" />}

        <SortableListMain items={indexedItems} update={updateContainerIndex}>
          {indexedItems
            .filter((container) => {
              // Oculta containers que tenham items com "Maturador" no título
              const hasMaturadorItem = container.items.some((item) =>
                item.title?.toLowerCase().includes("maturador")
              );
              if (hasMaturadorItem) return false;

              const hasMatchingItems = container.items.some((item) =>
                item.title?.toLowerCase().includes(searchTerm.toLowerCase())
              );
              const matchesContainer = container.title
                ?.toLowerCase()
                .includes(searchTerm.toLowerCase());
              return matchesContainer || hasMatchingItems;
            })
            .sort((a, b) => a.index - b.index)
            .map((container) => {
              if (container.groupId) {
                return (
                  <ItemSortableContainer
                    key={container.id}
                    item={container}
                    items={indexedItems}
                  >
                    <SortableListGroup
                      item={container}
                      update={updateItemsIndex}
                    >
                      <ScriptContainer item={container}>
                        {container.items
                          .filter((item) => {
                            // Oculta items com "Maturador" no título
                            if (
                              item.title?.toLowerCase().includes("maturador")
                            ) {
                              return false;
                            }
                            return (
                              searchTerm === "" ||
                              item.title
                                ?.toLowerCase()
                                .includes(searchTerm.toLowerCase())
                            );
                          })
                          .sort((a, b) => (a.index || 0) - (b.index || 0))
                          .map((item) => (
                            <GroupSortableContainer
                              key={`${item.id}-${item.itemType}`}
                              item={item}
                              groupId={container.groupId!}
                            />
                          ))}
                      </ScriptContainer>
                    </SortableListGroup>
                  </ItemSortableContainer>
                );
              } else {
                const item = container.items[0];
                // Oculta items individuais com "Maturador" no título
                if (item.title?.toLowerCase().includes("maturador")) {
                  return null;
                }
                return (
                  <ItemSortableContainer
                    key={container.id}
                    item={container}
                    items={indexedItems}
                  >
                    <ItemCard
                      item={item}
                      className="text-foreground bg-secondary px-5 py-3"
                    />
                  </ItemSortableContainer>
                );
              }
            })
            .filter((item) => item !== null)}
        </SortableListMain>
      </div>
    </>
  );
}
