import { useCallback, useEffect, useMemo, useState } from "react";
import { twMerge } from "tailwind-merge";
import { getIconByType } from "./header";
import { ChevronDown, Search, X } from "lucide-react";
import { useLiveQuery } from "dexie-react-hooks";
import db, { Step } from "../models/db";

export default function StepsSelect({
	setItems,
	defaultItem,
	label = "Selecione as etapas",
}: {
	setItems: (steps: number[]) => void;
	defaultItem?: number[];
	label?: string;
}) {
	const [show, setShow] = useState(false);
	const [searchTerm, setSearchTerm] = useState("");
	const [selecteds, setSelecteds] = useState<number[]>(defaultItem || []);
	const steps = useLiveQuery(() => db.steps.toArray(), [], []);
	const [visibleCount, setVisibleCount] = useState(12);

	useEffect(() => {
		setItems(selecteds);
	}, [selecteds, setItems]);

	const filteredSteps = useMemo(() => {
		if (!steps) return [];

		return steps
			.filter((item) =>
				item.title?.toLowerCase().includes(searchTerm.toLowerCase()),
			)
			.slice(0, visibleCount);
	}, [steps, searchTerm, visibleCount]);

	const handleClick = useCallback((itemId?: number) => {
		if (!itemId) return;

		setSelecteds((prev) =>
			prev.includes(itemId)
				? prev.filter((id) => id !== itemId)
				: [...prev, itemId],
		);
	}, []);

	const handleClearSearch = useCallback(() => {
		setSearchTerm("");
	}, []);

	const handleLoadMore = useCallback(() => {
		setVisibleCount((prev) => prev + 12);
	}, []);

	return (
		<div className="w-full max-h-56 flex flex-col gap-5 rounded p-2 bg-secondary text-sm">
			<button
				onClick={() => setShow(!show)}
				className="w-full flex items-center justify-between gap-2"
			>
				<span>{label}</span>
				<ChevronDown
					className={twMerge(
						"size-4 text-gray-400 duration-300 ease-in-out",
						show ? "rotate-180" : "rotate-0",
					)}
				/>
			</button>

			{show && (
				<>
					<div className="w-full flex items-center gap-2 bg-neutral rounded px-5 py-1">
						<label htmlFor="search" className="cursor-pointer">
							<Search className="w-5 text-gray-400" />
						</label>
						<input
							id="search"
							className="w-full bg-transparent py-1 focus:outline-none"
							type="text"
							placeholder="Buscar..."
							value={searchTerm}
							onChange={(event) => setSearchTerm(event.target.value)}
						/>
						{searchTerm && (
							<button
								onClick={handleClearSearch}
								className="text-gray-400 hover:text-white transition-colors"
							>
								<X className="w-4" />
							</button>
						)}
					</div>

					<div className="flex flex-col h-full overflow-auto gap-y-1">
						{!steps ? (
							<div className="w-full text-center py-4 text-gray-400">
								Carregando etapas...
							</div>
						) : filteredSteps.length === 0 ? (
							<div className="w-full text-center py-4 text-gray-400">
								{searchTerm
									? "Nenhuma etapa encontrada"
									: "Nenhuma etapa disponível"}
							</div>
						) : (
							<div className="flex w-full flex-col gap-2">
								{filteredSteps.map((item) => (
									<Label
										key={item.id}
										item={item}
										selected={selecteds.includes(item.id!)}
										onClick={() => handleClick(item.id)}
									/>
								))}
							</div>
						)}

						{steps && visibleCount < steps.length && (
							<button
								onClick={handleLoadMore}
								className="w-full mt-2 p-2 bg-primary text-white rounded hover:bg-primary/90 transition-colors"
							>
								Ver mais
							</button>
						)}
					</div>
				</>
			)}
		</div>
	);
}

function Label({
	item,
	selected,
	...props
}: {
	item: Step;
	selected?: boolean;
} & React.HTMLAttributes<HTMLDivElement>) {
	const Icon = getIconByType("step");

	return (
		<div
			className={twMerge(
				"w-full gap-2 p-2 rounded transition-colors",
				selected
					? "bg-primary/50 hover:bg-primary/60"
					: "bg-neutral hover:bg-neutral/80",
			)}
			{...props}
		>
			<button className="w-full flex items-center justify-between gap-2">
				<div className="w-full flex items-center gap-2 whitespace-nowrap overflow-hidden">
					<Icon className="size-3" />
					<span className="text-ellipsis overflow-hidden">{item.title}</span>
				</div>
				{item.users.length > 0 && (
					<span className="font-bold text-xs bg-neutral px-2 py-1 rounded">
						{item.users.length}
					</span>
				)}
			</button>
		</div>
	);
}
