import { useContext } from "react";
import { HeaderContext } from "../providers/header-context";

export function ConfirmModal() {
  const { confirmAction, closeConfirmModal, confirmTitle, confirmDescription } =
    useContext(HeaderContext);

  return (
    <div className="z-[99999] fixed inset-0 flex items-center justify-center bg-black/50 backdrop-blur-sm">
      <div className="w-full max-w-md mx-4 bg-neutral rounded-lg shadow-xl border border-white/10">
        <div className="p-6">
          <h3 className="text-lg font-semibold text-center text-white mb-3">
            {confirmTitle || "Tem certeza que deseja continuar?"}
          </h3>
          {confirmDescription && (
            <p className="text-sm text-center text-gray-300 mb-6 leading-relaxed">
              {confirmDescription}
            </p>
          )}
        </div>
        <div className="flex gap-3 px-6 pb-6">
          <button
            onClick={closeConfirmModal}
            className="flex-1 bg-secondary/50 hover:bg-secondary/70 text-gray-300 hover:text-white text-sm font-medium text-center py-2.5 px-4 rounded-lg transition-colors duration-200 border border-white/10"
          >
            Cancelar
          </button>
          <button
            onClick={() => {
              if (confirmAction) confirmAction();
              closeConfirmModal();
            }}
            className="flex-1 bg-primary hover:bg-primary/90 text-white text-sm font-medium text-center py-2.5 px-4 rounded-lg transition-colors duration-200 shadow-lg shadow-primary/20"
          >
            Continuar
          </button>
        </div>
      </div>
    </div>
  );
}
