import { useLiveQuery } from "dexie-react-hooks";
import db from "../../models/db";
import { useContext, useEffect, useRef } from "react";
import { getIconByType } from "../header";
import AddMenuLabel from "../add-menu-label";
import { HeaderContext } from "../providers/header-context";
import {
  ChevronRight,
  Eraser,
  MessageSquareOff,
  MessageSquareX,
  Settings,
} from "lucide-react";

export default function MenuSettingsTab() {
  const user = useLiveQuery(() => db.user.where("id").equals(1).first(), []);
  const chatBlurRef = useRef<HTMLInputElement>(null);
  const Icon = getIconByType("settings");
  const { setTab, showConfirmModal } = useContext(HeaderContext);

  useEffect(() => {
    if (!user) return;

    if (chatBlurRef.current) {
      chatBlurRef.current.checked = user.chatBlur || false;
    }
  }, [user]);

  async function handleChatBlurChange(e: React.ChangeEvent<HTMLInputElement>) {
    const checked = e.target.checked;
    await db.user.put({
      id: 1,
      webhook: user?.webhook,
      chatBlur: checked,
    });
  }

  function clearGlobalVariables() {
    showConfirmModal(
      () => {
        const handleComplete = (event: Event) => {
          const customEvent = event as CustomEvent;
          if (customEvent.detail?.success) {
            window.dispatchEvent(
              new CustomEvent("showErrorMessage", {
                detail: { message: "Cache global limpo com sucesso!" },
              }),
            );
          }
          window.removeEventListener(
            "clearGlobalVariablesComplete",
            handleComplete,
          );
        };

        window.addEventListener("clearGlobalVariablesComplete", handleComplete);
        window.dispatchEvent(new CustomEvent("clearGlobalVariables"));
      },
      "Limpar cache global",
      "Tem certeza que deseja limpar o cache global? Esta ação não pode ser desfeita.",
    );
  }

  function clearCurrentConversationVariables() {
    showConfirmModal(
      () => {
        const handleComplete = (event: Event) => {
          const customEvent = event as CustomEvent;
          if (customEvent.detail?.success) {
            window.dispatchEvent(
              new CustomEvent("showErrorMessage", {
                detail: { message: "Cache do chat limpo com sucesso!" },
              }),
            );
          } else if (customEvent.detail?.error) {
            window.dispatchEvent(
              new CustomEvent("showErrorMessage", {
                detail: { message: customEvent.detail.error },
              }),
            );
          }
          window.removeEventListener(
            "clearCurrentConversationVariablesComplete",
            handleComplete,
          );
        };

        window.addEventListener(
          "clearCurrentConversationVariablesComplete",
          handleComplete,
        );
        window.dispatchEvent(
          new CustomEvent("clearCurrentConversationVariables"),
        );
      },
      "Limpar cache do chat atual",
      "Tem certeza que deseja limpar o cache do chat atual? Esta ação não pode ser desfeita.",
    );
  }

  return (
    <div className="w-full h-full flex flex-col items-center gap-5 overflow-auto">
      <div className="w-full flex items-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
        <Icon className="size-4" />
        <span className="text-center text-sm">Configurações</span>
      </div>

      <div className="w-full flex flex-col flex-1 gap-2">
        <AddMenuLabel
          itemType="export"
          className="py-2"
          onClick={() => setTab("export")}
        />

        <div className="w-full flex items-center justify-between gap-2 p-3 rounded bg-neutral whitespace-nowrap">
          <label
            htmlFor="chat-blur"
            className="w-full text-sm flex items-center gap-2"
          >
            <MessageSquareOff className="size-4 min-w-4 min-h-4 opacity-80" />
            <span>Borrar conversas</span>
          </label>
          <div className="relative flex">
            <label className="relative inline-flex items-center cursor-pointer">
              <input
                ref={chatBlurRef}
                id="chat-blur"
                type="checkbox"
                className="sr-only peer/check"
                onChange={handleChatBlurChange}
              />
              <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
            </label>
          </div>
        </div>

        <button
          type="button"
          onClick={clearGlobalVariables}
          className="w-full flex items-center justify-between gap-2 p-3 rounded bg-neutral whitespace-nowrap"
        >
          <span className="w-full text-sm flex items-center gap-2">
            <Eraser className="size-4 min-w-4 min-h-4 opacity-80" />
            <span>Limpar cache global</span>
          </span>
          <ChevronRight className="size-4 min-w-4 min-h-4 opacity-80" />
        </button>

        <button
          type="button"
          onClick={clearCurrentConversationVariables}
          className="w-full flex items-center justify-between gap-2 p-3 rounded bg-neutral whitespace-nowrap"
        >
          <span className="w-full text-sm flex items-center gap-2">
            <MessageSquareX className="size-4 min-w-4 min-h-4 opacity-80" />
            <span>Limpar cache do chat atual</span>
          </span>
          <ChevronRight className="size-4 min-w-4 min-h-4 opacity-80" />
        </button>
      </div>
    </div>
  );
}
