/**
 * updateChecker.ts
 *
 * Módulo independente de verificação de atualização na Chrome Web Store.
 * - Busca a versão publicada via endpoint de update check do Chrome
 * - Compara com a versão atual do manifest
 * - Exibe card de notificação se houver versão mais nova
 * - Usa chrome.storage.local para não mostrar novamente pelas próximas 24h
 *
 * Funciona de forma totalmente independente: não afeta nenhum outro módulo.
 */

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import UpdateNotifier from "../update-notifier";

const EXTENSION_ID = "iadbakknogblchdohbbnnchfpojbcbll";
const STORAGE_KEY = "revzap_update_check";
const TWENTY_FOUR_HOURS_MS = 24 * 60 * 60 * 1000;
const CONTAINER_ID = "revzap-update-notifier";

type UpdateCheckRecord = {
  storeVersion: string;
  shownAt: number; // ms timestamp
};

/**
 * Compara duas versões no formato X.Y.Z.W (semver estendido).
 * Retorna true se `storeVersion` for maior que `currentVersion`.
 */
function isNewerVersion(storeVersion: string, currentVersion: string): boolean {
  const toNumbers = (v: string) =>
    v.split(".").map((n) => parseInt(n, 10) || 0);

  const store = toNumbers(storeVersion);
  const current = toNumbers(currentVersion);

  const maxLen = Math.max(store.length, current.length);
  for (let i = 0; i < maxLen; i++) {
    const s = store[i] ?? 0;
    const c = current[i] ?? 0;
    if (s > c) return true;
    if (s < c) return false;
  }
  return false;
}

/**
 * Busca a versão publicada na Chrome Web Store via background service worker.
 * O fetch é delegado ao background para evitar bloqueios de CORS no content script.
 * Retorna { version, sw } ou null em caso de falha.
 */
async function fetchStoreVersion(): Promise<{
  version: string;
  sw: boolean;
} | null> {
  try {
    const response = await chrome.runtime.sendMessage({
      action: "extension.fetchStoreVersion",
    });
    if (!response?.version) return null;
    return { version: response.version, sw: response.sw === true };
  } catch {
    return null;
  }
}

/**
 * Verifica se o card já foi mostrado nas últimas 24 horas para esta versão da store.
 */
async function shouldShowNotification(storeVersion: string): Promise<boolean> {
  try {
    const result = await chrome.storage.local.get(STORAGE_KEY);
    const record = result[STORAGE_KEY] as UpdateCheckRecord | undefined;

    if (!record) return true;

    // Se a versão na store mudou desde o último check, mostrar novamente
    if (record.storeVersion !== storeVersion) return true;

    const elapsedMs = Date.now() - record.shownAt;
    return elapsedMs >= TWENTY_FOUR_HOURS_MS;
  } catch {
    return true;
  }
}

/**
 * Salva no chrome.storage.local o registro de exibição.
 */
async function saveNotificationRecord(storeVersion: string): Promise<void> {
  try {
    const record: UpdateCheckRecord = {
      storeVersion,
      shownAt: Date.now(),
    };
    await chrome.storage.local.set({ [STORAGE_KEY]: record });
  } catch {
    // falha silenciosa — não deve derrubar o fluxo
  }
}

/**
 * Remove o container do DOM quando o usuário fecha o card.
 */
function removeContainer(): void {
  const container = document.getElementById(CONTAINER_ID);
  container?.remove();
}

/**
 * Monta o card de notificação de atualização no DOM.
 */
function mountNotifier(currentVersion: string, storeVersion: string): void {
  // Garante que não há duplicata
  if (document.getElementById(CONTAINER_ID)) return;

  const container = document.createElement("div");
  container.id = CONTAINER_ID;
  document.body.appendChild(container);

  const root = createRoot(container);
  root.render(
    <StrictMode>
      <UpdateNotifier
        currentVersion={currentVersion}
        storeVersion={storeVersion}
        onDismiss={removeContainer}
      />
    </StrictMode>,
  );
}

/**
 * Ponto de entrada do módulo.
 * Deve ser chamado uma vez após a inicialização da extensão.
 * Falhas internas não propagam exceções ao chamador.
 */
export async function initUpdateChecker(): Promise<void> {
  try {
    const currentVersion = chrome.runtime.getManifest().version;
    const result = await fetchStoreVersion();

    if (!result) return;

    // Se a flag sw for false, a exibição está desativada pelo servidor
    if (!result.sw) return;

    if (!isNewerVersion(result.version, currentVersion)) return;

    const show = await shouldShowNotification(result.version);
    if (!show) return;

    await saveNotificationRecord(result.version);
    mountNotifier(currentVersion, result.version);
  } catch {
    // falha silenciosa — módulo independente, jamais deve quebrar a extensão
  }
}
