import { twMerge } from "tailwind-merge";
import { getIconByType } from "./header";
import { useContext } from "react";
import { Group } from "../models/db";
import { HeaderContext } from "./providers/header-context";
import { Settings2 } from "lucide-react";

export default function GroupCard({
  item,
  className,
}: {
  item: Group;
  className?: string;
}) {
  const Icon = getIconByType("group");
  const { setActiveItem, setTab } = useContext(HeaderContext);

  function handleClickActive() {
    setActiveItem({ group: item });
    setTab("group");
  }

  return (
    <button
      onClick={handleClickActive}
      style={{ backgroundColor: item.color || "#2e2e2e" }}
      className={twMerge(
        "w-full flex items-center justify-between gap-3 rounded p-2 text-white duration-300 hover:opacity-75",
        className
      )}
    >
      <div className="flex items-center gap-3">
        <Icon className="size-3" fill="currentColor" />
        <span className="text-sm truncate">{item.title}</span>
      </div>
      <div className="flex items-center gap-3">
        <Settings2 className="w-4 min-w-4" />
      </div>
    </button>
  );
}
