import { useContext, useEffect, useState } from "react";
import { Check } from "lucide-react";
import { SessionContext } from "../providers/session-context";
import { HeaderContext } from "../providers/header-context";
import { getActiveUser } from "../utils/functions";
import { MaturadorDebug } from "../login-models/debug/maturador-debug";
import db, { MaturadorConfig } from "../../models/db";

// Variável para ativar/desativar o debug do maturador
const DEBUG_MATURADOR = false;

export default function MenuMaturadorTab() {
  const { session } = useContext(SessionContext);
  const { setShowCheckout, setModelTab, setTab } = useContext(HeaderContext);
  const [ativo, setAtivo] = useState(false);
  const [loading, setLoading] = useState(true);
  const [whatsapp, setWhatsapp] = useState<string>("");
  const [delayMin, setDelayMin] = useState<number>(1);
  const [delayMax, setDelayMax] = useState<number>(2);
  const [salvando, setSalvando] = useState(false);
  const [mensagemSucesso, setMensagemSucesso] = useState(false);
  const [configId, setConfigId] = useState<number | undefined>();

  useEffect(() => {
    let cancelado = false;

    async function bootstrap() {
      try {
        const config = await db.maturador_config.limit(1).first();
        if (config && !cancelado) {
          setConfigId(config.id);
          setAtivo(config.ativo);
          setDelayMin(config.intervaloMin || 1);
          setDelayMax(config.intervaloMax || 2);
        }
      } catch (error) {
        console.error("Erro ao carregar config local do maturador:", error);
      } finally {
        if (!cancelado) {
          await carregarEstado();
        }
      }
    }

    bootstrap();

    return () => {
      cancelado = true;
    };
  }, []);

  async function carregarEstado() {
    setLoading(true);
    try {
      const activeUser = await getActiveUser();
      let whatsappNumber = "";
      if (activeUser) {
        whatsappNumber = activeUser._serialized || activeUser.toString();
        setWhatsapp(whatsappNumber);
      }

      if (!whatsappNumber) {
        return;
      }

      const response = await chrome.runtime.sendMessage({
        action: "maturador.get",
      });

      if (!response?.ok) {
        return;
      }

      if (!response.temPermissao) {
        setAtivo(false);
        await persistLocalConfig(false, delayMin, delayMax);
        return;
      }

      if (response.maturador && Array.isArray(response.maturador)) {
        const registroAtual = response.maturador.find(
          (item: any) => item.whatsapp === whatsappNumber
        );

        if (registroAtual) {
          const novoDelayMin = registroAtual.delayMin || 1;
          const novoDelayMax = registroAtual.delayMax || 2;
          setAtivo(registroAtual.ligado || false);
          setDelayMin(novoDelayMin);
          setDelayMax(novoDelayMax);
          await persistLocalConfig(
            registroAtual.ligado || false,
            novoDelayMin,
            novoDelayMax
          );
        }
      }
    } catch (error) {
      console.error("Erro ao carregar estado do maturador:", error);
    } finally {
      setLoading(false);
    }
  }

  async function persistLocalConfig(
    ativoState: boolean,
    min: number,
    max: number
  ) {
    try {
      if (configId) {
        // Atualiza registro existente
        await db.maturador_config.update(configId, {
          ativo: ativoState,
          intervaloMin: min,
          intervaloMax: max,
        });
      } else {
        // Cria novo registro
        const payload: Omit<MaturadorConfig, "id"> = {
          ativo: ativoState,
          intervaloMin: min,
          intervaloMax: max,
          limiteEnvio: 3,
          comandoLigar: "numale",
          comandoDesligar: "",
        };
        const savedId = await db.maturador_config.add(payload);
        setConfigId(savedId);
      }
    } catch (error) {
      console.error("Erro ao salvar config local do maturador:", error);
    }
  }

  async function ativarMaturador() {
    if (loading || !whatsapp || salvando) return;

    const temPermissao = session?.permissions?.includes("MATURADOR");

    if (!temPermissao) {
      setModelTab("maturador");
      setShowCheckout(true);
      return;
    }

    try {
      setSalvando(true);
      setMensagemSucesso(false);

      // 1. Atualiza o backend que o maturador está ligado
      const response = await chrome.runtime.sendMessage({
        action: "maturador.toggle",
        data: {
          ligado: true,
          whatsapp,
          delayMin,
          delayMax,
        },
      });

      if (!response?.ok) {
        throw new Error(response?.error || "Erro ao iniciar maturador");
      }

      // 2. Salva localmente
      await persistLocalConfig(true, delayMin, delayMax);

      // 3. Salva status no storage para listener do finishShooting
      await chrome.storage.local.set({
        maturadorStatus: {
          ativo: true,
          whatsapp,
          delayMin,
          delayMax,
          updatedAt: Date.now(),
        },
      });

      setAtivo(true);
      setMensagemSucesso(true);
      setTimeout(() => setMensagemSucesso(false), 2500);

      // 4. Inicia o shoot (disparador oculto)
      await chrome.runtime.sendMessage({
        action: "maturador.startShoot",
      });

      console.log("[Maturador] Maturador iniciado com sucesso!");
    } catch (error) {
      console.error("Erro ao iniciar/atualizar maturador:", error);
      window.dispatchEvent(
        new CustomEvent("showErrorMessage", {
          detail: {
            message: "Erro ao iniciar maturador",
            details: error,
          },
        })
      );
    } finally {
      setSalvando(false);
    }
  }

  async function desativarMaturador() {
    if (loading || !whatsapp || salvando) return;

    try {
      setSalvando(true);

      // PRIMEIRO: Atualiza o status no storage para parar imediatamente
      await chrome.storage.local.set({
        maturadorStatus: {
          ativo: false,
          whatsapp,
          delayMin,
          delayMax,
          updatedAt: Date.now(),
        },
      });

      // SEGUNDO: Para todos os disparos do maturador em andamento
      try {
        const allShoots = await db.shoots.toArray();
        const maturadorShoots = allShoots.filter(
          (s: any) => s.hidden === true && s.status === "shooting"
        );

        if (maturadorShoots && maturadorShoots.length > 0) {
          console.log(
            "[Maturador] Parando disparos do maturador em andamento..."
          );

          for (const shoot of maturadorShoots) {
            if (shoot.id) {
              // Dispara evento para pausar/cancelar o disparo
              window.dispatchEvent(
                new CustomEvent("pauseShoting", {
                  detail: { id: shoot.id },
                })
              );

              // Aguarda um pouco para garantir que o evento foi processado
              await new Promise((resolve) => setTimeout(resolve, 50));
            }
          }
        }
      } catch (error) {
        console.error("[Maturador] Erro ao parar disparos:", error);
        // Continua mesmo se falhar
      }

      const response = await chrome.runtime.sendMessage({
        action: "maturador.toggle",
        data: {
          ligado: false,
          whatsapp,
          delayMin,
          delayMax,
        },
      });

      if (!response?.ok) {
        throw new Error(response?.error || "Erro ao parar maturador");
      }

      await persistLocalConfig(false, delayMin, delayMax);

      setAtivo(false);
      console.log("[Maturador] Maturador pausado com sucesso!");
    } catch (error) {
      console.error("Erro ao parar maturador:", error);
      window.dispatchEvent(
        new CustomEvent("showErrorMessage", {
          detail: {
            message: "Erro ao parar maturador",
            details: error,
          },
        })
      );
    } finally {
      setSalvando(false);
    }
  }

  async function handleToggleMaster() {
    if (ativo) {
      await desativarMaturador();
    } else {
      await ativarMaturador();
    }
  }

  function handleFechar() {
    // Fecha o menu lateral voltando para "main"
    setTab("main");
  }

  if (loading) {
    return (
      <div className="w-full flex items-center justify-center p-10">
        <span className="text-sm">Carregando...</span>
      </div>
    );
  }

  return (
    <div className="w-full flex flex-col gap-4">
      <div className="w-full flex items-center justify-between">
        <h2 className="text-lg font-bold">Aquecedor de WhatsApp</h2>
      </div>

      <div className="w-full flex flex-col gap-4">
        <div className="w-full flex flex-col gap-4 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
          <div className="flex flex-col gap-1">
            <span className="text-xs uppercase tracking-wide text-foreground/60">
              Status
            </span>
            <span
              className={`text-xl font-semibold ${
                ativo ? "text-green-400" : "text-red-400"
              }`}
            >
              {ativo ? "Maturador ativo" : "Maturador inativo"}
            </span>
            <p className="text-xs text-foreground/60">
              {ativo
                ? "Mensagens estão sendo enviadas continuamente até você pausar manualmente."
                : "Clique em Iniciar maturador para começar o ciclo automático imediatamente."}
            </p>
          </div>

          <div className="flex flex-col gap-2">
            <button
              onClick={handleToggleMaster}
              disabled={salvando || loading}
              className="w-full bg-primary text-white font-medium text-center p-2 rounded disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {salvando
                ? "Aplicando..."
                : ativo
                  ? "Pausar maturador"
                  : "Iniciar maturador"}
            </button>
            <span className="text-xs text-foreground/60">
              {ativo
                ? "Clique para pausar imediatamente."
                : "Ao iniciar, o RevProtect inicia os envios."}
            </span>
          </div>

          {mensagemSucesso && (
            <div className="flex items-center gap-2 text-xs text-green-400">
              <Check className="size-4" />
              <span>Configurações atualizadas!</span>
            </div>
          )}
        </div>

        <div className="w-full flex flex-col gap-4 bg-secondary/30 rounded p-5 text-sm hidden">
          <span className="font-medium">Intervalo entre mensagens</span>

          <div className="flex flex-wrap items-end gap-4">
            <div className="flex items-end gap-2">
              <input
                type="number"
                min={1}
                max={60}
                id="delayMin"
                value={delayMin}
                onChange={(e) => {
                  const val = parseInt(e.target.value) || 1;
                  setDelayMin(val);
                  if (val > delayMax) {
                    setDelayMax(val);
                  }
                }}
                className="w-14 bg-secondary border border-transparent focus:border-primary text-foreground p-2 rounded [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                placeholder="1"
              />
              <label htmlFor="delayMin">minutos</label>
            </div>

            <span className="text-xs text-foreground/60">até</span>

            <div className="flex items-end gap-2">
              <input
                type="number"
                min={1}
                max={60}
                id="delayMax"
                value={delayMax}
                onChange={(e) => {
                  const val = parseInt(e.target.value) || 2;
                  setDelayMax(val);
                  if (val < delayMin) {
                    setDelayMin(val);
                  }
                }}
                className="w-14 bg-secondary border border-transparent focus:border-primary text-foreground p-2 rounded [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                placeholder="2"
              />
              <label htmlFor="delayMax">minutos</label>
            </div>
          </div>

          <p className="text-xs text-foreground/60">
            Os valores definidos acima são aplicados sempre que você iniciar ou
            atualizar o maturador.
          </p>
        </div>
      </div>

      {DEBUG_MATURADOR && <MaturadorDebug />}
    </div>
  );
}
