// Debug bridge (DEV only): permite rodar diagnósticos via Console mesmo sem WPP exposto.
// Fica eliminado do bundle quando DEV !== "true" (dotenv-webpack + terser).
const REVZAP_DEV_DEBUG = process.env.DEV === "true";

/**
 * Log condicional que só aparece quando DEV="true"
 * @param prefix - Prefixo do log (ex: "[getGroups]")
 * @param args - Argumentos para console.log
 */
const devLog = (...args: any[]) => {
  if (REVZAP_DEV_DEBUG) {
    console.log(...args);
  }
};

/**
 * Warning condicional que só aparece quando DEV="true"
 * @param prefix - Prefixo do warning
 * @param args - Argumentos para console.warn
 */
const devWarn = (...args: any[]) => {
  if (REVZAP_DEV_DEBUG) {
    console.warn(...args);
  }
};

/**
 * Error sempre aparece (mesmo em produção), mas com contexto adicional em DEV
 * @param args - Argumentos para console.error
 */
const devError = (...args: any[]) => {
  console.error(...args);
};

const getStepUserKey = (id?: string) => {
  if (!id) return "";
  // Para grupos, mantemos o id completo (inclui sufixo @g.us).
  if (id.endsWith("@g.us")) return id;
  // Para contatos, usamos a parte antes do @ para igualar @c.us vs @lid.
  const num = id.split("@")[0] || id;
  // Normaliza variante brasileira 13 dígitos → 12 dígitos:
  // 55 (país) + DDD (2) + 9 (extra) + 8 = 13 → remove o 9 do DDN → 12.
  // Isso garante que 5511912345678 e 551112345678 sejam tratados como o mesmo contato.
  if (num.length === 13 && num.startsWith("55")) {
    return num.slice(0, 4) + num.slice(5);
  }
  return num;
};

const findStepUserIndex = (users: string[], id?: string) => {
  if (!id) return -1;
  const key = getStepUserKey(id);
  if (!key) return -1;
  return users.findIndex((u) => getStepUserKey(u) === key);
};

