export async function addUsersToStep(stepId: number, userId: string) {
  if (!userId) return;

  // Remove sufixo @lid duplicado que pode ser gerado quando chatId já tem @lid
  // e o código que constrói cleanChatId apendava @lid novamente: 'xxx@lid@lid' → 'xxx@lid'
  const normalizedUserId = userId
    .replace(/(@lid)+$/i, "@lid")
    .replace(/(@c\.us)+$/i, "@c.us");
  // Usa .modify() para operação atômica (readwrite transaction no Dexie).
  // Evita race condition do read-modify-write manual quando múltiplos chats
  // de um grupo são adicionados em paralelo pelo disparo em massa.
  const updated = await db.steps
    .where("id")
    .equals(stepId)
    .modify((step) => {
      // Aproveita a transação para limpar possíveis entradas @lid@lid já existentes.
      const users = (Array.isArray(step.users) ? step.users : []).map((u) =>
        typeof u === "string"
          ? u.replace(/(@lid)+$/i, "@lid").replace(/(@c\.us)+$/i, "@c.us")
          : u,
      );

      const existingIndex = findStepUserIndex(users, normalizedUserId);

      if (existingIndex >= 0) {
        const existing = users[existingIndex];
        // Preferir @c.us (canônico) sobre @lid quando disponível.
        if (!normalizedUserId.endsWith("@lid") && existing.endsWith("@lid")) {
          users[existingIndex] = normalizedUserId;
        }
        // Se chegou aqui com @lid e existente é @c.us, mantém @c.us.
        // Se chegou aqui igual, sem duplicata.
      } else {
        users.push(normalizedUserId);
      }

      step.users = users;
    });

  if (updated === 0) {
    console.log("Passo não encontrado:", stepId);
  }
}

