export async function changeChatViewWithStep(stepId?: number) {
  devLog("[changeChatViewWithStep] Chamado com stepId:", stepId);

  if (!stepId) {
    devLog("[changeChatViewWithStep] stepId vazio, limpando filtro");
    window.dispatchEvent(
      new CustomEvent("setStep", {
        detail: { chats: undefined },
      }),
    );

    return;
  }

  const step = await getStepById(stepId);
  devLog("[changeChatViewWithStep] Step encontrado:", {
    id: step?.id,
    title: step?.title,
    usersCount: step?.users?.length,
    users: step?.users,
  });

  if (!step || !step.users) {
    devWarn("[changeChatViewWithStep] Step ou users inválidos!");
    return;
  }

  // CRÍTICO: Clonar o array para garantir serialização correta no CustomEvent
  // Arrays do Dexie não são serializados corretamente entre isolated e MAIN world
  const chatsArray = Array.from(step.users);
  devLog(
    "[changeChatViewWithStep] Disparando evento setStep com",
    chatsArray.length,
    "chats:",
    chatsArray,
  );

  window.dispatchEvent(
    new CustomEvent("setStep", {
      detail: { chats: chatsArray },
    }),
  );
}

export async function convertAudioToOgg({
  file,
  fileName,
}: ConvertAudioToOgg): Promise<ConvertAudioToOggResponse> {
  return await chrome.runtime
    .sendMessage({
      action: "extension.convert-audio",
      data: {
        file,
        fileName,
      },
    })
    .then((response) => {
      if (response.error) {
        throw new Error(
          response.error ?? "Ocorreu um erro ao converter o áudio",
        );
      }

      return response;
    });
}

