export const waitForShootingPermission = (itemId: number): Promise<boolean> => {
  return new Promise((resolve) => {
    const onAllowed = (e: Event) => {
      const { id } = (e as CustomEvent<{ id: number }>).detail;
      if (id === itemId) {
        cleanup();
        resolve(true);
      }
    };

    const onInProgress = (e: Event) => {
      const { attemptedShootingId } = (
        e as CustomEvent<{
          currentShootingId: number;
          attemptedShootingId: number;
        }>
      ).detail;
      if (attemptedShootingId === itemId) {
        cleanup();
        resolve(false);
      }
    };

    const cleanup = () => {
      window.removeEventListener("shootingAllowed", onAllowed);
      window.removeEventListener("shootingAlreadyInProgress", onInProgress);
    };

    window.addEventListener("shootingAllowed", onAllowed);
    window.addEventListener("shootingAlreadyInProgress", onInProgress);

    window.dispatchEvent(
      new CustomEvent("checkActiveShooting", { detail: { id: itemId } }),
    );

    setTimeout(() => {
      cleanup();
      resolve(false);
    }, 1000);
  });
};

