export async function delUsersToStep(stepId: number, userId: string) {
  if (!userId) return;

  const normalizedUserId = userId
    .replace(/(@lid)+$/i, "@lid")
    .replace(/(@c\.us)+$/i, "@c.us");

  // Usa .modify() para operação atômica e remove TODAS as entradas que
  // correspondam ao mesmo contato (inclusive duplicatas com variante de número BR
  // e entradas @lid@lid corrompidas).
  const updated = await db.steps
    .where("id")
    .equals(stepId)
    .modify((step) => {
      const targetKey = getStepUserKey(normalizedUserId);
      step.users = (step.users || [])
        .map((u) =>
          typeof u === "string"
            ? u.replace(/(@lid)+$/i, "@lid").replace(/(@c\.us)+$/i, "@c.us")
            : u,
        )
        .filter((user) => getStepUserKey(user) !== targetKey);
    });

  if (updated === 0) {
    console.log("Passo não encontrado:", stepId);
  }
}

export async function markShootToSent(id: number, shoots: ShootingChat[]) {
  const selectedItem = await db.shoots.where("id").equals(id).first();

  if (!selectedItem) {
    console.log("Item não foi encontrado");
    return;
  }

  // Permite persistir contatos tanto em "shooting" quanto em "paused"
  // para não perder flags de sent/error quando o pause handler roda antes
  if (
    selectedItem.status !== "shooting" &&
    selectedItem.status !== "paused" &&
    !selectedItem.schedule
  ) {
    return;
  }

  return await db.shoots.put({ ...selectedItem, contacts: shoots });
}

export async function removePhoneFromShooting(id: number, phone: string) {
  const selectedItem = await db.shoots.where("id").equals(id).first();

  if (!selectedItem) {
    console.log("Item não foi encontrado");
    return;
  }

  const updatedShoots = selectedItem.contacts?.filter(
    (shoot) => shoot.chatId !== phone,
  );

  return await db.shoots.put({
    ...selectedItem,
    contacts: updatedShoots || [],
  });
}

export async function getSelectedItems(items: ShootItem[]): Promise<any[]> {
  return await Promise.all(
    items.map(async (item) => {
      if (item.type === "script") {
        const script = await getScriptById(item.id);
        if (!script) return null;

        const orderedScriptItems = [...(script.items || [])].sort(
          (a, b) => (a.index ?? 0) - (b.index ?? 0),
        );

        const scriptItems = await Promise.all(
          orderedScriptItems.map(async (scriptItem) => {
            if (
              scriptItem.type === "addStep" ||
              scriptItem.type === "removeStep"
            ) {
              const step = await getStepById(scriptItem.id ?? 0);

              if (!step) return null;

              return {
                ...step,
                type: scriptItem.type,
                itemType: scriptItem.type,
              };
            } else if (scriptItem.type === "wait") {
              return {
                ...scriptItem,
                type: "wait",
              };
            } else if (scriptItem.type === "randomizer") {
              const randomizer = await db.randomizers.get(scriptItem.id ?? 0);

              if (!randomizer) return null;

              return {
                ...randomizer,
                type: "randomizer",
              } as Randomizer;
            } else {
              const item = await getItemById(scriptItem.id ?? 0);

              if (!item) {
                return {
                  ...scriptItem,
                  delay: scriptItem.delay,
                  type: scriptItem.type,
                };
              }

              return {
                ...item,
                delay: scriptItem.delay,
                type: item.type,
              };
            }
          }),
        );

        return { ...script, items: scriptItems, type: "script" };
      }

      return await getItemById(item.id);
    }),
  );
}

export async function getAllItemsOnScript(items: ShootItem[]): Promise<any[]> {
  return await Promise.all(
    items.map(async (item) => {
      if (item.type === "script") {
        const script = await getScriptById(item.id);
        if (!script) return null;
        const orderedScriptItems = [...(script.items || [])].sort(
          (a, b) => (a.index ?? 0) - (b.index ?? 0),
        );

        const scriptItems = await Promise.all(
          orderedScriptItems.map(async (scriptItem) => {
            if (scriptItem.type === "randomizer") {
              const randomizer = await db.randomizers.get(scriptItem.id ?? 0);

              if (!randomizer) return null;

              return {
                ...randomizer,
                type: "randomizer",
              } as Randomizer;
            }

            const nestedItem = await getItemById(scriptItem.id ?? 0);

            return {
              ...nestedItem,
              delay: scriptItem.delay,
              type: scriptItem.type,
            };
          }),
        );

        return { ...script, items: scriptItems, type: "script" };
      }

      return await getItemById(item.id);
    }),
  );
}

