// Função utilitária para desativar o maturador
export async function desativarMaturadorCompleto(): Promise<boolean> {
  try {
    const activeUser = await getActiveUser();

    if (!activeUser) {
      return false;
    }

    const whatsappNumber = activeUser._serialized || activeUser.toString();

    // Busca os valores atuais do maturador (delayMin e delayMax)
    let delayMin = 1;
    let delayMax = 2;

    // Tenta obter do storage local primeiro
    const res = await chrome.storage.local.get("maturadorStatus");
    const status = res.maturadorStatus;
    if (status?.delayMin && status?.delayMax) {
      delayMin = status.delayMin;
      delayMax = status.delayMax;
    } else {
      // Se não encontrar no storage, busca do banco local
      const config = await db.maturador_config.limit(1).first();
      if (config) {
        delayMin = config.intervaloMin || 1;
        delayMax = config.intervaloMax || 2;
      }
    }

    // Desativa no backend
    const response = await chrome.runtime.sendMessage({
      action: "maturador.toggle",
      data: {
        ligado: false,
        whatsapp: whatsappNumber,
        delayMin,
        delayMax,
      },
    });

    if (!response?.ok) {
      console.error(
        "[Maturador] Erro ao desativar no backend:",
        response?.error,
      );
      // Continua mesmo se falhar no backend para limpar localmente
    }

    // Atualiza status no storage
    await chrome.storage.local.set({
      maturadorStatus: {
        ativo: false,
        whatsapp: whatsappNumber,
        delayMin,
        delayMax,
        updatedAt: Date.now(),
      },
    });

    // Atualiza no banco local
    const config = await db.maturador_config.limit(1).first();
    if (config) {
      await db.maturador_config.update(config.id, { ativo: false });
    }

    // Cancela o disparo do maturador em andamento, se houver
    try {
      // Busca shoots do maturador (hidden: true) que estão em shooting
      const allShoots = await db.shoots.toArray();
      const maturadorShoots = allShoots.filter(
        (s: any) => s.hidden === true && s.status === "shooting",
      );

      if (maturadorShoots && maturadorShoots.length > 0) {
        console.log(
          "[Maturador] Cancelando disparos do maturador em andamento...",
        );

        // Para cada shoot do maturador em andamento, cancela o disparo
        for (const shoot of maturadorShoots) {
          if (shoot.id) {
            // Dispara evento para pausar/cancelar o disparo
            window.dispatchEvent(
              new CustomEvent("pauseShoting", {
                detail: { id: shoot.id },
              }),
            );

            // Aguarda um pouco para garantir que o evento foi processado
            await new Promise((resolve) => setTimeout(resolve, 100));

            // Atualiza o status do shoot
            await db.shoots.update(shoot.id, { status: "shooted" });

            // Dispara evento para finalizar o disparo e limpar o estado
            window.dispatchEvent(
              new CustomEvent("finishShooting", {
                detail: { id: shoot.id },
              }),
            );
          }
        }
      }
    } catch (error) {
      console.error(
        "[Maturador] Erro ao cancelar disparos do maturador:",
        error,
      );
      // Continua mesmo se falhar
    }

    console.log("[Maturador] Maturador desativado com sucesso!");
    return true;
  } catch (error) {
    console.error("[Maturador] Erro ao desativar maturador:", error);
    return false;
  }
}

// Função para verificar se o maturador está ativo
export async function verificarMaturadorAtivo(): Promise<boolean> {
  try {
    // Primeiro tenta verificar no storage local
    const res = await chrome.storage.local.get("maturadorStatus");
    const status = res.maturadorStatus;

    if (status?.ativo) {
      return true;
    }

    // Se não encontrar no storage, verifica no backend
    const response = await chrome.runtime.sendMessage({
      action: "maturador.get",
    });

    if (
      response?.ok &&
      response.maturador &&
      Array.isArray(response.maturador)
    ) {
      const activeUser = await getActiveUser();
      if (activeUser) {
        const whatsappNumber = activeUser._serialized || activeUser.toString();
        const registroAtual = response.maturador.find(
          (item: any) =>
            item.whatsapp === whatsappNumber && item.ligado === true,
        );
        return !!registroAtual;
      }
    }

    return false;
  } catch (error) {
    console.error("[Maturador] Erro ao verificar maturador:", error);
    return false;
  }
}

export async function getContactsByStep(
  steps: number[],
  type: "all" | "archived" | "not-archived" = "all",
  resolvePhone: boolean = false,
): Promise<string[][]> {
  const contactsByStep = await Promise.all(
    steps.map(async (stepId) => {
      const step = await getStepById(stepId);
      if (!step) return [] as string[][];

      const contactsForStep = await Promise.all(
        step.users.map(async (userId) => {
          const contact = await getContactById(userId, type, resolvePhone);
          return contact
            ? ([contact.id, contact.name] as [string, string])
            : null;
        }),
      );

      return contactsForStep.filter((c): c is [string, string] => c !== null);
    }),
  );

  return contactsByStep.flat();
}
