import { Check } from "lucide-react";
import { urls } from "../../../utils/checkout";

export function CardMensal() {
  return (
    <div className="p-5 min-w-72 flex-1 flex flex-col gap-5 rounded border border-solid border-secondary">
      <h3 className="font-bold text-lg">Plano mensal</h3>

      <div className="flex flex-col gap-1">
        <span className="text-sm">
          De <s>R$56,90</s> por apenas
        </span>
        <h3 className="text-2xl font-bold">R$36,90/mês</h3>
        <span className="text-sm invisible">_</span>
      </div>

      <a
        href={urls.saver.mensal}
        rel="noopener noreferrer"
        target="_blank"
        className="w-full p-2 rounded border border-solid border-primary text-primary hover:bg-primary hover:text-white duration-300 text-center"
      >
        Assinar agora
      </a>

      <hr className="w-full" />

      <div className="w-full flex flex-col gap-2">
        <div className="flex items-center gap-2">
          <Check className="size-4 text-primary" />
          <span>1 usuário por licença</span>
        </div>
        <div className="flex items-center gap-2">
          <Check className="size-4 text-primary" />
          <span>1 mês de acesso</span>
        </div>
        <div className="flex items-center gap-2">
          <Check className="size-4 text-primary" />
          <span>Renovação automática</span>
        </div>
      </div>
    </div>
  );
}
