import clsx from "clsx";
import { Check, Phone, Trash, X } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { twMerge } from "tailwind-merge";
import Spinner from "./spinner";
import { Shooting } from "./tabs/shooting";
import { getContactById } from "./utils/functions";

export default function ShootingItem({
  chats,
  onRemove,
  canRemove,
  isRemoving,
}: {
  chats?: Shooting["chats"];
  onRemove?: (chatId: string) => void;
  canRemove?: boolean;
  isRemoving?: boolean;
}) {
  return (
    <div className="w-full flex flex-col gap-5 rounded p-5 bg-gradient-to-r from-neutral via-neutral to-transparent">
      <div className="flex w-full flex-col gap-2 overflow-auto">
        {chats && chats.length > 0 ? (
          <>
            <button className="w-full flex items-center justify-between gap-2">
              <span>Ver usuários</span>
            </button>
            {chats.map((i) => (
              <Label
                key={i.chatId}
                user={i.userId}
                server={i.server ?? undefined}
                selected={i.sent}
                error={i.error}
                chatId={i.chatId}
                onRemove={onRemove}
                canRemove={canRemove}
                isRemoving={isRemoving}
              />
            ))}
          </>
        ) : (
          <p className="w-full h-full flex items-center justify-center">
            Sem usuários para disparar
          </p>
        )}
      </div>
    </div>
  );
}

function Label({
  user,
  server,
  selected,
  error,
  chatId,
  onRemove,
  canRemove,
  isRemoving,
}: {
  user?: string;
  server?: string;
  selected?: boolean;
  error?: boolean;
  chatId?: string;
  onRemove?: (chatId: string) => void;
  canRemove?: boolean;
  isRemoving?: boolean;
}) {
  if (!user) return null;

  const isLid =
    server === "lid" ||
    server === "@lid" ||
    user.endsWith("@lid") ||
    (chatId ? chatId.endsWith("@lid") : false);

  const [resolvedPhone, setResolvedPhone] = useState<string | null>(null);
  const [resolvedTitle, setResolvedTitle] = useState<string | null>(null);

  useEffect(() => {
    if (!isLid || !chatId) return;

    let alive = true;

    (async () => {
      try {
        const contact = await getContactById(chatId, "all", true);
        if (!alive || !contact) return;

        const phone = contact.id?.split("@")[0] || contact.id;
        setResolvedPhone(phone || null);
        setResolvedTitle(contact.name || phone || null);
      } catch {
        // Se falhar, mantemos fallback visual (não afeta envio).
      }
    })();

    return () => {
      alive = false;
    };
  }, [isLid, chatId]);

  const displayUser = useMemo(() => {
    if (!isLid) return user;
    if (resolvedPhone) return resolvedPhone;
    // fallback: ao invés de "Número desconhecido", exibe um identificador útil
    return user.replace(/@lid$/i, "") || user;
  }, [isLid, resolvedPhone, user]);

  const titleUser = useMemo(() => {
    if (!isLid) return user;
    return resolvedTitle || resolvedPhone || user;
  }, [isLid, resolvedTitle, resolvedPhone, user]);

  return (
    <div
      className={twMerge(
        "w-full flex items-center justify-between gap-2 p-2 rounded duration-300",
        selected && !error
          ? "bg-primary"
          : error
            ? "bg-red-500"
            : "bg-secondary/50",
      )}
    >
      <div className="flex items-center gap-2 min-w-0 flex-1">
        <Phone
          className={clsx(
            "size-3 flex-shrink-0",
            (error || selected) && "text-white",
          )}
        />
        <span
          title={titleUser}
          className={clsx(
            "text-sm truncate min-w-0",
            !error && !selected ? "text-text" : "text-white",
          )}
        >
          {displayUser}
        </span>
      </div>
      <div className="flex items-center gap-2 flex-shrink-0">
        {canRemove && onRemove && chatId && (
          <button
            type="button"
            disabled={isRemoving}
            onClick={() => onRemove(chatId)}
            className={clsx(
              "transition-opacity duration-200",
              isRemoving && "opacity-50 cursor-not-allowed",
            )}
          >
            {isRemoving ? (
              <Spinner className="size-4" />
            ) : (
              <Trash
                className={clsx(
                  "size-4",
                  !error && !selected ? "text-text" : "text-white",
                )}
              />
            )}
          </button>
        )}
        {typeof selected !== "undefined" || typeof error !== "undefined" ? (
          error ? (
            <X className={twMerge("size-4 text-white")} />
          ) : (
            <Check
              className={twMerge("size-4 text-white", !selected && "invisible")}
            />
          )
        ) : null}
      </div>
    </div>
  );
}
