import { useLiveQuery } from "dexie-react-hooks";
import db from "../../models/db";
import { getIconByType } from "../header";
import ShootCard from "../shoot-cards";
import { Plus } from "lucide-react";
import { useContext, useState, useEffect } from "react";
import { HeaderContext } from "../providers/header-context";
import { twMerge } from "tailwind-merge";

export default function MenuShootListTab() {
  const { setTab, tabShooting, setTabShooting } = useContext(HeaderContext);
  const [tabFilter, setTabFilter] = useState<
    "no-shoot" | "shooting" | "shooted" | "schedule"
  >(tabShooting ?? "shooting");
  const shoots = useLiveQuery(() => db.shoots.toArray(), [], []);
  const Icon = getIconByType("shoot");

  useEffect(() => {
    setTabShooting(tabFilter);
  }, [tabFilter, setTabShooting]);

  function handleClick() {
    setTab("shoot");
  }

  return (
    <div className="w-full h-full flex flex-col items-center gap-5 overflow-auto">
      <button
        onClick={handleClick}
        className="w-full flex items-center justify-center gap-2 bg-primary text-white rounded px-5 py-2"
      >
        <Plus className="size-4" />
        <span>Novo disparo</span>
      </button>

      <div className="w-full flex items-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
        <Icon className="size-4" />
        <span className="text-center text-sm">Meus disparos</span>
      </div>

      <div className="w-full flex items-center justify-center gap-2">
        <Button
          name="Enviando"
          className="flex-1"
          selected={tabFilter === "shooting"}
          onClick={() => setTabFilter("shooting")}
        />
        <Button
          name="Rascunhos"
          className="flex-1"
          selected={tabFilter === "no-shoot"}
          onClick={() => setTabFilter("no-shoot")}
        />
        <Button
          name="Agendados"
          className="flex-1"
          selected={tabFilter === "schedule"}
          onClick={() => setTabFilter("schedule")}
        />
        <Button
          name="Enviados"
          className="flex-1"
          selected={tabFilter === "shooted"}
          onClick={() => setTabFilter("shooted")}
        />
      </div>

      <div className="w-full flex flex-col gap-2">
        {shoots
          .filter((item) => !item.hidden) // Ocultar shoots do maturador
          .filter((item) => {
            // Rascunhos: apenas disparos em massa sem status e sem agendamento
            if (tabFilter === "no-shoot") return !item.status && !item.schedule;

            // Enviando: status em progresso
            if (tabFilter === "shooting") return item.status === "shooting";

            // Enviados: status concluído
            if (tabFilter === "shooted") return item.status === "shooted";

            // Agendados: têm schedule, ainda não concluídos e não em execução
            if (tabFilter === "schedule")
              return (
                !!item.schedule &&
                (item.status === undefined ||
                  item.status === null ||
                  item.status === "scheduled")
              );
          })
          .map((item) => (
            <ShootCard key={item.id} item={item} />
          ))}
      </div>
    </div>
  );
}

function Button({
  name,
  selected,
  className,
  ...props
}: {
  name: string;
  selected?: boolean;
  className?: string;
} & React.HTMLAttributes<HTMLButtonElement>) {
  return (
    <button
      className={twMerge(
        "rounded p-2 text-xs duration-300",
        selected
          ? "bg-primary hover:bg-primary/80"
          : "bg-secondary/50 hover:bg-secondary",
        className
      )}
      {...props}
    >
      {name}
    </button>
  );
}
