import { ChevronLeft, Mail } from "lucide-react";
import { useContext, useEffect, useRef, useState } from "react";
import Loading from "../loading";
import { LoginTab } from "../providers/header-context";
import { SessionContext } from "../providers/session-context";
import InputPassword from "../input-password";

const ForgetPassword = ({
  setModelTab,
}: {
  setModelTab: (tab: LoginTab) => void;
}) => {
  const { forgetPassword, validateCode, changePassword } =
    useContext(SessionContext);
  const [isLoading, setIsLoading] = useState(false);
  const [isResending, setIsResending] = useState(false);
  const [resendCountdown, setResendCountdown] = useState(0);
  const [step, setStep] = useState<"email" | "code" | "new-password">("email");
  const [email, setEmail] = useState<string>("");
  const passwordRef = useRef<HTMLInputElement>(null);
  const passwordConfirmRef = useRef<HTMLInputElement>(null);
  const otpRefs = useRef<(HTMLInputElement | null)[]>([]);
  const [token, setToken] = useState<string>("");
  const [otpValues, setOtpValues] = useState<string[]>([
    "",
    "",
    "",
    "",
    "",
    "",
  ]);
  const [errors, setErrors] = useState<{
    form?: string;
  }>({});
  const [successMessage, setSuccessMessage] = useState<string>("");

  // Contador regressivo para reenvio de código
  useEffect(() => {
    if (resendCountdown > 0) {
      const timer = setTimeout(() => {
        setResendCountdown((prev) => prev - 1);
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [resendCountdown]);

  function handleResendCode() {
    if (resendCountdown > 0) return;

    setIsResending(true);
    setErrors({});
    setSuccessMessage("");

    forgetPassword(email)
      .then((response) => {
        if (!response?.ok) {
          setErrors({
            form:
              response?.message ||
              "Ocorreu um erro ao tentar reenviar o código!",
          });
        } else {
          setSuccessMessage("Código reenviado com sucesso!");
          setResendCountdown(60); // 60 segundos de cooldown
          setOtpValues(["", "", "", "", "", ""]);
          setTimeout(() => {
            setSuccessMessage("");
            otpRefs.current[0]?.focus();
          }, 3000);
        }
      })
      .catch((error) => {
        console.log(error);
        setErrors({
          form: error.message || "Ocorreu um erro ao tentar reenviar o código!",
        });
      })
      .finally(() => setIsResending(false));
  }

  function handleSubmitEmail(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();

    if (!email) return;

    setIsLoading(true);

    forgetPassword(email)
      .then((response) => {
        if (!response?.ok) {
          setErrors((prev) => {
            const newErrors = { ...prev };
            newErrors.form =
              response?.message || "Ocorreu um erro ao tentar resetar a senha!";
            return newErrors;
          });
        } else {
          setStep("code");
          setErrors({});
          setResendCountdown(60);
          setTimeout(() => otpRefs.current[0]?.focus(), 100);
        }
      })
      .catch((error) => {
        console.log(error);
        setErrors((prev) => {
          const newErrors = { ...prev };
          newErrors.form =
            error.message || "Ocorreu um erro ao tentar resetar a senha!";
          return newErrors;
        });
      })
      .finally(() => setIsLoading(false));
  }

  function handleSubmitCode(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();

    const code = otpValues.join("");

    if (code.length !== 6) {
      setErrors({ form: "Por favor, digite o código completo de 6 dígitos" });
      return;
    }

    if (!email) return;

    setIsLoading(true);

    validateCode(code, email)
      .then((response) => {
        if (!response?.ok) {
          setErrors({
            form: response?.message || "Ocorreu um erro ao validar o código",
          });
        } else {
          if (!response?.token) {
            setErrors({
              form: "Ocorreu um erro ao validar o código",
            });

            return;
          }

          setStep("new-password");
          setToken(response.token);
          setErrors({});
        }
      })
      .finally(() => setIsLoading(false));
  }

  function handleOtpChange(index: number, value: string) {
    if (value && !/^\d$/.test(value)) return;

    const newOtpValues = [...otpValues];
    newOtpValues[index] = value;
    setOtpValues(newOtpValues);

    if (value && index < 5) {
      otpRefs.current[index + 1]?.focus();
    }
  }

  function handleOtpKeyDown(
    index: number,
    e: React.KeyboardEvent<HTMLInputElement>
  ) {
    if (e.key === "Backspace" && !otpValues[index] && index > 0) {
      otpRefs.current[index - 1]?.focus();
    }
  }

  function handleOtpPaste(e: React.ClipboardEvent<HTMLInputElement>) {
    e.preventDefault();
    const pastedData = e.clipboardData.getData("text/plain").trim();

    if (/^\d{6}$/.test(pastedData)) {
      const digits = pastedData.split("");
      setOtpValues(digits);
      otpRefs.current[5]?.focus();
    }
  }

  function handleSubmitNewPassword(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();

    const password = passwordRef.current?.value;

    const passwordConfirm = passwordConfirmRef.current?.value;

    if (!password || !passwordConfirm) return;

    if (passwordConfirm && passwordConfirm.length < 8) {
      setErrors((prev) => {
        const newErrors = { ...prev };
        newErrors.form = "A senha precisa ter no mínimo 8 caracteres!";
        return newErrors;
      });
      return;
    }

    if (password !== passwordConfirm) {
      setErrors((prev) => {
        const newErrors = { ...prev };
        newErrors.form = "As senhas digitadas não coincidem!";
        return newErrors;
      });
      return;
    }

    setIsLoading(true);

    changePassword(password, token)
      .then((response) => {
        if (!response?.ok) {
          setErrors((prev) => {
            const newErrors = { ...prev };
            newErrors.form =
              response?.message || "Ocorreu um erro ao tentar alterar a senha!";
            return newErrors;
          });
        } else {
          setModelTab("login");
          setErrors({});
        }
      })
      .finally(() => setIsLoading(false));
  }

  return (
    <>
      {step === "email" && (
        <div className="w-full flex flex-col gap-3">
          <button
            onClick={() => setModelTab("login")}
            className="w-fit flex items-center gap-2"
          >
            <ChevronLeft className="size-4" />
            <span>Voltar</span>
          </button>
        </div>
      )}

      {step === "email" && (
        <form
          className="w-full flex flex-col gap-10"
          onSubmit={handleSubmitEmail}
        >
          <div className="w-full flex flex-col gap-2 text-center">
            <h3 className="text-xl font-bold">Esqueceu sua senha?</h3>
            <span className="text-sm">
              Digite o email cadastrado para receber um link de recuperação de
              senha.
            </span>
          </div>
          <div className="w-full flex flex-col gap-2">
            <div className="w-full relative flex items-center text-black">
              <label htmlFor="email" className="absolute left-2 z-10">
                <Mail className="size-4" />
              </label>
              <input
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full bg-white rounded flex items-center gap-3 border-none outline-none px-8 py-2 text-sm"
                id="email"
                type="email"
                placeholder="Email"
                required
              />
            </div>
            {errors.form && (
              <span className="text-red-500 text-sm">{errors.form}</span>
            )}
          </div>

          <div className="relative w-full">
            {isLoading && <Loading />}

            <button
              type="submit"
              className="w-full bg-primary p-2 rounded text-white text-center"
              disabled={isLoading}
            >
              Enviar código de recuperação
            </button>
          </div>
        </form>
      )}
      {step === "code" && (
        <form
          className="w-full flex flex-col gap-10"
          onSubmit={handleSubmitCode}
        >
          <div className="w-full flex flex-col gap-2 text-center">
            <h3 className="text-xl font-bold">
              Digite o código de recuperação
            </h3>
            <span className="text-sm">
              Digite o código de 6 dígitos enviado para o seu Whatsapp
              cadastrado.
            </span>
          </div>
          <div className="w-full flex flex-col gap-2">
            <div className="w-full flex justify-center gap-2">
              {otpValues.map((value, index) => (
                <input
                  key={index}
                  ref={(el) => (otpRefs.current[index] = el)}
                  type="text"
                  inputMode="numeric"
                  maxLength={1}
                  value={value}
                  onChange={(e) => handleOtpChange(index, e.target.value)}
                  onKeyDown={(e) => handleOtpKeyDown(index, e)}
                  onPaste={handleOtpPaste}
                  className="w-12 h-12 text-center text-xl font-bold bg-white text-black rounded border-2 border-gray-300 outline-none focus:border-primary transition-colors"
                  autoComplete="off"
                />
              ))}
            </div>
            {errors.form && (
              <span className="text-red-500 text-sm text-center">
                {errors.form}
              </span>
            )}
            {successMessage && (
              <span className="text-green-500 text-sm text-center">
                {successMessage}
              </span>
            )}
          </div>

          <div className="relative w-full">
            {isLoading && <Loading />}

            <button
              type="submit"
              className="w-full bg-primary p-2 rounded text-white text-center"
              disabled={isLoading}
            >
              Validar código
            </button>
          </div>

          <div className="relative w-full">
            {isResending && <Loading />}

            <button
              type="button"
              onClick={handleResendCode}
              className="w-full bg-neutral text-primary text-center p-2 rounded hover:underline disabled:opacity-50 disabled:cursor-not-allowed"
              disabled={resendCountdown > 0 || isResending}
            >
              {resendCountdown > 0
                ? `Aguarde ${resendCountdown}s para reenviar`
                : "Enviar novamente o código de recuperação"}
            </button>
          </div>
        </form>
      )}

      {step === "new-password" && (
        <form
          className="w-full flex flex-col gap-10"
          onSubmit={handleSubmitNewPassword}
        >
          <div className="w-full flex flex-col gap-2 text-center">
            <h3 className="text-xl font-bold">Crie uma nova senha</h3>
            <span className="text-sm">
              Digite uma nova senha para sua conta.
            </span>
          </div>
          <div className="w-full flex flex-col gap-2">
            <div className="flex flex-col gap-2">
              <label className="text-sm" htmlFor="password">
                Senha
              </label>
              <InputPassword ref={passwordRef} />
            </div>

            <div className="flex flex-col gap-2">
              <label className="text-sm" htmlFor="password-confirm">
                Confirmar senha
              </label>
              <InputPassword ref={passwordConfirmRef} />
            </div>

            {errors.form && (
              <span className="text-red-500 text-sm">{errors.form}</span>
            )}
          </div>

          <div className="relative w-full">
            {isLoading && <Loading />}

            <button
              type="submit"
              className="w-full bg-primary p-2 rounded text-white text-center"
              disabled={isLoading}
            >
              Alterar senha
            </button>
          </div>
        </form>
      )}
    </>
  );
};

export default ForgetPassword;
