import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent,
} from '@dnd-kit/core'
import {
  SortableContext,
  verticalListSortingStrategy
} from '@dnd-kit/sortable'
import { IndexedContainer } from './hooks/get-indexes'

export default function SortableListGroup({
  children,
  item,
  update
}: {
  children: React.ReactNode,
  item: IndexedContainer,
  update: (groupId: number, oldId: number | string, newId: number | string, oldType: "item" | "script", newType: "item" | "script") => void
}) {
  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 5
      }
    })
  )

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event

    if (active.id !== over?.id && over && item.groupId !== undefined) {
      const activeItem = item.items.find(i => active.id == `${i.id}-${i.itemType}`)
      const overItem = item.items.find(i => over.id == `${i.id}-${i.itemType}`)

      if (activeItem?.id && overItem?.id) {
        update(item.groupId, activeItem.id, overItem.id, activeItem.itemType, overItem.itemType)
      }
    }
  }

  const items = item.items.map(i => `${i.id}-${i.itemType}`).filter(i => i !== undefined)

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCenter}
      onDragEnd={handleDragEnd}
    >
      <SortableContext
        items={items}
        strategy={verticalListSortingStrategy}
      >
        {children}
      </SortableContext>
    </DndContext>
  )
}