import { createContext, useEffect, useState } from "react";
import {
  Group,
  Item,
  ItemType,
  Schedule,
  Script,
  Shoot,
  ShotTriggers,
  Step,
  Trigger,
} from "../../models/db";

export type LoginTab =
  | "login"
  | "plans"
  | "saver"
  | "saver_video"
  | "maturador_video"
  | "maturador"
  | "business"
  | "plans_video"
  | "indicate"
  | "free-trial"
  | "forget-password";

export type Label = {
  id: string;
  color: string;
  colorIndex: string;
  hexColor: string;
  name: string;
  count: number;
};

type DataMap = {
  group?: Group;
  item?: Item;
  script?: Script;
  step?: Step;
  shoot?: Shoot;
  schedule?: Schedule;
  label?: Label;
  trigger?: Trigger;
  shotTrigger?: ShotTriggers;
};

export type MenuTabType =
  | "main"
  | "settings"
  | "account"
  | "step"
  | "addStep"
  | "removeStep"
  | "wait"
  | "label"
  | "trigger"
  | "webhook"
  | "export"
  | "schedule_list"
  | "schedule"
  | "shoot"
  | "shoot_list"
  | "shooting"
  | "saver"
  | "maturador"
  | "shot-triggers"
  | "shot-triggers-list"
  | ItemType;

export type TabShootingType = "shooting" | "shooted" | "no-shoot" | "schedule";

type MenuContextType = {
  show: boolean;
  setShow: (show: boolean) => void;
  tab: MenuTabType;
  setTab: (tab: MenuTabType) => void;
  activeItem: DataMap | undefined;
  setActiveItem: (item: DataMap | undefined) => void;
  showCheckout: boolean;
  setShowCheckout: (showCheckout: boolean) => void;
  modelTab: LoginTab;
  setModelTab: (tab: LoginTab) => void;
  tabShooting: TabShootingType;
  setTabShooting: (tab: TabShootingType) => void;
  confirmModal: boolean;
  setConfirmModal: (confirmModal: boolean) => void;
  showConfirmModal: (
    onConfirm: () => void,
    title?: string,
    description?: string,
  ) => void;
  confirmAction: (() => void) | null;
  confirmTitle: string | null;
  confirmDescription: string | null;
  closeConfirmModal: () => void;
  runningScriptId: number | null;
  activeChatId: string | null;
  manualScriptsByChat: Record<
    string,
    { scriptId?: number | null; startedAt?: number | null }
  >;
};

export const HeaderContext = createContext({} as MenuContextType);

export function HeaderProvider({ children }: { children: React.ReactNode }) {
  const [show, setShow] = useState(false);
  const [tab, setTab] = useState<MenuTabType>("main");
  const [activeItem, setActiveItem] = useState<DataMap | undefined>();
  const [showCheckout, setShowCheckout] = useState(false);
  const [modelTab, setModelTab] = useState<LoginTab>("login");
  const [tabShooting, setTabShooting] = useState<TabShootingType>("shooting");
  const [confirmModal, setConfirmModal] = useState(false);
  const [confirmAction, setConfirmAction] = useState<(() => void) | null>(null);
  const [confirmTitle, setConfirmTitle] = useState<string | null>(null);
  const [confirmDescription, setConfirmDescription] = useState<string | null>(
    null,
  );
  const [runningScriptId, setRunningScriptId] = useState<number | null>(null);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [manualScriptsByChat, setManualScriptsByChat] = useState<
    Record<string, { scriptId?: number | null; startedAt?: number | null }>
  >({});

  useEffect(() => {
    const handleScriptExecutionState = (e: Event) => {
      const { scriptId, status } = (
        e as CustomEvent<{ scriptId: number; status: "start" | "stop" }>
      ).detail;

      setRunningScriptId((current) => {
        if (status === "start") {
          return scriptId;
        }
        if (status === "stop" && current === scriptId) {
          return null;
        }
        return current;
      });
    };

    window.addEventListener("scriptExecutionState", handleScriptExecutionState);
    return () => {
      window.removeEventListener(
        "scriptExecutionState",
        handleScriptExecutionState,
      );
    };
  }, []);

  useEffect(() => {
    const handleManualScriptState = (e: Event) => {
      const { scripts } = (
        e as CustomEvent<{
          scripts?: Array<{
            chatId: string;
            scriptId?: number | null;
            startedAt?: number | null;
          }>;
        }>
      ).detail;

      if (!scripts) {
        setManualScriptsByChat({});
        return;
      }

      const mapped: Record<
        string,
        { scriptId?: number | null; startedAt?: number | null }
      > = {};

      scripts.forEach(({ chatId, scriptId, startedAt }) => {
        if (!chatId) return;
        mapped[chatId] = { scriptId, startedAt };
      });

      setManualScriptsByChat(mapped);
    };

    window.addEventListener(
      "manualScriptStateChanged",
      handleManualScriptState,
    );
    window.dispatchEvent(new Event("requestManualScriptState"));

    return () => {
      window.removeEventListener(
        "manualScriptStateChanged",
        handleManualScriptState,
      );
    };
  }, []);

  useEffect(() => {
    const handleActiveChatContext = (e: Event) => {
      const { chatId } = (e as CustomEvent<{ chatId?: string | null }>).detail;
      setActiveChatId(chatId ?? null);
    };

    window.addEventListener(
      "activeChatContextChanged",
      handleActiveChatContext,
    );
    window.dispatchEvent(new Event("requestActiveChatContext"));

    return () => {
      window.removeEventListener(
        "activeChatContextChanged",
        handleActiveChatContext,
      );
    };
  }, []);

  useEffect(() => {
    const resetActiveItem = () => setActiveItem(undefined);

    if (activeItem) {
      const {
        item,
        group,
        step,
        label,
        trigger,
        schedule,
        shoot,
        script,
        shotTrigger,
      } = activeItem;

      if (
        (item && tab !== (item.type || item.itemType)) ||
        (script && tab !== "script") ||
        (group && tab !== "group") ||
        (step && tab !== "step") ||
        (label && tab !== "label") ||
        (trigger && tab !== "trigger") ||
        (schedule && tab !== "schedule") ||
        (shoot && tab !== "shoot" && tab !== "shooting") ||
        (shotTrigger && tab !== "shot-triggers")
      ) {
        resetActiveItem();
      }
    }
  }, [activeItem, tab]);

  useEffect(() => {
    const element = document.querySelector("#app");

    const mainElement = document.querySelector(
      ".x78zum5.xdt5ytf.x5yr21d", //"#app > div > .x78zum5.xdt5ytf.x5yr21d > .x78zum5.xdt5ytf.x5yr21d"
    ) as HTMLElement | null;

    if (show) {
      element?.classList.add("ext-active");

      if (mainElement) {
        mainElement.style.setProperty(
          "width",
          "calc(100% - 384px)",
          "important",
        );
      }
    } else {
      element?.classList.remove("ext-active");

      if (mainElement) {
        mainElement.style.removeProperty("width");
        mainElement.style.removeProperty("important");
        mainElement.style.removeProperty("width");
        mainElement.style.removeProperty("important");
      }
    }
  }, [show]);

  // useEffect(() => {
  //   if (session?.logged) {
  //     sendMessage("session", session);
  //   }
  // }, [session]);

  function showConfirmModal(
    onConfirm: () => void,
    title?: string,
    description?: string,
  ) {
    setConfirmAction(() => onConfirm);
    setConfirmTitle(title || null);
    setConfirmDescription(description || null);
    setConfirmModal(true);
  }

  function closeConfirmModal() {
    setConfirmModal(false);
    setConfirmAction(null);
    setConfirmTitle(null);
    setConfirmDescription(null);
  }

  return (
    <HeaderContext.Provider
      value={{
        show,
        setShow,
        tab,
        setTab,
        activeItem,
        setActiveItem,
        showCheckout,
        setShowCheckout,
        modelTab,
        setModelTab,
        tabShooting,
        setTabShooting,
        confirmModal,
        setConfirmModal,
        showConfirmModal,
        confirmAction,
        confirmTitle,
        confirmDescription,
        closeConfirmModal,
        runningScriptId,
        activeChatId,
        manualScriptsByChat,
      }}
    >
      {children}
    </HeaderContext.Provider>
  );
}
