import { forwardRef, useEffect, useState } from "react"
import { useLiveQuery } from "dexie-react-hooks"
import { ChevronDown } from "lucide-react"
import db from "../../models/db"

type Props = {
  defaultId?: number,
  type?: "item" | "script"
}

const SelectGroup = forwardRef<HTMLSelectElement, Props>(({ defaultId, type = "item" }, ref) => {
  const [itemId, setItemId] = useState<string>("")
  const groups = useLiveQuery(() => db.groups.toArray(), [], [])

  useEffect(() => {
    if (groups && defaultId) {
      const group = groups.find(i => i.items?.find(x => x.id == defaultId && x.type == type))
      if (group) {
        setItemId(String(group.id))
      }
    }
  }, [groups, defaultId])

  function handleChange(e: React.ChangeEvent<HTMLSelectElement>) {
    setItemId(e.target.value)
  }

  return (
    <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
      <label htmlFor="group">Selecionar uma pasta</label>
      <div className="relative">
        <select
          ref={ref}
          className="rounded p-2 bg-secondary"
          name="group"
          id="group"
          value={itemId}
          onChange={handleChange}
        >
          <option value="">Selecione a pasta...</option>
          {groups?.map((group) => (
            <option key={group.id} value={group.id}>{group.title}</option>
          ))}
        </select>
        <label htmlFor="group" className="absolute top-0 right-3 h-full flex items-center">
          <ChevronDown className="size-4 text-gray-400" />
        </label>
      </div>
    </div>
  )
})

SelectGroup.displayName = "SelectGroup"

export { SelectGroup }