import { ChevronDown, Folder } from "lucide-react";
import { useState } from "react";
import { twMerge } from "tailwind-merge";
import useAutoScroll from "./hooks/auto-scroll";
import { IndexedContainer } from "./hooks/get-indexes";

export default function ScriptContainer({
  children,
  item,
}: {
  children?: React.ReactNode;
  item: IndexedContainer;
}) {
  const [show, setShow] = useState(false);
  const { scrollRef, handleMouseEnter, handleMouseLeave } = useAutoScroll();

  return (
    <div
      style={{ backgroundColor: item.color || "#2e2e2e" }}
      className={twMerge(
        "w-full flex flex-col gap-5 rounded px-5 py-3 duration-300",
        !show && "hover:opacity-75"
      )}
    >
      <button
        onClick={() => setShow(!show)}
        className="w-full flex items-center justify-between text-white"
      >
        <div className="flex gap-3">
          <Folder className="w-4" />
          <span
            ref={scrollRef}
            onMouseEnter={handleMouseEnter}
            onMouseLeave={handleMouseLeave}
            title={item.title}
            className="text-sm"
          >
            {item.title}
          </span>
        </div>
        <ChevronDown
          className={twMerge(
            "w-5 duration-300 ease-in-out",
            show ? "rotate-180" : "rotate-0"
          )}
        />
      </button>

      {show && <div className="flex w-full flex-col gap-2">{children}</div>}
    </div>
  );
}
