import { useLiveQuery } from "dexie-react-hooks";
import db, { Script } from "../../models/db";
import { useContext, useEffect, useState } from "react";
import { HeaderContext } from "../providers/header-context";

type Validate = {
  [key: string]: string | undefined;
};

type ItemSet = {
  item?: Script;
  validateErrors: Validate;
};

type Set = {
  newItem: Partial<Script>;
  groupId?: number;
};

export function useScriptSet({ item, validateErrors }: ItemSet) {
  const [errors, setErrors] = useState<Validate>({});
  const groups = useLiveQuery(() => db.groups.toArray(), [], []);
  const { setTab } = useContext(HeaderContext);

  useEffect(() => {
    if (item) {
      setErrors({});
    }
  }, [item]);

  function validateForm(newItem: Partial<Script>): boolean {
    const newErrors: { [key: string]: string | undefined } = {};

    for (const [key, value] of Object.entries(newItem)) {
      if (key in validateErrors && !value) {
        newErrors[key] = validateErrors[key];
      }
    }

    setErrors(newErrors);

    return Object.keys(newErrors).length === 0;
  }

  async function saveItem({ newItem, groupId }: Set) {
    if (!validateForm(newItem)) return;

    let newItemID;

    if (item?.id) {
      newItemID = await db.scripts.put({
        ...(newItem as Script),
        id: item.id,
      });
    } else {
      newItemID = await db.scripts.add(newItem as Script);
    }

    if (newItemID !== undefined) {
      await handleGroupAssociation(newItemID, groupId);
      setTab("main");
    }
  }

  async function handleGroupAssociation(newItemID: number, groupId?: number) {
    const inGroup = checkGroupAssociation(item?.id);

    if (groupId) {
      const group = groups.find((i) => i.id == Number(groupId));

      if (group?.id) {
        if (inGroup?.id) {
          await db.removeGroupItem(inGroup.id, newItemID, "script");
        }
        await db.addGroupItem(group.id, { id: newItemID, type: "script" });
      }
    } else {
      if (inGroup?.id) {
        await db.removeGroupItem(inGroup.id, newItemID, "script");
      }
    }
  }

  async function removeItem() {
    if (!item) return;

    if (item.type === "item-error")
      if (window.confirm("Deseja realmente excluir este item?")) {
        if (item.id) {
          await db.items.delete(item.id);

          setTab("main");
        }

        return;
      }

    if (window.confirm("Deseja realmente excluir este item?")) {
      if (item.id) {
        await db.scripts.delete(item.id);

        setTab("main");
      }
    }
  }

  function checkGroupAssociation(itemId?: number) {
    return groups.find((i) =>
      i.items?.find((i) => i.id == itemId && i.type == "script")
    );
  }

  return { saveItem, removeItem, errors };
}
