import { useContext, useEffect, useRef } from "react";
import LoginModelBusiness from "./login-models/business";
import ForgetPassword from "./login-models/forget-password";
import { FreeTierModel } from "./login-models/free-tier";
import LoginModelIndicate from "./login-models/indicate";
import LoginModelMain from "./login-models/main";
import { LoginModelPlans, LoginModelPlansVideo } from "./login-models/plans";
import LoginModelMaturador from "./login-models/maturador";
import LoginModelSaver from "./login-models/saver";
import LoginModelSaverVideo from "./login-models/saver-video";
import LoginModelMaturadorVideo from "./login-models/maturador-video";
import { HeaderContext } from "./providers/header-context";

export default function LoginModal() {
  const { showCheckout, setShowCheckout, modelTab, setModelTab } =
    useContext(HeaderContext);
  const modalRef = useRef<HTMLDivElement>(null);

  const handleClickOutside = (event: MouseEvent) => {
    if (modalRef.current && !modalRef.current.contains(event.target as Node)) {
      setShowCheckout(false);
    }
  };

  useEffect(() => {
    if (showCheckout) {
      document.addEventListener("mousedown", handleClickOutside);
    } else {
      document.removeEventListener("mousedown", handleClickOutside);
    }
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [showCheckout]);

  return (
    <>
      {showCheckout && (
        <div className="z-[999] fixed inset-0 flex items-center bg-black/20 backdrop-blur-xs shadow-lg">
          <div
            ref={modalRef}
            className="min-w-96 mx-auto max-w-3xl py-3 px-5 rounded bg-neutral shadow-lg"
          >
            {modelTab === "login" ? (
              <LoginModelMain setModelTab={setModelTab} />
            ) : modelTab === "plans" ? (
              <LoginModelPlans setModelTab={setModelTab} />
            ) : modelTab === "plans_video" ? (
              <LoginModelPlansVideo setModelTab={setModelTab} />
            ) : modelTab === "saver" ? (
              <LoginModelSaver setModelTab={setModelTab} />
            ) : modelTab === "saver_video" ? (
              <LoginModelSaverVideo setModelTab={setModelTab} />
            ) : modelTab === "maturador_video" ? (
              <LoginModelMaturadorVideo setModelTab={setModelTab} />
            ) : modelTab === "maturador" ? (
              <LoginModelMaturador setModelTab={setModelTab} />
            ) : modelTab === "business" ? (
              <LoginModelBusiness />
            ) : modelTab === "indicate" ? (
              <LoginModelIndicate />
            ) : modelTab === "free-trial" ? (
              <FreeTierModel />
            ) : modelTab === "forget-password" ? (
              <ForgetPassword setModelTab={setModelTab} />
            ) : null}
          </div>
        </div>
      )}
    </>
  );
}
