import { useContext, useEffect, useRef, useState } from "react";
import { ScriptItemsContext, ScriptItemType } from "./tabs/script";
import db, { Item, Step } from "../models/db";
import { useLiveQuery } from "dexie-react-hooks";
import { Clock4, Search, Trash2 } from "lucide-react";
import RandomizerCard from "./randomizer-card";

export default function CardByType({ item }: { item: ScriptItemType }) {
  const [searchTerm, setSearchTerm] = useState("");
  const [delayUnit, setDelayUnit] = useState<"segundos" | "minutos" | "horas">(
    item.delayUnit || "segundos"
  );
  const [delayInputValue, setDelayInputValue] = useState<string>(
    (item.delay ?? 1).toString()
  );
  const { setItem, removeItem } = useContext(ScriptItemsContext);
  const delayInputRef = useRef<HTMLInputElement>(null);

  // Sincronizar delayUnit e delay quando o item mudar
  useEffect(() => {
    if (item.delayUnit) {
      setDelayUnit(item.delayUnit);
    }
    // Atualizar o valor do input quando o item mudar
    if (item.delay !== undefined) {
      setDelayInputValue(item.delay.toString());
    }
  }, [item.delayUnit, item.delay]);

  const items = useLiveQuery(
    async () => {
      let result;
      if (searchTerm) {
        result = await db.items
          .where("title")
          .startsWithIgnoreCase(searchTerm)
          .filter((i) => i.type === item.type && !i.hidden)
          .toArray();
      } else {
        result = await db.items
          .filter((i) => i.type === item.type && !i.hidden)
          .toArray();
      }

      // Oculta items com "Maturador" no título (mesma lógica do main.tsx)
      return result.filter(
        (i) => !i.title?.toLowerCase().includes("maturador")
      );
    },
    [searchTerm, item.type],
    []
  );

  const steps = useLiveQuery(
    async () => {
      if (searchTerm) {
        return await db.steps
          .where("title")
          .startsWithIgnoreCase(searchTerm)
          .toArray();
      } else {
        return await db.steps.toArray();
      }
    },
    [searchTerm],
    []
  );

  function handleSelectClick(i: Item) {
    setItem({ ...item, item: i });
  }

  function handleStepSelect(step: Step) {
    const stepItem = {
      ...step,
      type: "step" as const,
      itemType: "step",
    };
    setItem({ ...item, item: stepItem });
  }

  function saveDelay(inputValue?: string) {
    const valueToProcess = inputValue ?? delayInputValue;
    // Se estiver vazio, usa 1 como padrão
    const value =
      valueToProcess === "" || valueToProcess === "-"
        ? 1
        : Number(valueToProcess);

    if (!isNaN(value) && value >= 0) {
      const unitLabel =
        delayUnit === "segundos"
          ? "segundos"
          : delayUnit === "minutos"
            ? "minutos"
            : "horas";

      const updatedItem = {
        ...item,
        item: {
          title: `Aguardar ${value} ${unitLabel}...`,
          type: "delay" as const,
          itemType: "delay" as const,
        },
        delay: value,
        delayUnit,
      };

      setItem(updatedItem);
      // Atualiza o estado local com o valor validado
      setDelayInputValue(value.toString());
    } else {
      // Se o valor for inválido, restaura o valor anterior
      setDelayInputValue((item.delay ?? 1).toString());
    }
  }

  function handleDelayChange(e: React.ChangeEvent<HTMLInputElement>) {
    const newValue = e.target.value;
    // Permite valores vazios durante a digitação
    setDelayInputValue(newValue);
  }

  function handleDelayBlur() {
    // Valida apenas ao perder o foco
    saveDelay();
  }

  function handleDelayUnitChange(e: React.ChangeEvent<HTMLSelectElement>) {
    const newUnit = e.target.value as "segundos" | "minutos" | "horas";
    setDelayUnit(newUnit);
    // Salvar imediatamente quando a unidade muda
    const inputValue = delayInputValue;
    const value =
      inputValue === "" || inputValue === "-" ? 1 : Number(inputValue);
    if (!isNaN(value) && value >= 0) {
      const unitLabel =
        newUnit === "segundos"
          ? "segundos"
          : newUnit === "minutos"
            ? "minutos"
            : "horas";

      setItem({
        ...item,
        item: {
          title: `Aguardar ${value} ${unitLabel}...`,
          type: "delay" as const,
          itemType: "delay" as const,
        },
        delay: value,
        delayUnit: newUnit,
      });
    }
  }

  function handleRemove() {
    removeItem(item.id);
  }

  switch (item.type) {
    case "delay":
      return (
        <div className="w-full max-h-48 flex items-center justify-between gap-2">
          <div className="flex items-center gap-2 text-sm text-gray-400">
            <Clock4 className="size-4" />
            <div className="flex items-center gap-1 rounded px-2 py-1 bg-secondary">
              <input
                ref={delayInputRef}
                className="w-10 bg-transparent border-none focus:outline-none text-foreground [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                type="number"
                id="delay"
                value={delayInputValue}
                onChange={handleDelayChange}
                onBlur={handleDelayBlur}
                min="0"
              />
              <select
                value={delayUnit}
                onChange={handleDelayUnitChange}
                className="bg-transparent border-none focus:outline-none text-foreground text-xs"
              >
                <option value="segundos">segundos</option>
                <option value="minutos">minutos</option>
                <option value="horas">horas</option>
              </select>
            </div>
            <span>aguardando...</span>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={handleRemove}
              className="h-full flex items-center pl-1"
            >
              <Trash2 className="size-4 text-red-500" />
            </button>
          </div>
        </div>
      );

    case "addStep":
    case "removeStep":
      return (
        <div className="w-full max-h-48 flex flex-col gap-2 overflow-auto">
          <div className="flex items-center gap-3 mb-3">
            <div className="w-full flex items-center gap-2 text-gray-400 bg-neutral rounded px-5 py-1 cursor-pointer">
              <label htmlFor="search">
                <Search className="w-5" />
              </label>
              <input
                id="search"
                className="w-full text-xs bg-transparent py-1 focus:outline-none"
                type="text"
                placeholder="Pesquisar script..."
                value={searchTerm}
                onChange={(event) =>
                  setSearchTerm(event.target.value.toLowerCase())
                }
              />
            </div>

            <button
              onClick={handleRemove}
              className="h-full flex items-center pl-1"
            >
              <Trash2 className="size-4 text-red-500" />
            </button>
          </div>

          {steps?.map((step) => (
            <button
              onClick={() => handleStepSelect(step)}
              key={step.id}
              className="w-full p-2 rounded bg-neutral"
            >
              <span className="text-center">{step.title}</span>
            </button>
          ))}
        </div>
      );

    case "react":
      return "selecionar reação...";
    case "randomizer":
      return <RandomizerCard item={item} />;
    default:
      return (
        <div className="w-full max-h-48 flex flex-col gap-2 overflow-auto">
          <div className="flex items-center gap-3 mb-3">
            <div className="w-full flex items-center gap-2 text-gray-400 bg-neutral rounded px-5 py-1 cursor-pointer">
              <label htmlFor="search">
                <Search className="w-5" />
              </label>
              <input
                id="search"
                className="w-full text-xs bg-transparent py-1 focus:outline-none"
                type="text"
                placeholder="Pesquisar..."
                value={searchTerm}
                onChange={(event) =>
                  setSearchTerm(event.target.value.toLowerCase())
                }
              />
            </div>

            <button
              onClick={handleRemove}
              className="h-full flex items-center pl-1"
            >
              <Trash2 className="size-4 text-red-500" />
            </button>
          </div>

          {items?.map((i) => (
            <button
              onClick={() => handleSelectClick(i)}
              key={i.id}
              className="w-full p-2 rounded bg-neutral"
            >
              <span className="text-center">{i.title}</span>
            </button>
          ))}
        </div>
      );
  }
}
