import { HeaderContext } from "../providers/header-context";
import { getIconByType } from "../header";
import {
  ChevronDown,
  ChevronRight,
  CreditCard,
  KeyRound,
  Settings,
} from "lucide-react";
import { useContext, useRef, useState } from "react";
import Loading from "../loading";
import { SessionContext } from "../providers/session-context";
import { urls } from "../utils/checkout";

export default function MenuAccountTab() {
  const [changePassword, setChangePassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [showTools, setShowTools] = useState(false);
  const [errors, setErrors] = useState<{
    password?: string;
    form?: string;
  }>({});
  const passwordRef = useRef<HTMLInputElement>(null);
  const passwordConfirmRef = useRef<HTMLInputElement>(null);
  const Icon = getIconByType("account");
  const { setTab, showConfirmModal } = useContext(HeaderContext);
  const { session, signOut } = useContext(SessionContext);

  function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();

    const password = passwordRef.current?.value;
    const passwordConfirm = passwordConfirmRef.current?.value;

    setErrors({});

    if (changePassword) {
      if (passwordConfirm && passwordConfirm.length < 8) {
        setErrors((prev) => {
          const newErrors = { ...prev };
          newErrors.password = "A senha precisa ter no mínimo 8 caracteres!";
          return newErrors;
        });
        return;
      }

      if (password !== passwordConfirm) {
        setErrors((prev) => {
          const newErrors = { ...prev };
          newErrors.password = "As senhas precisam ser iguais!";
          return newErrors;
        });
        return;
      }

      setIsLoading(true);

      chrome.runtime
        .sendMessage({ action: "user.edit", data: { password } })
        .then((response) => {
          if (response?.ok) {
            setChangePassword(false);
          }
        })
        .finally(() => setIsLoading(false));
    } else {
      setChangePassword(true);
    }
  }

  function logout() {
    signOut().then((response) => {
      if (response) {
        setTab("main");
      }
    });
  }

  return (
    <div className="w-full h-full flex flex-col items-center gap-5 overflow-auto">
      <div className="w-full flex items-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
        <Icon className="size-4" />
        <span className="text-center text-sm">Minha conta</span>
      </div>

      {session && (
        <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
          <span>Meu email</span>
          <div className="w-full rounded p-2 bg-secondary">
            <span>{session.email}</span>
          </div>
          <ul className="list-none pl-2 flex flex-col gap-y-2">
            <li className="flex items-center justify-between">
              <div className="flex items-center gap-x-2">
                <div
                  className={`size-1.5 rounded-full ${
                    session.permissions?.includes("EXTENSION")
                      ? "bg-primary"
                      : "bg-red-500"
                  }`}
                  title="assinatura ativa"
                />
                <span>REVZAP</span>
              </div>
            </li>
            <li className="flex items-center justify-between">
              <div className="flex items-center gap-x-2">
                <div
                  className={`size-1.5 rounded-full ${
                    session.permissions?.includes("SAVER")
                      ? "bg-primary"
                      : "bg-red-500"
                  }`}
                />
                <span>REVSAVER</span>
              </div>
            </li>
            <li className="flex items-center justify-between">
              <div className="flex items-center gap-x-2">
                <div
                  className={`size-1.5 rounded-full ${
                    session.permissions?.includes("MATURADOR")
                      ? "bg-primary"
                      : "bg-red-500"
                  }`}
                />
                <span>REVPROTECT</span>
              </div>
            </li>
          </ul>
        </div>
      )}

      <div className="w-full flex flex-col flex-1 gap-5">
        <div className="w-full flex flex-col gap-2">
          <button
            type="button"
            onClick={() => setShowTools((v) => !v)}
            aria-expanded={showTools}
            className="w-full flex items-center gap-2 p-3 rounded bg-neutral whitespace-nowrap duration-300 hover:bg-primary/50"
          >
            <Settings className="size-4 min-w-4 min-h-4" />
            <span className="text-sm capitalize flex-1 text-left">
              Configurações da conta
            </span>
            {showTools ? (
              <ChevronDown className="size-4 min-w-4 min-h-4 opacity-80" />
            ) : (
              <ChevronRight className="size-4 min-w-4 min-h-4 opacity-80" />
            )}
          </button>

          {showTools && (
            <div className="pl-4 flex flex-col gap-2">
              <a
                href={urls.billing}
                rel="noopener noreferrer"
                target="_blank"
                className="w-full flex items-center justify-between gap-2 p-3 rounded bg-neutral whitespace-nowrap"
              >
                <span className="w-full text-sm flex items-center gap-2">
                  <CreditCard className="size-4 min-w-4 min-h-4 opacity-80" />
                  <span>Gerenciar assinatura</span>
                </span>
                <ChevronRight className="size-4 min-w-4 min-h-4 opacity-80" />
              </a>

              <button
                type="button"
                onClick={() => setChangePassword((prev) => !prev)}
                className="w-full flex items-center justify-between gap-2 p-3 rounded bg-neutral whitespace-nowrap"
              >
                <span className="w-full text-sm flex items-center gap-2">
                  <KeyRound className="size-4 min-w-4 min-h-4 opacity-80" />
                  <span>Alterar senha</span>
                </span>
                {changePassword ? (
                  <ChevronDown className="size-4 min-w-4 min-h-4 opacity-80" />
                ) : (
                  <ChevronRight className="size-4 min-w-4 min-h-4 opacity-80" />
                )}
              </button>

              {changePassword && (
                <form
                  action=""
                  onSubmit={handleSubmit}
                  className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm"
                >
                  <span>Trocar senha</span>
                  <input
                    ref={passwordRef}
                    type="password"
                    id="password"
                    className="w-full rounded p-2 bg-secondary focus:outline-none"
                    placeholder="Digite a nova senha..."
                    required
                  />
                  <input
                    ref={passwordConfirmRef}
                    type="password"
                    id="password-confirm"
                    className="w-full rounded p-2 bg-secondary focus:outline-none"
                    placeholder="Confirme a nova senha..."
                    required
                  />
                  {errors.password && (
                    <p className="text-red-500">{errors.password}</p>
                  )}

                  <div className="relative">
                    {isLoading && <Loading />}
                    <button
                      type="submit"
                      disabled={isLoading}
                      className="w-full bg-secondary text-center p-2 rounded"
                    >
                      Alterar senha
                    </button>
                  </div>
                </form>
              )}
            </div>
          )}
        </div>
      </div>

      <button
        onClick={logout}
        className="w-full bg-neutral text-red-500 text-center p-2 rounded"
      >
        Desconectar
      </button>
    </div>
  );
}
