import { useEffect, useState, useRef, useCallback } from "react";
import { X, Trash2 } from "lucide-react";

interface DebugLog {
  id: string;
  timestamp: Date;
  type: "info" | "success" | "error" | "warning";
  message: string;
  data?: any;
}

export function MaturadorDebug() {
  const [logs, setLogs] = useState<DebugLog[]>([]);
  const [isMinimized, setIsMinimized] = useState(false);
  const logsEndRef = useRef<HTMLDivElement>(null);

  const addLog = useCallback(
    (type: DebugLog["type"], message: string, data?: any) => {
      setLogs((prev) => {
        const newLog: DebugLog = {
          id: Date.now().toString() + Math.random().toString(36).substr(2, 9),
          timestamp: new Date(),
          type,
          message,
          data,
        };
        return [...prev, newLog].slice(-100);
      });
    },
    []
  );

  useEffect(() => {
    // Intercepta console.log relacionado ao maturador
    const originalConsoleLog = console.log;
    const originalConsoleError = console.error;
    const originalConsoleWarn = console.warn;

    console.log = (...args: any[]) => {
      originalConsoleLog.apply(console, args);
      const message = args.join(" ");
      if (message.includes("[Maturador]") || message.includes("MATURADOR")) {
        if (message.includes("ERRO") || message.includes("ERROR")) {
          addLog("error", message, args);
        } else if (message.includes("SUCESSO") || message.includes("SUCCESS")) {
          addLog("success", message, args);
        } else {
          addLog("info", message, args);
        }
      }
    };

    console.error = (...args: any[]) => {
      originalConsoleError.apply(console, args);
      const message = args.join(" ");
      if (message.includes("[Maturador]") || message.includes("MATURADOR")) {
        addLog("error", message, args);
      }
    };

    console.warn = (...args: any[]) => {
      originalConsoleWarn.apply(console, args);
      const message = args.join(" ");
      if (message.includes("[Maturador]") || message.includes("MATURADOR")) {
        addLog("warning", message, args);
      }
    };

    // Escuta eventos do maturador
    const handleMaturadorSendMessage = (e: Event) => {
      const event = e as CustomEvent<{
        to: string;
        message: string;
        server: string;
      }>;
      addLog("info", `Evento maturadorSendMessage recebido`, {
        to: event.detail?.to,
        message: event.detail?.message?.substring(0, 50) + "...",
        server: event.detail?.server,
      });
    };

    const handleSendMessage = (e: Event) => {
      const event = e as CustomEvent<{
        to: string;
        message: string;
        mentionAll: boolean;
      }>;
      addLog("info", `Evento sendMessage disparado`, {
        to: event.detail?.to,
        message: event.detail?.message?.substring(0, 50) + "...",
      });
    };

    const handleSendMessageComplete = (e: Event) => {
      const event = e as CustomEvent<{
        chatId: string;
        status: string;
      }>;
      addLog(
        event.detail?.status === "sent" ? "success" : "warning",
        `Mensagem ${event.detail?.status === "sent" ? "enviada" : "cancelada"}`,
        {
          chatId: event.detail?.chatId,
          status: event.detail?.status,
        }
      );
    };

    window.addEventListener("maturadorSendMessage", handleMaturadorSendMessage);
    window.addEventListener("sendMessage", handleSendMessage);
    window.addEventListener("sendMessageComplete", handleSendMessageComplete);

    // Log inicial
    setTimeout(() => {
      addLog("info", "Debug do Maturador ativado");
      addLog("info", "Aguardando eventos do maturador...");
    }, 100);

    return () => {
      console.log = originalConsoleLog;
      console.error = originalConsoleError;
      console.warn = originalConsoleWarn;
      window.removeEventListener(
        "maturadorSendMessage",
        handleMaturadorSendMessage
      );
      window.removeEventListener("sendMessage", handleSendMessage);
      window.removeEventListener(
        "sendMessageComplete",
        handleSendMessageComplete
      );
    };
  }, [addLog]);

  useEffect(() => {
    const handleBackgroundLog = (event: Event) => {
      const detail = (
        event as CustomEvent<{
          message?: string;
          payload?: Record<string, unknown>;
          timestamp?: string;
        }>
      ).detail;
      const payload = detail?.payload;
      const message = detail?.message || "Evento do maturador.";
      addLog("info", message, {
        ...payload,
        timestamp: detail?.timestamp,
        source: "background",
      });
    };

    window.addEventListener("maturadorDebugLog", handleBackgroundLog);

    return () => {
      window.removeEventListener("maturadorDebugLog", handleBackgroundLog);
    };
  }, [addLog]);

  // Auto-scroll para o último log
  useEffect(() => {
    if (!isMinimized) {
      logsEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }
  }, [logs, isMinimized]);

  const getLogColor = (type: DebugLog["type"]) => {
    switch (type) {
      case "success":
        return "text-green-400";
      case "error":
        return "text-red-400";
      case "warning":
        return "text-yellow-400";
      default:
        return "text-blue-400";
    }
  };

  const getLogBgColor = (type: DebugLog["type"]) => {
    switch (type) {
      case "success":
        return "bg-green-400/10 border-green-400/20";
      case "error":
        return "bg-red-400/10 border-red-400/20";
      case "warning":
        return "bg-yellow-400/10 border-yellow-400/20";
      default:
        return "bg-blue-400/10 border-blue-400/20";
    }
  };

  const clearLogs = () => {
    setLogs([]);
  };

  return (
    <div className="w-full mt-5" style={{ zIndex: 10 }}>
      <div className="bg-[var(--background-default)] border-2 border-blue-500 rounded-lg shadow-lg overflow-hidden">
        {/* Header */}
        <div className="bg-neutral px-4 py-3 flex items-center justify-between border-b border-[var(--border-list)]">
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 bg-green-400 rounded-full animate-pulse"></div>
            <h3 className="text-sm font-bold text-foreground">
              Debug do Maturador
            </h3>
            <span className="text-xs text-foreground/60">
              ({logs.length} logs)
            </span>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={clearLogs}
              className="p-1.5 rounded hover:bg-primary/50 transition-colors"
              title="Limpar logs"
            >
              <Trash2 className="size-4 text-foreground" />
            </button>
            <button
              onClick={() => setIsMinimized(!isMinimized)}
              className="p-1.5 rounded hover:bg-primary/50 transition-colors"
              title={isMinimized ? "Expandir" : "Minimizar"}
            >
              <X className="size-4 text-foreground" />
            </button>
          </div>
        </div>

        {/* Logs Container */}
        {!isMinimized && (
          <div className="max-h-64 overflow-y-auto p-4 space-y-2 bg-[var(--background-default)] min-h-[150px]">
            {logs.length === 0 ? (
              <div className="text-center text-sm text-foreground/60 py-8">
                <div className="animate-pulse">
                  Aguardando eventos do maturador...
                </div>
              </div>
            ) : (
              logs.map((log) => (
                <div
                  key={log.id}
                  className={`p-3 rounded border ${getLogBgColor(log.type)}`}
                >
                  <div className="flex items-start gap-2">
                    <span
                      className={`text-xs font-mono flex-shrink-0 ${getLogColor(log.type)}`}
                    >
                      [{log.timestamp.toLocaleTimeString()}]
                    </span>
                    <div className="flex-1 min-w-0">
                      <p
                        className={`text-xs font-mono break-words ${getLogColor(log.type)}`}
                      >
                        {log.message}
                      </p>
                      {log.data && (
                        <pre className="text-xs text-foreground/70 mt-1 overflow-x-auto bg-[var(--background-default)]/50 p-2 rounded">
                          {JSON.stringify(log.data, null, 2)}
                        </pre>
                      )}
                    </div>
                  </div>
                </div>
              ))
            )}
            <div ref={logsEndRef} />
          </div>
        )}
      </div>
    </div>
  );
}
