import { useState } from "react";
import { ArrowUpCircle, Clock, RefreshCw } from "lucide-react";
import { urls } from "./utils/checkout";

type UpdateNotifierProps = {
  currentVersion: string;
  storeVersion: string;
  onDismiss: () => void;
};

export default function UpdateNotifier({
  currentVersion,
  storeVersion,
  onDismiss,
}: UpdateNotifierProps) {
  const [visible, setVisible] = useState(true);

  if (!visible) return null;

  const handleDismiss = () => {
    setVisible(false);
    onDismiss();
  };

  return (
    <>
      {/* Backdrop */}
      <div className="fixed inset-0 z-[99998] bg-black/60 backdrop-blur-sm" />

      {/* Card centralizado */}
      <div className="fixed inset-0 z-[99999] flex items-center justify-center pointer-events-none">
        <div
          className="pointer-events-auto w-96 rounded-xl shadow-2xl p-6"
          style={{ backgroundColor: "#09090b", border: "1px solid #3f3f46" }}
        >
          {/* Header */}
          <div className="flex items-center gap-3 mb-4">
            <div
              className="flex items-center justify-center w-10 h-10 rounded-full"
              style={{ backgroundColor: "#61ce7020" }}
            >
              <RefreshCw size={20} color="#61ce70" />
            </div>
            <div>
              <p className="font-semibold text-sm" style={{ color: "#ffffff" }}>
                Atualização disponível
              </p>
              <p className="text-xs" style={{ color: "#a1a1aa" }}>
                RevZap — Chrome Web Store
              </p>
            </div>
          </div>

          {/* Descrição */}
          <p
            className="text-xs leading-relaxed mb-4"
            style={{ color: "#a1a1aa" }}
          >
            Uma nova versão do RevZap está disponível. Atualize para garantir
            melhor performance e compatibilidade com o WhatsApp Web.
          </p>

          {/* Versões */}
          <div
            className="flex items-center gap-2 text-xs rounded-lg px-3 py-2 mb-5"
            style={{ backgroundColor: "#27272a" }}
          >
            <span style={{ color: "#a1a1aa" }}>Instalada</span>
            <span
              className="font-mono font-medium"
              style={{ color: "#ffffff" }}
            >
              v{currentVersion}
            </span>
            <ArrowUpCircle
              size={14}
              color="#61ce70"
              className="mx-1 shrink-0"
            />
            <span style={{ color: "#a1a1aa" }}>Disponível</span>
            <span
              className="font-mono font-semibold"
              style={{ color: "#61ce70" }}
            >
              v{storeVersion}
            </span>
          </div>

          {/* Botões */}
          <div className="flex gap-3">
            <a
              href={urls.chromeWebStore}
              target="_blank"
              rel="noreferrer"
              style={{
                display: "flex",
                flex: 1,
                alignItems: "center",
                justifyContent: "center",
                gap: "6px",
                fontSize: "12px",
                fontWeight: 600,
                padding: "10px 16px",
                borderRadius: "8px",
                backgroundColor: "#19972a", //"#6f1ff0",
                color: "#ffffff",
                textDecoration: "none",
                border: "none",
                cursor: "pointer",
                transition: "opacity 0.2s",
              }}
              onMouseEnter={(e) => (e.currentTarget.style.opacity = "0.85")}
              onMouseLeave={(e) => (e.currentTarget.style.opacity = "1")}
            >
              <RefreshCw size={14} />
              Atualizar agora
            </a>
            <button
              onClick={handleDismiss}
              style={{
                display: "flex",
                flex: 1,
                alignItems: "center",
                justifyContent: "center",
                gap: "6px",
                fontSize: "12px",
                fontWeight: 500,
                padding: "10px 16px",
                borderRadius: "8px",
                backgroundColor: "transparent",
                color: "#ffffff",
                border: "1px solid #3f3f46",
                cursor: "pointer",
                transition: "background-color 0.2s",
              }}
              onMouseEnter={(e) =>
                (e.currentTarget.style.backgroundColor = "#27272a")
              }
              onMouseLeave={(e) =>
                (e.currentTarget.style.backgroundColor = "transparent")
              }
            >
              <Clock size={14} />
              Lembrar depois
            </button>
          </div>
        </div>
      </div>
    </>
  );
}
