import { ChevronDown } from "lucide-react";
import { useContext, useRef, useState } from "react";
import { downloadCSV } from "../../lib/download-csv";
import { downloadVCard } from "../../lib/download-vcard";
import ChatsSelect from "../chats-select";
import { getIconByType } from "../header";
import LabelsSelect from "../labels-select";
import { HeaderContext, LoginTab } from "../providers/header-context";
import { SessionContext } from "../providers/session-context";
import StepsSelect from "../steps-select";
import {
  getAllChats,
  getContactsByLabel,
  getContactsByStep,
  getParticipantsOnGroup,
} from "../utils/functions";

export default function MenuSaverTab() {
  const [steps, setSteps] = useState<number[]>([]);
  const [labels, setLabels] = useState<string[]>([]);
  const [withGroups, setWithGroups] = useState(false);
  const [chats, setChats] = useState<string[]>([]);
  const [withAdmin, setWithAdmin] = useState(false);
  const [withContactType, setWithContactType] = useState(false);
  const [withLabels, setWithLabels] = useState(false);
  const [withSteps, setWithSteps] = useState(false);
  const prefixRef = useRef<HTMLInputElement>(null);
  const contactTypeRef = useRef<HTMLSelectElement>(null);
  const { setShowCheckout, modelTab, setModelTab, showCheckout } =
    useContext(HeaderContext);
  const { session } = useContext(SessionContext);
  const Icon = getIconByType("saver");

  async function handleClick(fileType: "csv" | "vcard" = "csv") {
    if (!session?.logged) {
      const tab: LoginTab = "saver";
      let value = !showCheckout;

      if (tab) {
        if (tab !== modelTab) value = true;
        setModelTab(tab);
      }

      setShowCheckout(value);

      return;
    }

    if (
      !session?.permissions?.includes("SAVER") ||
      (session?.permissions?.includes("SAVER") &&
        session?.trialStatus === "TRIAL_EXPIRED" &&
        !session?.hasPlan)
    ) {
      console.log(
        "[saver.downloadCsv] BLOQUEIO (sem permissão ou trial expirado):",
        "\n  permissions:",
        session?.permissions,
        "\n  trialStatus:",
        session?.trialStatus,
        "\n  hasPlan:",
        session?.hasPlan,
        "\n  email:",
        session?.email,
      );
      setShowCheckout(true);
      setModelTab("saver");
      return;
    }

    const type = withContactType
      ? (contactTypeRef.current?.value as "all" | "archived" | "not-archived")
      : "all";
    const prefix = prefixRef.current?.value;

    let formatedData: string[][] = [["Telefone", "Nome"]];
    let dataRows: string[][] = [];

    const normalizeWhatsappId = (raw: string) =>
      raw.split("@")[0]?.replace(/\D+/g, "") || raw;

    if (withGroups && chats.length > 0) {
      const participants = await getParticipantsOnGroup(chats, withAdmin);
      if (participants && participants.length > 0) {
        dataRows = dataRows.concat(
          participants.map((p) => [
            normalizeWhatsappId(p.id),
            p.name.replace("@c.us", ""),
          ]),
        );
      }
    }

    if (withSteps && steps && steps.length > 0) {
      const stepData = await getContactsByStep(steps, type, true);
      if (stepData && stepData.length > 0) {
        dataRows = dataRows.concat(
          stepData.map(([id, nome]) => [normalizeWhatsappId(id), nome]),
        );
      }
    }

    if (withLabels && labels && labels.length > 0) {
      const labelData = await getContactsByLabel(labels, type, true);
      if (labelData && labelData.length > 0) {
        dataRows = dataRows.concat(
          labelData.map(([id, nome]) => [normalizeWhatsappId(id), nome]),
        );
      }
    }

    if (!withGroups && !withSteps && !withLabels) {
      const allChats = await getAllChats(type, false, true);
      if (allChats && allChats.length > 0) {
        dataRows = dataRows.concat(
          allChats.map((chat) => [normalizeWhatsappId(chat.id), chat.name]),
        );
      }
    }

    const uniqueRowsMap = new Map<string, string>();
    dataRows.forEach(([telefone, nome]) => {
      if (telefone && !uniqueRowsMap.has(telefone)) {
        uniqueRowsMap.set(telefone, nome);
      }
    });

    formatedData = [
      ["Telefone", "Nome"],
      ...Array.from(uniqueRowsMap.entries()).map(([telefone, nome]) => [
        telefone,
        nome,
      ]),
    ];

    if (prefix) {
      formatedData = formatedData.map((i) => ({
        ...i,
        name: `${prefix} ${i[1]}`,
      }));
    }

    if (fileType === "vcard") {
      const data = formatedData.map((i) => ({
        fullName: i[1] || "",
        phone: i[0] || "",
        email: "",
      }));

      downloadVCard(data, "contatos_revzap.vcf");
    } else {
      const data = [
        ...formatedData
          .filter((i) => i[0] !== undefined)
          .map((i) => [i[0]!, i[1] || ""]),
      ];

      downloadCSV(data, "contatos_revzap.csv");
    }
  }

  return (
    <div className="w-full h-full flex flex-col items-center gap-5 overflow-auto">
      <div className="w-full flex items-center justify-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
        <Icon className="size-3" />
        <span className="text-center text-sm">RevSaver</span>
      </div>

      <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <label htmlFor="prefix">Prefixo</label>
        <input
          ref={prefixRef}
          type="text"
          id="prefix"
          className="w-full rounded p-2 bg-secondary focus:outline-none"
          placeholder="Digite um prefixo..."
        />
      </div>

      <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <div className="w-full flex items-center justify-between gap-2">
          <label htmlFor="type" className="w-full">
            Tipo de contatos
          </label>
          <label className="relative inline-flex items-center cursor-pointer">
            <input
              id="type"
              type="checkbox"
              className="sr-only peer/check"
              checked={withContactType}
              onChange={() => setWithContactType(!withContactType)}
            />
            <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
          </label>
        </div>

        {withContactType && (
          <div className="relative">
            <select
              ref={contactTypeRef}
              className="rounded p-2 bg-secondary"
              name="type"
              id="type-select"
            >
              <option value="all">Todos</option>
              <option value="not-archived">Não arquivados</option>
              <option value="archived">Arquivados</option>
            </select>
            <label
              htmlFor="group"
              className="absolute top-0 right-3 h-full flex items-center"
            >
              <ChevronDown className="size-4 text-gray-400" />
            </label>
          </div>
        )}
      </div>

      <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <div className="w-full flex items-center justify-between gap-2">
          <label htmlFor="groups" className="w-full">
            Usuários de grupos
          </label>
          <label className="relative inline-flex items-center cursor-pointer">
            <input
              id="groups"
              type="checkbox"
              className="sr-only peer/check"
              checked={withGroups}
              onChange={() => setWithGroups(!withGroups)}
            />
            <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
          </label>
        </div>

        {withGroups && (
          <>
            <ChatsSelect
              setItems={setChats}
              label="Selecione os grupos"
              canSend={false}
            />
            <div className="w-full flex items-center justify-between gap-2">
              <label htmlFor="withAdmin" className="w-full">
                Remover ADM do grupo
              </label>
              <label className="relative inline-flex items-center cursor-pointer">
                <input
                  id="withAdmin"
                  type="checkbox"
                  className="sr-only peer/check"
                  checked={withAdmin}
                  onChange={() => setWithAdmin(!withAdmin)}
                />
                <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
              </label>
            </div>
          </>
        )}
      </div>

      <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <div className="w-full flex items-center justify-between gap-2">
          <label htmlFor="labels" className="w-full">
            Usuários com etiquetas
          </label>
          <label className="relative inline-flex items-center cursor-pointer">
            <input
              id="labels"
              type="checkbox"
              className="sr-only peer/check"
              checked={withLabels}
              onChange={() => setWithLabels(!withLabels)}
            />
            <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
          </label>
        </div>

        {withLabels && <LabelsSelect setItems={setLabels} />}
      </div>

      <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <div className="w-full flex items-center justify-between gap-2">
          <label htmlFor="steps" className="w-full">
            Usuários de etapas
          </label>
          <label className="relative inline-flex items-center cursor-pointer">
            <input
              id="steps"
              type="checkbox"
              className="sr-only peer/check"
              checked={withSteps}
              onChange={() => setWithSteps(!withSteps)}
            />
            <div className="w-9 h-5 peer-focus/check:outline-none peer-focus/check:ring-4 rounded-full peer/check bg-gray-700 peer-checked/check:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked/check:bg-accent"></div>
          </label>
        </div>

        {withSteps && <StepsSelect setItems={setSteps} />}
      </div>

      <div className="w-full flex items-center gap-3">
        <button
          onClick={() => handleClick("csv")}
          className="w-full bg-primary text-white text-center p-2 rounded"
        >
          Baixar .csv
        </button>
        <button
          onClick={() => handleClick("vcard")}
          className="w-full bg-primary text-white text-center p-2 rounded"
        >
          Baixar vCard
        </button>
      </div>
    </div>
  );
}
