import { Mail, Pencil, ShoppingCart, Zap } from "lucide-react";
import { useContext, useRef, useState } from "react";
import { twMerge } from "tailwind-merge";
import InputPassword from "../input-password";
import Loading from "../loading";
import { HeaderContext, LoginTab } from "../providers/header-context";
import { SessionContext } from "../providers/session-context";
import clsx from "clsx";

export default function LoginModelMain({
  setModelTab,
}: {
  setModelTab: (tab: LoginTab) => void;
}) {
  const [withPassword, setWithPassword] = useState(false);
  const [newPassword, setNewPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [errors, setErrors] = useState<{
    email?: string;
    password?: string;
    form?: string;
  }>({});
  const { session, signIn, checkEmail, setSession } =
    useContext(SessionContext);
  const { setShowCheckout } = useContext(HeaderContext);
  const emailRef = useRef<HTMLInputElement>(null);
  const passwordRef = useRef<HTMLInputElement>(null);
  const passwordConfirmRef = useRef<HTMLInputElement>(null);

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();

    const email = emailRef.current?.value;
    const password = passwordRef.current?.value;
    const passwordConfirm = passwordConfirmRef.current?.value;

    setErrors({});

    if (!email) return;

    if (withPassword) {
      if (newPassword) {
        if (passwordConfirm && passwordConfirm.length < 8) {
          setErrors((prev) => {
            const newErrors = { ...prev };
            newErrors.password = "A senha precisa ter no mínimo 8 caracteres!";
            return newErrors;
          });
          return;
        }

        if (password !== passwordConfirm) {
          setErrors((prev) => {
            const newErrors = { ...prev };
            newErrors.password = "As senhas precisam ser iguais!";
            return newErrors;
          });
          return;
        }
      }

      setIsLoading(true);
      setSession(undefined);

      signIn({ email, password, passwordConfirm })
        .then((response) => {
          if (response) {
            setShowCheckout(false);
          }
        })
        .catch((error) => {
          setErrors((prev) => {
            const newErrors = { ...prev };
            newErrors.form =
              error.message || "Ocorreu um erro. Tente novamente!";
            return newErrors;
          });

          if (passwordRef.current) {
            passwordRef.current.value = "";
          }

          if (passwordConfirmRef.current) {
            passwordConfirmRef.current.value = "";
          }
        })
        .finally(() => setIsLoading(false));
    } else {
      setIsLoading(true);

      checkEmail(email)
        .then((response) => {
          if (!response) return;

          setWithPassword(true);

          if (response.withoutPassword) {
            setNewPassword(true);

            setErrors((prev) => {
              const newErrors = { ...prev };
              newErrors.password = "Crie uma nova senha para continuar!";
              return newErrors;
            });
          }
        })
        .catch((error) => {
          setErrors((prev) => {
            const newErrors = { ...prev };
            newErrors.form =
              error.message || "Ocorreu um erro. Tente novamente!";
            return newErrors;
          });

          if (passwordRef.current) {
            passwordRef.current.value = "";
          }

          if (passwordConfirmRef.current) {
            passwordConfirmRef.current.value = "";
          }
        })
        .finally(() => setIsLoading(false));
    }
  }

  function reset() {
    if (emailRef.current) {
      emailRef.current.value = "";
    }

    if (passwordRef.current) {
      passwordRef.current.value = "";
    }

    if (passwordConfirmRef.current) {
      passwordConfirmRef.current.value = "";
    }

    setErrors({});
    setWithPassword(false);
    setNewPassword(false);
  }

  return (
    <div className="w-full flex flex-col gap-10">
      {session?.logged && !isLoading ? (
        <div className="w-full flex flex-col gap-10">
          <div className="w-full flex flex-col gap-2 text-center">
            <h3 className="text-xl font-bold">Sua assinatura expirou…</h3>
            <span className="text-sm">
              Faça a compra de um dos planos para continuar utilizando todas
              funções da RevZap
            </span>
          </div>

          <button
            onClick={() => setModelTab("plans")}
            className="w-full bg-primary p-2 rounded text-white text-center animate-pulse flex items-center justify-center gap-2 visited:text-white"
          >
            <ShoppingCart className="size-3.5" strokeWidth={3} />
            <span>Comprar agora</span>
          </button>
        </div>
      ) : (
        <form
          action=""
          onSubmit={handleSubmit}
          className="w-full flex flex-col gap-10"
        >
          <div className="w-full flex flex-col gap-2 text-center">
            <h3 className="text-xl font-bold">Já possui uma conta?</h3>
            <span className="text-sm">
              Entre com suas credenciais para acessar sua conta
            </span>
          </div>

          <div className="w-full flex items-start flex-col gap-2">
            <div className="w-full flex flex-col gap-5">
              <div className="w-full relative flex items-center text-black">
                <label htmlFor="email" className="absolute left-2 z-10">
                  <Mail className="size-4" />
                </label>
                <div className="flex w-full items-start gap-2 flex-col relative">
                  <input
                    ref={emailRef}
                    className={twMerge(
                      "w-full bg-white rounded flex items-center gap-3 border-none outline-none px-8 py-2 text-sm",
                      withPassword && "cursor-not-allowed",
                    )}
                    id="email"
                    type="email"
                    placeholder="Email"
                    required
                    readOnly={withPassword}
                  />
                </div>
                <button
                  type="button"
                  onClick={reset}
                  disabled={!withPassword}
                  className={twMerge(
                    "absolute right-0 p-1.5 rounded",
                    withPassword ? "visible" : "invisible",
                  )}
                >
                  <Pencil className="size-4" />
                </button>
              </div>

              {withPassword && (
                <>
                  <div className="flex flex-col gap-2">
                    <InputPassword ref={passwordRef} />
                  </div>

                  {newPassword && (
                    <div className="flex flex-col gap-2">
                      <InputPassword ref={passwordConfirmRef} />
                    </div>
                  )}
                </>
              )}
            </div>
            {withPassword && !newPassword && (
              <button
                type="button"
                onClick={() => setModelTab("forget-password")}
                className="text-sm cursor-pointer  hover:underline"
              >
                Esqueceu sua senha?
              </button>
            )}

            {errors.password && (
              <p className="text-red-500">{errors.password}</p>
            )}
            {errors.form && <p className="text-red-500">{errors.form}</p>}
          </div>

          <div className="relative w-full">
            {isLoading && <Loading />}

            <button
              type="submit"
              className="w-full bg-primary p-2 rounded text-white text-center"
              disabled={isLoading}
            >
              Entrar
            </button>
          </div>

          <div className="w-full flex flex-col gap-2 text-center">
            <h3 className="text-xl font-bold">Ainda não tem uma conta?</h3>
            <span className="text-sm">
              Adquira sua conta <b className="font-bold">Premium</b> agora
            </span>
            <button
              onClick={() => setModelTab("plans_video")} // plans
              className="w-full bg-primary p-2 rounded text-white text-center animate-pulse flex items-center justify-center gap-2 visited:text-white"
            >
              <Zap className="size-3.5" strokeWidth={3} />
              <span>Comprar agora Revzap</span>
            </button>
          </div>
        </form>
      )}
    </div>
  );
}
