import { saveAs } from "file-saver";
import JSZip from "jszip";
import { Upload } from "lucide-react";
import { ChangeEvent, useState } from "react";
import db from "../../models/db";
import Spinner from "../spinner";
import { getActiveUser } from "../utils/functions";

const MenuExportTab = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [isLoadingImport, setIsLoadingImport] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handlerClickBackup = async () => {
    setIsLoading(true);

    try {
      const backupData = {
        groups: await db.groups.toArray(),
        items: await db.items.toArray(),
        scripts: await db.scripts.toArray(),
        steps: (await db.steps.toArray()).map((step) => ({
          ...step,
          users: Array.isArray(step.users) ? step.users.join(",") : "",
        })),
        schedules: await db.schedules.toArray(),
        indexes: await db.indexes.toArray(),
        triggers: await db.triggers.toArray(),
        shoots: await db.shoots.toArray(),
        user: await db.user.toArray(),
        shotTriggers: await db.shotTriggers.toArray(),
      };

      const activeUser = await getActiveUser();

      const jsonData = JSON.stringify(
        { ...backupData, activeUser: activeUser?.user },
        null,
        2,
      );

      const today = new Date();
      const formattedDate =
        `${String(today.getUTCDate()).padStart(2, "0")}/` +
        `${String(today.getUTCMonth() + 1).padStart(2, "0")}/` +
        `${today.getUTCFullYear()}`;

      const formattedTime =
        `${String(today.getUTCHours()).padStart(2, "0")}:` +
        `${String(today.getUTCMinutes()).padStart(2, "0")}:` +
        `${String(today.getUTCSeconds()).padStart(2, "0")}`;

      const dateTime = `${formattedDate}-${formattedTime}`;

      // Criar blob do JSON
      const blob = new Blob([jsonData], { type: "application/json" });

      // Salvar como arquivo JSON
      saveAs(blob, `backup-revzap-${dateTime}.json`);
    } catch (error) {
      window.dispatchEvent(
        new CustomEvent("showErrorMessage", {
          detail: {
            message: "Ocorreu um erro ao gerar o backup.",
            details: (error as Error).message,
          },
        }),
      );
      console.error("Error ao gerars backup:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handlerClickImport = async (e: ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return;

    const file = e.target.files[0];

    if (!file.name.startsWith("backup-revzap")) {
      setError(
        "Arquivo de backup inválido. Este arquivo não está no formato correto.",
      );

      return;
    }

    // Verificar se é arquivo JSON ou ZIP/RAR
    const isJsonFile = file.name.endsWith(".json");
    const isZipFile = file.name.endsWith(".zip") || file.name.endsWith(".rar");

    if (!isJsonFile && !isZipFile) {
      setError(
        "Arquivo de backup inválido. Aceitamos apenas arquivos .json, .zip ou .rar.",
      );
      return;
    }

    try {
      setIsLoadingImport(true);

      let jsonData: string;

      if (isJsonFile) {
        // Processar arquivo JSON diretamente
        jsonData = await file.text();
      } else {
        // Processar arquivo ZIP/RAR
        const zip = await JSZip.loadAsync(file);
        const jsonFile = zip.file("backup.json");

        if (!jsonFile) {
          setIsLoadingImport(false);
          setError(
            "Arquivo de backup inválido. Este arquivo não está no formato correto.",
          );
          return;
        }

        jsonData = await jsonFile.async("string");
      }

      await Promise.all([
        db.groups.clear(),
        db.items.clear(),
        db.scripts.clear(),
        db.steps.clear(),
        db.schedules.clear(),
        db.indexes.clear(),
        db.triggers.clear(),
        db.shoots.clear(),
        db.user.clear(),
      ]);

      const importedData = JSON.parse(jsonData);

      const activeUser = await getActiveUser();

      if (!activeUser) {
        setError(
          "Usuário não encontrado. Verifique se o usuário está logado e tente novamente.",
        );
        return;
      }

      importedData.steps = importedData.steps.map(
        (step: { users: string | string[]; [key: string]: unknown }) => ({
          ...step,
          users:
            typeof step.users === "string"
              ? step.users
                  .split(",")
                  .map((u: string) => {
                    const trimmed = u.trim();
                    if (!trimmed) return null;

                    if (
                      trimmed.endsWith("@c.us") ||
                      trimmed.endsWith("@g.us") ||
                      trimmed.endsWith("@lid")
                    ) {
                      return trimmed;
                    }

                    return `${trimmed}@lid`;
                  })
                  .filter(Boolean)
              : [],
        }),
      );

      await Promise.all([
        db.groups.bulkPut(importedData.groups || []),
        db.items.bulkPut(importedData.items || []),
        db.scripts.bulkPut(importedData.scripts || []),
        db.steps.bulkPut(importedData.steps || []),
        db.schedules.bulkPut(importedData.schedules || []),
        db.indexes.bulkPut(importedData.indexes || []),
        db.triggers.bulkPut(importedData.triggers || []),
        db.shoots.bulkPut(importedData.shoots || []),
        db.user.bulkPut(importedData.user || []),
        db.shotTriggers.bulkPut(importedData.shotTriggers || []),
      ]);

      setError(null);
      chrome.runtime.sendMessage({
        action: "reloadTab",
      });
    } catch (err) {
      console.log("Error ao importar backup:", err);
      setError(
        "Ocorreu um erro ao importar o backup. Verifique se o arquivo é válido e tente novamente.",
      );
    } finally {
      console.log("Importação concluída");
      setIsLoadingImport(false);
    }
  };

  return (
    <div className="w-full h-full flex flex-col items-center gap-8 overflow-auto">
      <div className="flex flex-col gap-y-2">
        <div className="w-full flex items-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
          <span className="text-center text-sm">Exportar</span>
        </div>
        <ol className="text-sm space-y-2">
          <li className="dark:text-white/50 text-black/50">
            <strong className="dark:text-white text-black">
              Inicie o processo:
            </strong>{" "}
            Para gerar um backup dos seus dados, clique no botão &quot;Baixar
            backup&quot; abaixo. Isso dará início à criação do arquivo.
          </li>
          <li className="dark:text-white/50 text-black/50">
            <strong className="dark:text-white text-black">
              Aguarde a geração do arquivo:
            </strong>{" "}
            Após clicar, o sistema criará um arquivo JSON com o nome{" "}
            <code>backup-revzap-(data atual).json</code>, onde &quot;data
            atual&quot; corresponde ao dia do backup.
          </li>
          <li className="dark:text-white/50 text-black/50">
            <strong className="dark:text-white text-black">
              Faça o download do arquivo:
            </strong>{" "}
            Assim que estiver pronto, o download será iniciado automaticamente.
            Se isso não acontecer, verifique as permissões do navegador para
            downloads automáticos.
          </li>
          <li className="dark:text-white/50 text-black/50">
            <strong className="dark:text-white text-black">
              Guarde o backup com segurança:
            </strong>{" "}
            Após baixar o arquivo JSON, armazene-o em um local seguro para
            futuras restaurações, caso necessário.
          </li>
        </ol>
        <button
          onClick={handlerClickBackup}
          disabled={isLoading}
          className="w-full bg-primary text-white text-center p-2 rounded"
        >
          {isLoading ? (
            <Spinner className="mx-auto" />
          ) : (
            <span>Baixar backup</span>
          )}
        </button>
      </div>
      <div className="flex flex-col gap-y-2">
        <div className="w-full flex items-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
          <span className="text-center text-sm">Importar</span>
        </div>
        <ol className="text-sm space-y-2">
          <li className="dark:text-white/50 text-black/50">
            <strong className="dark:text-white text-black">
              Escolha o arquivo:{" "}
            </strong>{" "}
            Clique no botão &quot;Clique aqui ou arraste o arquivo&quot; para
            selecionar o arquivo de backup.
          </li>
          <li className="dark:text-white/50 text-black/50">
            <strong className="dark:text-white text-black">
              Selecione o backup correto:{" "}
            </strong>{" "}
            Escolha o arquivo JSON nomeado como{" "}
            <code>backup-revzap-(data do backup).json</code> ou arquivos ZIP/RAR
            de backups antigos.
          </li>
          <li className="dark:text-white/50 text-black/50">
            <strong className="dark:text-white text-black">
              Inicie a importação:{" "}
            </strong>{" "}
            O sistema processará o arquivo automaticamente. Aguarde o
            carregamento dos dados.
          </li>
          <li className="dark:text-white/50 text-black/50">
            <strong className="dark:text-white text-black">
              Verifique a finalização:{" "}
            </strong>{" "}
            Uma notificação será exibida quando a importação for concluída com
            sucesso.
          </li>
          <li className="dark:text-white/50 text-black/50">
            <strong className="dark:text-white text-black">
              Atualize a página:{" "}
            </strong>{" "}
            Após a conclusão, recarregue a página para visualizar os dados
            importados.
          </li>
          <li className="dark:text-white/50 text-black/50">
            <strong className="dark:text-white text-black">Atenção: </strong> Os
            dados atuais do sistema serão substituídos pelo conteúdo do backup
            importado.
          </li>
        </ol>
        <div className="w-full flex items-center justify-center">
          <label
            htmlFor="dropzone-file"
            className="w-full h-24 flex flex-col items-center justify-center gap-3 rounded cursor-pointer bg-secondary p-2"
          >
            {isLoadingImport ? (
              <Spinner className="size-16 !fill-primary" />
            ) : (
              <Upload className="size-8" />
            )}
            <input
              id="dropzone-file"
              type="file"
              accept=".json,.zip,.rar"
              className="hidden"
              onChange={handlerClickImport}
            />
          </label>
        </div>
        {error && <p className="text-red-500">{error}</p>}
      </div>
      {/* <button
				onClick={handleClearData}
				className="w-full bg-primary text-white text-center p-2 rounded"
			>
				Limpar dados
			</button> */}
    </div>
  );
};

export default MenuExportTab;
