import { twMerge } from "tailwind-merge";
import { getIconByType } from "./header";
import { useContext } from "react";
import { HeaderContext } from "./providers/header-context";
import { Settings2 } from "lucide-react";
import { ShotTriggers } from "../models/db";

export default function TriggerCard({
	item,
	className,
}: { item: ShotTriggers; className?: string }) {
	const Icon = getIconByType("shot-triggers-list");
	const { setActiveItem, setTab } = useContext(HeaderContext);

	function handleClickActive(
		e: React.MouseEvent<HTMLButtonElement, MouseEvent>,
	) {
		e.stopPropagation();

		setActiveItem({ shotTrigger: item });
		setTab("shot-triggers");
	}

	return (
		<button
			onClick={(e) => handleClickActive(e)}
			className={twMerge(
				"w-full flex items-center justify-between bg-neutral hover:bg-primary/50 gap-3 rounded-lg p-2 text-foreground duration-300",
				className,
			)}
		>
			<div className="flex items-center gap-3">
				<Icon className="size-3" />
				<span className="text-sm">{item.title}</span>
			</div>
			<div className="flex items-center gap-3">
				<div className="px-2 py-1 duration-300 hover:bg-white/50 rounded">
					<Settings2 className="w-4 min-w-4" />
				</div>
			</div>
		</button>
	);
}
