import { twMerge } from "tailwind-merge"

export default function Loading({ className }: { className?: string }) {
  return (
    <div className={twMerge(
      "absolute w-full h-full flex items-center justify-center gap-1 m-auto select-none backdrop-blur-2xs bg-black/10",
      className
    )}>
      <div className="w-2 h-2 bg-foreground rounded-full animate-[bounce_0.5s_infinite]"></div>
      <div className="w-2 h-2 bg-foreground rounded-full [animation-delay:100ms] animate-[bounce_0.5s_infinite]"></div>
      <div className="w-2 h-2 bg-foreground rounded-full [animation-delay:200ms] animate-[bounce_0.5s_infinite]"></div>
    </div>
  )
}