import { getBaseUrl } from "../../lib/base-url";
import { urls } from "../utils/checkout";

const baseUrl = getBaseUrl();

export default function LoginModelIndicate() {
  return (
    <div className="w-full flex items-center flex-col gap-5">
      <div className="flex items-center gap-2">
        <img src={baseUrl + "/assets/icon.png"} alt="Logo" className="w-10" />
      </div>

      <div className="max-w-2xl flex flex-col gap-1 text-center">
        <h1 className="font-bold text-xl">
          Indique a RevZap e ganhe 50% de comissão todos os meses
        </h1>
      </div>

      <div className="w-[42rem] max-w-full aspect-video">
        <iframe
          sandbox="allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox"
          credentialless=""
          className="z-10 w-full h-full rounded bg-black"
          src={urls.video.indicate}
          width="100%"
          height="300"
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
          referrerPolicy="strict-origin-when-cross-origin"
          allowFullScreen
        ></iframe>
      </div>

      <a
        href={urls.indicate}
        rel="noopener noreferrer"
        target="_blank"
        className="w-full p-2 rounded bg-primary text-center text-white font-bold animate-pulse"
      >
        Afilie-se a RevZap agora!
      </a>
    </div>
  );
}
