import { useLiveQuery } from "dexie-react-hooks"
import { useEffect, useState } from "react"
import db from "../../models/db"

export default function useSettingsUpdate() {
  const [chatBlur, setChatBlur] = useState(false)
  const user = useLiveQuery(() => db.user.where("id").equals(1).first(), [])

  useEffect(() => {
    if (!user) return

    setChatBlur(user.chatBlur || false)
  }, [user])

  useEffect(() => {
    modifyChatBlur()

    const observer = new MutationObserver(modifyChatBlur)

    const elem = document.querySelector("#pane-side")

    if (!elem) return

    observer.observe(elem, { childList: true, subtree: true })

    return () => observer.disconnect()
  }, [chatBlur])

  function modifyChatBlur() {
    const element = document.querySelector('#pane-side > div[data-tab="4"]')

    if (!element) return

    if (chatBlur) {
      element.classList.add("ext-chat-blur")
    } else {
      element.classList.remove("ext-chat-blur")
    }
  }
}