import { useLiveQuery } from "dexie-react-hooks";
import db, { Item } from "../../models/db";
import { useContext, useEffect, useState } from "react";
import { HeaderContext } from "../providers/header-context";

type Validate = {
	[key: string]: string | undefined;
};

type ItemSet = {
	item?: Item;
	validateErrors: Validate;
};

type Set = {
	newItem: Partial<Item>;
	groupId?: number;
};

export function useItemSet({ item, validateErrors }: ItemSet) {
	const [errors, setErrors] = useState<Validate>({});
	const groups = useLiveQuery(() => db.groups.toArray(), [], []);
	const scripts = useLiveQuery(() => db.scripts.toArray(), [], []);
	const { setTab } = useContext(HeaderContext);

	useEffect(() => {
		if (item) {
			setErrors({});
		}
	}, [item]);

	function validateForm(newItem: Partial<Item>): boolean {
		const newErrors: { [key: string]: string | undefined } = {};

		for (const [key, value] of Object.entries(newItem)) {
			if (key in validateErrors && !value) {
				newErrors[key] = validateErrors[key];
			}
		}

		setErrors(newErrors);

		return Object.keys(newErrors).length === 0;
	}

	async function saveItem({ newItem, groupId }: Set) {
		if (!validateForm(newItem)) return;

		let newItemID;

		try {
			if (item?.id) {
				newItemID = await db.items.put({
					...(newItem as Item),
					id: item.id,
				});
			} else {
				newItemID = await db.items.add(newItem as Item);
			}

			if (newItemID !== undefined) {
				try {
					await handleGroupAssociation(newItemID, groupId);
					setTab("main");
				} catch (error) {
					console.error("Erro ao associar grupo:", error);
					throw new Error("Falha ao associar o item ao grupo");
				}
			} else {
				throw new Error("Falha ao salvar item: ID não retornado");
			}
		} catch (error) {
			console.error("Erro ao salvar item:", error);
			throw new Error("Falha ao salvar o item. Tente novamente.");
		}
	}

	async function handleGroupAssociation(newItemID: number, groupId?: number) {
		const inGroup = checkGroupAssociation(item?.id);

		if (groupId) {
			const group = groups.find((i) => i.id == Number(groupId));

			if (group?.id) {
				if (inGroup?.id) {
					await db.removeGroupItem(inGroup.id, newItemID);
				}
				await db.addGroupItem(group.id, { id: newItemID, type: "item" });
			}
		} else {
			if (inGroup?.id) {
				await db.removeGroupItem(inGroup.id, newItemID);
			}
		}
	}

	async function removeItem() {
		if (!item) return;

		if (window.confirm("Deseja realmente excluir este item?")) {
			if (item.id) {
				await db.items.delete(item.id);

				try {
					await removeItemFromGroups(item.id);
					await removeItemFromScripts(item.id);
				} catch {}

				setTab("main");
			}
		}
	}

	function checkGroupAssociation(itemId?: number) {
		return groups.find((i) =>
			i.items?.find((i) => i.id == itemId && i.type == "item"),
		);
	}

	function checkScriptAssociation(itemId?: number) {
		return scripts.find((i) => i.items?.find((i) => i.id == itemId));
	}

	async function removeItemFromGroups(itemId: number) {
		const group = checkGroupAssociation(itemId);
		if (group?.id) {
			await db.removeGroupItem(group.id, itemId);
		}
	}

	async function removeItemFromScripts(itemId: number) {
		const script = checkScriptAssociation(itemId);
		if (script?.id) {
			await db.removeScriptItem(script.id, itemId);
		}
	}

	return { saveItem, removeItem, errors };
}
