import { Copy, FolderX, SendHorizontal } from "lucide-react";
import { useContext, useEffect, useMemo, useRef, useState } from "react";
import { twMerge } from "tailwind-merge";
import db, { Item, Script } from "../models/db";
import { getIconByType } from "./header";
import useAutoScroll from "./hooks/auto-scroll";
import { HeaderContext, LoginTab } from "./providers/header-context";
import { SessionContext } from "./providers/session-context";
import Spinner from "./spinner";
import {
  convertAudioToOgg,
  getSelectedItems,
  updateAudio,
  validateAudioIsOgg,
} from "./utils/functions";

function normalizeChatId(id?: string | null) {
  if (!id) return "";
  return id.replace(/@(lid|c\.us|g\.us)$/gi, "");
}

function resolveManualStateForChat(
  chatId: string | null,
  manualScripts: Record<
    string,
    { scriptId?: number | null; startedAt?: number | null }
  >,
) {
  if (!chatId) return undefined;

  const directMatch = manualScripts[chatId];
  if (directMatch) {
    return directMatch;
  }

  const normalizedActive = normalizeChatId(chatId);
  if (!normalizedActive) return undefined;

  const fallbackEntry = Object.entries(manualScripts).find(([key]) => {
    return normalizeChatId(key) === normalizedActive;
  });

  return fallbackEntry?.[1];
}

export default function ItemCard({
  item,
  className,
  groupId,
}: {
  item: Item | Script;
  className?: string;
  groupId?: number;
}) {
  const isScriptItem = item.itemType === "script";
  const type = isScriptItem ? "script" : (item as Item).type;
  const [isLoading, setIsLoading] = useState(false);
  const Icon = getIconByType(type || "script");
  const { scrollRef, handleMouseEnter, handleMouseLeave } = useAutoScroll();
  const {
    setActiveItem,
    setTab,
    setShowCheckout,
    showCheckout,
    modelTab,
    setModelTab,
    runningScriptId,
    activeChatId,
    manualScriptsByChat,
  } = useContext(HeaderContext);
  const { session } = useContext(SessionContext);
  const [manualButtonDebouncing, setManualButtonDebouncing] = useState(false);
  const manualDebounceTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(
    null,
  );

  const manualStateForActiveChat = useMemo(
    () => resolveManualStateForChat(activeChatId, manualScriptsByChat),
    [activeChatId, manualScriptsByChat],
  );

  const manualScriptsRunningIds = useMemo(() => {
    const ids = new Set<number>();
    Object.values(manualScriptsByChat).forEach((state) => {
      if (typeof state?.scriptId === "number") {
        ids.add(state.scriptId);
      }
    });
    return ids;
  }, [manualScriptsByChat]);

  const manualScriptIdForActiveChat =
    manualStateForActiveChat?.scriptId ?? null;
  const manualScriptRunningInActiveChat =
    typeof manualScriptIdForActiveChat === "number";
  const isCurrentManualScriptRunning =
    manualScriptRunningInActiveChat &&
    isScriptItem &&
    typeof item.id === "number" &&
    manualScriptIdForActiveChat === item.id;

  useEffect(() => {
    return () => {
      if (manualDebounceTimeoutRef.current) {
        clearTimeout(manualDebounceTimeoutRef.current);
      }
    };
  }, []);

  function startManualSendDebounce() {
    if (manualDebounceTimeoutRef.current) {
      clearTimeout(manualDebounceTimeoutRef.current);
    }

    setManualButtonDebouncing(true);
    manualDebounceTimeoutRef.current = setTimeout(() => {
      setManualButtonDebouncing(false);
      manualDebounceTimeoutRef.current = null;
    }, 1000);
  }

  async function handleClickRemove(
    e: React.MouseEvent<HTMLButtonElement, MouseEvent>,
  ) {
    e.stopPropagation();

    if (groupId && item.id) {
      await db.removeGroupItem(
        groupId,
        item.id,
        type === "script" ? "script" : "item",
      );
    }
  }

  async function handleDuplicate(
    e: React.MouseEvent<HTMLDivElement, MouseEvent>,
  ) {
    e.stopPropagation();

    let allowed = false;

    if (session?.permissions) {
      allowed = session.permissions.includes("EXTENSION");
    }

    if (!allowed) {
      const tab: LoginTab = "login";
      let value = !showCheckout;

      if (tab) {
        if (tab !== modelTab) value = true;
        setModelTab(tab);
      }

      setShowCheckout(value);
      return;
    }

    if (
      session?.logged &&
      session?.trialStatus === "TRIAL_EXPIRED" &&
      !session?.hasPlan
    ) {
      console.log(
        "[item-card.handleDuplicate] BLOQUEIO POR TRIAL EXPIRADO:",
        "\n  trialStatus:",
        session.trialStatus,
        "\n  hasPlan:",
        session.hasPlan,
        "\n  permissions:",
        session.permissions,
        "\n  email:",
        session.email,
      );
      setModelTab("free-trial");
      setShowCheckout(true);
      return;
    }

    try {
      if (type !== "script") {
        const newItem: Item = {
          ...(item as Item),
          id: undefined,
          title: `${(item as Item).title} (cópia)`,
        };

        await db.items.add(newItem);
      } else {
        const newScript: Script = {
          ...(item as Script),
          id: undefined,
          title: `${(item as Script).title} (cópia)`,
        };

        await db.scripts.add(newScript);
      }

      window.dispatchEvent(
        new CustomEvent("showErrorMessage", {
          detail: { message: "Item duplicado com sucesso." },
        }),
      );
    } catch (error) {
      console.error("Erro ao duplicar item:", error);
    }
  }

  function handleClickActive() {
    if (type) {
      setActiveItem({ item: item as Item });
    } else {
      setActiveItem({ script: item as Script });
    }

    setTab(type || "script");
  }

  async function handleClick(e: React.MouseEvent<HTMLElement, MouseEvent>) {
    e.stopPropagation();

    if (manualButtonDebouncing) return;

    let allowed = false;

    if (session?.permissions) {
      allowed = session.permissions.includes("EXTENSION");
    }

    if (!allowed) {
      const tab: LoginTab = "plans_video";
      let value = !showCheckout;

      if (!session?.logged) {
        setModelTab("login");
        setShowCheckout(true);
        return;
      }

      if (tab) {
        if (tab !== modelTab) value = true;
        setModelTab(tab);
      }

      setShowCheckout(value);
      return;
    }

    if (
      session?.logged &&
      session?.trialStatus === "TRIAL_EXPIRED" &&
      !session?.hasPlan
    ) {
      console.log(
        "[item-card.handleClick] BLOQUEIO POR TRIAL EXPIRADO:",
        "\n  trialStatus:",
        session.trialStatus,
        "\n  hasPlan:",
        session.hasPlan,
        "\n  permissions:",
        session.permissions,
        "\n  email:",
        session.email,
      );
      setModelTab("free-trial");
      setShowCheckout(true);
      return;
    }

    if (!isScriptItem && type === "wait") return;

    try {
      if (isScriptItem) {
        if (manualScriptBlocksActiveChat && !isCurrentManualScriptRunning) {
          window.dispatchEvent(
            new CustomEvent("showErrorMessage", {
              detail: {
                message:
                  "Já existe um script manual em execução neste chat. Pare-o para iniciar outro.",
              },
            }),
          );
          return;
        }

        startManualSendDebounce();

        const selectedItem = await getSelectedItems([
          {
            id: item.id ?? 0,
            type: "script",
          },
        ]);

        window.dispatchEvent(
          new CustomEvent("sendScript", {
            detail: {
              item: selectedItem[0],
              isShooting: true,
              executionType: "manual",
            },
          }),
        );

        return;
      }

      startManualSendDebounce();

      const itemTyped = item as Item;
      switch (itemTyped.type) {
        case "text":
          window.dispatchEvent(
            new CustomEvent("sendMessage", {
              detail: {
                message: itemTyped.content,
                mentionAll: itemTyped.mentionAll,
              },
            }),
          );
          break;
        case "image":
          window.dispatchEvent(
            new CustomEvent("sendFile", {
              detail: {
                file: itemTyped.content,
                caption: itemTyped.caption,
                mentionAll: itemTyped.mentionAll,
                type: "image",
                fileName: itemTyped.filename,
              },
            }),
          );
          break;
        case "video":
          window.dispatchEvent(
            new CustomEvent("sendFile", {
              detail: {
                file: itemTyped.content,
                caption: itemTyped.caption,
                mentionAll: itemTyped.mentionAll,
                type: "video",
                fileName: itemTyped.filename,
              },
            }),
          );
          break;
        case "audio": {
          const isOgg = validateAudioIsOgg(itemTyped.content || "");

          if (isOgg) {
            window.dispatchEvent(
              new CustomEvent("sendFile", {
                detail: {
                  file: itemTyped.content,
                  caption: itemTyped.caption,
                  mentionAll: itemTyped.mentionAll,
                  type: "audio",
                  fileName: itemTyped.filename,
                },
              }),
            );
          } else {
            setIsLoading(true);

            if (!itemTyped.content || !itemTyped.filename || !itemTyped.id) {
              setIsLoading(false);
              window.dispatchEvent(
                new CustomEvent("showErrorMessage", {
                  detail: { message: "Erro ao enviar áudio" },
                }),
              );
              return;
            }

            try {
              const attemptConversion = (): Promise<{ base64: string }> => {
                return new Promise((resolve, reject) => {
                  const timeout = setTimeout(() => {
                    reject(
                      new Error(
                        "Timeout: Conversão de áudio excedeu 10 segundos",
                      ),
                    );
                  }, 10000);

                  try {
                    if (!itemTyped.content || !itemTyped.filename) {
                      reject(new Error("Arquivo de áudio não encontrado"));
                      return;
                    }

                    convertAudioToOgg({
                      file: itemTyped.content,
                      fileName: itemTyped.filename,
                    }).then((result) => {
                      clearTimeout(timeout);
                      resolve(result);
                    });
                  } catch (error) {
                    clearTimeout(timeout);
                    reject(error);
                  }
                });
              };

              const convertedFile = await attemptConversion();

              await updateAudio(itemTyped.id, convertedFile.base64);

              window.dispatchEvent(
                new CustomEvent("sendFile", {
                  detail: {
                    file: convertedFile.base64,
                    caption: itemTyped.caption,
                    mentionAll: itemTyped.mentionAll,
                    type: "audio",
                    fileName: itemTyped.filename,
                  },
                }),
              );
            } catch (error: any) {
              console.error("Erro na conversão de áudio:", error);
              const errorMessage = error?.message?.includes("logado")
                ? "Você precisa estar logado para enviar áudios"
                : "Erro ao converter áudio para envio";

              window.dispatchEvent(
                new CustomEvent("showErrorMessage", {
                  detail: {
                    message: errorMessage,
                  },
                }),
              );
            } finally {
              setIsLoading(false);
            }
          }
          break;
        }

        case "doc":
          window.dispatchEvent(
            new CustomEvent("sendFile", {
              detail: {
                file: itemTyped.content,
                caption: itemTyped.caption,
                mentionAll: itemTyped.mentionAll,
                type: "document",
                fileName: itemTyped.filename,
              },
            }),
          );
          break;
        case "contact":
          window.dispatchEvent(
            new CustomEvent("sendContact", {
              detail: {
                content: itemTyped.content,
                name: itemTyped.name,
              },
            }),
          );
          break;
        default:
          throw new Error("Tipo de item não suportado: " + itemTyped.type);
      }
    } catch (error) {
      console.error("Erro ao processar item:", error);
      throw error;
    }
  }

  const scriptId = isScriptItem && typeof item.id === "number" ? item.id : null;

  const automationRunningCard =
    isScriptItem && scriptId !== null && runningScriptId === scriptId;

  const runningCardClasses = "bg-primary/50 hover:bg-primary/75 animate-pulse";
  const manualRunningCardClasses =
    "bg-primary/75 text-foreground hover:bg-primary/30 animate-pulse"; // keep single bg-* so green stays visible
  const idleCardClasses = "bg-white/10 hover:bg-primary/50";

  const manualScriptBlocksActiveChat =
    isScriptItem && manualScriptRunningInActiveChat;

  const manualBlockedCardClasses = isCurrentManualScriptRunning
    ? "opacity-70 cursor-not-allowed"
    : "";

  const scriptRunningManuallySomewhere =
    scriptId !== null && manualScriptsRunningIds.has(scriptId);

  const automationHighlightActive =
    automationRunningCard && !scriptRunningManuallySomewhere;

  const scriptButtonDisabled = isScriptItem
    ? automationHighlightActive ||
      manualButtonDebouncing ||
      isLoading ||
      isCurrentManualScriptRunning
    : manualButtonDebouncing || isLoading;

  const manualButtonTitle = isCurrentManualScriptRunning
    ? "Este script manual está em execução neste chat."
    : undefined;

  return (
    <div
      onClick={handleClickActive}
      className={twMerge(
        "w-full flex items-center justify-between gap-3 rounded p-2 text-white duration-300",
        isCurrentManualScriptRunning
          ? manualRunningCardClasses
          : automationHighlightActive
            ? runningCardClasses
            : idleCardClasses,
        manualBlockedCardClasses,
        className,
        isLoading && "opacity-50",
      )}
    >
      <div className="flex items-center gap-3 min-w-0 flex-1">
        <Icon className="size-4 shrink-0" />
        <span
          ref={scrollRef}
          className="text-sm whitespace-nowrap overflow-hidden cursor-default"
          onMouseEnter={handleMouseEnter}
          onMouseLeave={handleMouseLeave}
          title={item.title}
        >
          {item.title}
        </span>
      </div>
      <div className="flex items-center gap-1 shrink-0">
        {groupId && (
          <button
            onClick={handleClickRemove}
            className="px-2 py-1 duration-300 hover:bg-white/50 rounded"
          >
            <FolderX className="w-4 min-w-4" />
          </button>
        )}
        {type !== "wait" && (
          <>
            <div
              onClick={handleDuplicate}
              className="px-2 py-1 duration-300 hover:bg-white/50 rounded"
            >
              <Copy className="w-4 min-w-4" />
            </div>
            <button
              type="button"
              onClick={scriptButtonDisabled ? undefined : handleClick}
              disabled={scriptButtonDisabled}
              title={manualButtonTitle}
              className={twMerge(
                "px-2 py-1 duration-300 rounded",
                scriptButtonDisabled
                  ? "opacity-60 cursor-not-allowed"
                  : "hover:bg-white/50",
              )}
            >
              {isLoading ? (
                <Spinner className="w-4 min-w-4" />
              ) : (
                <SendHorizontal className="w-4 min-w-4" />
              )}
            </button>
          </>
        )}
      </div>
    </div>
  );
}
