import { useSortable } from "@dnd-kit/sortable"
import { CSSProperties, useEffect, useState } from "react"
import { CSS } from "@dnd-kit/utilities"
import { IndexedContainer } from "./hooks/get-indexes"

export default function ItemSortableContainer({
  children,
  item,
  items
}: {
  children?: React.ReactNode,
  item: IndexedContainer,
  items: IndexedContainer[]
}) {
  const [disabled, setDisabled] = useState(false)
  const {
    active,
    over,
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition
  } = useSortable({ id: item.id! })

  useEffect(() => {
    let disable = false

    if (item.groupId && active?.id !== item.id) {
      const activeItem = items.find(i => i.id === active?.id)
      if (!activeItem?.groupId && over?.id !== active?.id) {
        const overItem = items.find(i => i.id === over?.id)
        if (overItem?.id === item.id) {
          disable = true
        }
      }
    }

    setDisabled(disable)
  }, [active, over])

  const style: CSSProperties = {
    transform: active ? `translate3d(${transform?.x}px, ${transform?.y}px, 0)` : CSS.Transform.toString(transform),
    transition,
  }

  if (!children) return null

  if (disabled) return (
    <div className="w-full opacity-50">
      {children}
    </div>
  )

  return (
    <div
      ref={setNodeRef}
      style={style}
      className="w-full"
      {...attributes}
      {...listeners}
    >
      {children}
    </div>
  )
}