import db, { Step } from "../../models/db"
import { useContext, useEffect, useState } from "react"
import { HeaderContext } from "../providers/header-context"

type Validate = {
  [key: string]: string | undefined
}

type ItemSet = {
  item?: Step,
  validateErrors: Validate
}

type Set = {
  newItem: Partial<Step>,
  groupId?: number
}

export function useStepSet({ item, validateErrors }: ItemSet) {
  const [errors, setErrors] = useState<Validate>({})
  const { setTab, setActiveItem } = useContext(HeaderContext)

  useEffect(() => {
    if (item) {
      setErrors({})
    }
  }, [item])

  function validateForm(newItem: Partial<Step>): boolean {
    const newErrors: { [key: string]: string | undefined } = {}

    for (const [key, value] of Object.entries(newItem)) {
      if (key in validateErrors && !value) {
        newErrors[key] = validateErrors[key]
      }
    }

    setErrors(newErrors)

    return Object.keys(newErrors).length === 0
  }

  async function saveItem({ newItem }: Set) {
    if (!validateForm(newItem)) return

    let newItemID

    if (item?.id) {
      newItemID = await db.steps.put({
        ...newItem as Step,
        id: item.id,
        users: item?.users || newItem?.users || []
      })
    } else {
      newItemID = await db.steps.add(newItem as Step)
    }

    if (newItemID !== undefined) {
      setActiveItem(undefined)
      setTab("step")
    }
  }

  async function removeItem() {
    if (!item) return

    if (window.confirm("Deseja realmente excluir este item?")) {
      if (item.id) {
        await db.steps.delete(item.id)

        setActiveItem(undefined)
        setTab("step")
      }
    }
  }

  return { saveItem, removeItem, errors }
}