import { useContext, useEffect, useRef, useState } from "react";
import { ScriptItemsContext } from "./tabs/script";
import AddMenuLabel from "./add-menu-label";
import { ItemType } from "../models/db";
import { SquarePlus } from "lucide-react";

type ScriptItemsDataType = Exclude<ItemType, "group" | "script">;

export default function AddMenuScript() {
  const [show, setShow] = useState(false);
  const { addItem } = useContext(ScriptItemsContext);
  const modalRef = useRef<HTMLDivElement>(null);

  const handleClickOutside = (event: MouseEvent) => {
    if (modalRef.current && !modalRef.current.contains(event.target as Node)) {
      setShow(false);
    }
  };

  useEffect(() => {
    if (show) {
      document.addEventListener("mousedown", handleClickOutside);
    } else {
      document.removeEventListener("mousedown", handleClickOutside);
    }
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [show]);

  function handleClick(itemType: ScriptItemsDataType) {
    addItem(itemType);
    setShow(false);
  }

  return (
    <div className="relative">
      <button
        onClick={() => setShow(!show)}
        className="p-2 rounded duration-300 hover:bg-primary/50"
      >
        <SquarePlus className="size-6" />
      </button>

      {show && (
        <div
          ref={modalRef}
          className="z-10 absolute top-full max-h-72 translate-y-3 right-0 p-3 rounded bg-neutral flex flex-col gap-2 shadow-lg overflow-auto"
        >
          <AddMenuLabel itemType="delay" onClick={() => handleClick("delay")} />
          <AddMenuLabel itemType="text" onClick={() => handleClick("text")} />
          <AddMenuLabel itemType="audio" onClick={() => handleClick("audio")} />
          <AddMenuLabel itemType="image" onClick={() => handleClick("image")} />
          <AddMenuLabel itemType="video" onClick={() => handleClick("video")} />
          <AddMenuLabel itemType="doc" onClick={() => handleClick("doc")} />
          <AddMenuLabel
            itemType="contact"
            onClick={() => handleClick("contact")}
          />
          <AddMenuLabel itemType="wait" onClick={() => handleClick("wait")} />
          <AddMenuLabel
            itemType="randomizer"
            onClick={() => handleClick("randomizer")}
          />
          <AddMenuLabel
            itemType="removeStep"
            onClick={() => handleClick("removeStep")}
          />
          <AddMenuLabel
            itemType="addStep"
            onClick={() => handleClick("addStep")}
          />
        </div>
      )}
    </div>
  );
}
