import { Loader, Pause, Play } from "lucide-react";
import { useContext, useEffect, useMemo, useRef, useState } from "react";
import { twMerge } from "tailwind-merge";
import { Shoot, ShootItem } from "../../models/db";
import { getIconByType } from "../header";
import { HeaderContext, LoginTab } from "../providers/header-context";
import { SessionContext } from "../providers/session-context";
import ShootingItem from "../shooting-item";
import { SelectedShoot } from "./shoot";
import {
  getProgress,
  getSelectedItems,
  getShootingById,
  markShootingAsComplete,
  markShootToSent,
  markStatusShooting,
  removePhoneFromShooting,
  waitForShootingPermission,
  verificarMaturadorAtivo,
  desativarMaturadorCompleto,
} from "../utils/functions";

window.addEventListener("markShootingAsSent", async (e: Event) => {
  const { id, chats } = (
    e as CustomEvent<{ id: number; chats: ShootingChat[] }>
  ).detail;

  try {
    await markShootToSent(id, chats);
  } catch (error) {
    console.error("Erro ao marcar disparo como enviado:", error);
  }
});

window.addEventListener("finishShooting", async (e: Event) => {
  const { id } = (e as CustomEvent<{ id: number }>).detail;
  try {
    markShootingAsComplete(id);
  } catch (error) {
    console.error("Erro ao finalizar disparo:", error);
  }
});

export type ShootingChat = {
  sent?: boolean;
  chatId: string;
  userId?: string;
  error?: boolean;
  server?: string | null;
};

export type Shooting = {
  id: number;
  play: boolean;
  chats?: (ShootingChat & {
    sent?: boolean;
    error?: boolean;
  })[];
  done?: boolean;
};

const resetShootingStatus = (chats: ShootingChat[]) => {
  return chats.map((chat) => ({
    ...chat,
    sent: undefined,
    error: undefined,
  }));
};

export default function MenuShootingTab({ item }: { item: Shoot }) {
  const [shooting, setShooting] = useState<Shooting | undefined>();
  const [isShooting, setIsShooting] = useState(false);
  const [isPreparing, setIsPreparing] = useState(false);
  const [isRemoving, setIsRemoving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hydrated, setHydrated] = useState(false);
  const {
    setShowCheckout,
    setModelTab,
    showCheckout,
    modelTab,
    setActiveItem,
    setTab,
    showConfirmModal,
  } = useContext(HeaderContext);
  const { session } = useContext(SessionContext);
  const Icon = getIconByType("shooting");
  const [shootingStatus, setShootingStatus] = useState(item?.status);
  const shootingStatusRef = useRef(shootingStatus);

  useEffect(() => {
    shootingStatusRef.current = shootingStatus;
  }, [shootingStatus]);

  const { total, sent, errors } = useMemo(() => {
    const chats = shooting?.chats || [];
    return {
      total: chats.length,
      sent: chats.filter((i) => i.sent).length,
      errors: chats.filter((i) => i.error).length,
    };
  }, [shooting]);

  const scheduledPast = useMemo(() => {
    try {
      return !!item.schedule && new Date(item.schedule) <= new Date();
    } catch {
      return false;
    }
  }, [item.schedule]);

  useEffect(() => {
    if (!item.id) return;

    // Sempre tenta obter o estado mais recente: primeiro tenta o progresso
    // corrente (memória do engine). Se não existir, busca o registro no DB.
    (async () => {
      try {
        const currentProgress = await getProgress();

        if (currentProgress && currentProgress.id === item.id) {
          setShooting(currentProgress);
          setIsShooting(true);
          setShootingStatus("shooting");
          return;
        }

        const id = item.id!;
        const activeShooting = await getShootingById(id);
        if (activeShooting) {
          // Se o DB diz "shooting" mas o engine não tem progresso ativo,
          // significa que o engine perdeu o estado (ex: reload da página).
          // Nesse caso, mostramos "Retomar" (play:false) em vez de "Pausar",
          // e atualizamos o DB para refletir a realidade (paused).
          const isEngineAlive =
            currentProgress && currentProgress.id === item.id;
          const dbSaysActive = activeShooting.status === "shooting";
          const isOrphaned = dbSaysActive && !isEngineAlive;

          if (isOrphaned) {
            // Engine morreu; corrige DB para "paused" e mostra Retomar
            try {
              const dbMod = await import("../../models/db").then(
                (m) => m.default,
              );
              await dbMod.shoots.update(id, { status: "paused" });
            } catch {
              // best-effort
            }
            setShooting({
              id: activeShooting.id ?? id,
              play: false,
              chats: activeShooting.contacts,
            });
            setIsShooting(false);
            setShootingStatus("paused");
          } else {
            setShooting({
              id: activeShooting.id ?? id,
              play: activeShooting.status === "shooting",
              chats: activeShooting.contacts,
            });
            setIsShooting(activeShooting.status === "shooting");
            setShootingStatus(activeShooting.status);
          }
        } else {
          // Fallback para itens sem registro no DB
          setShooting({ id: id, play: false, chats: item.contacts });
          setIsShooting(false);
          setShootingStatus(item.status);
        }
      } catch (err) {
        // Em caso de erro, usa dados do prop como fallback
        console.error(err);
        const id = item.id ?? 0;
        setShooting({ id: id, play: false, chats: item.contacts });
        setIsShooting(false);
        setShootingStatus(item.status);
      }
      // Marca que a reidratação inicial terminou (DB/engine lido)
      setHydrated(true);
    })();
  }, [item]);

  useEffect(() => {
    const handleProgress = async (e: Event) => {
      const { shooting } = (e as CustomEvent<{ shooting: Shooting }>).detail;

      if (shooting && shooting.id === item.id) {
        setShootingStatus("shooting");
        setShooting(shooting);
        // Mantém isShooting=true enquanto o registro de disparo existir
        setIsShooting(true);
      }
    };

    const handleStatus = (e: Event) => {
      const { isSending } = (e as CustomEvent<{ isSending: boolean }>).detail;
      // Evita sobrescrever o estado persistido (por exemplo 'paused') no mount.
      // Se o DB já indica que o shoot está 'paused' ou 'shooted', não ativamos o flag
      // apenas por um evento transitório de isSending.
      if (isSending) {
        const persisted = shootingStatusRef.current;
        if (persisted === "paused" || persisted === "shooted") {
          return;
        }
        setIsShooting(true);
        return;
      }
      // se isSending === false, não alteramos o estado aqui (o evento de finish
      // ou sendingProgress cuida de setar isShooting=false quando apropriado)
      return;
    };

    const handleFinish = async (e: Event) => {
      const { id } = (e as CustomEvent<{ id: number }>).detail;
      if (id === item.id) {
        setShootingStatus("shooted");
        setIsShooting(false);
      }
    };
    // Sempre escuta progress e finish
    window.addEventListener("sendingProgress", handleProgress);
    window.addEventListener("finishShooting", handleFinish);

    // O listener de status (isSending) pode ser transitório logo após o mount.
    // Registra somente após a reidratação inicial completar para evitar sobrescrever
    // o estado persistido vindo do DB.
    if (hydrated) {
      window.addEventListener("sendingStatus", handleStatus);
    }

    return () => {
      window.removeEventListener("sendingProgress", handleProgress);
      window.removeEventListener("finishShooting", handleFinish);
      if (hydrated) {
        window.removeEventListener("sendingStatus", handleStatus);
      }
    };
  }, [item.id, item.status]);

  useEffect(() => {
    if (shooting?.done) {
      setShootingStatus("shooted");
      setIsShooting(false);
    }
  }, [shooting]);

  async function buildActionGroupsItems() {
    if (!item.randomizeActions) return undefined;
    const storedGroups = item.actionGroups;
    if (!storedGroups || !Array.isArray(storedGroups) || !storedGroups.length) {
      return undefined;
    }

    const resolvedGroups: any[][] = [];

    const groups = storedGroups as ShootItem[][];

    for (const group of groups) {
      if (!Array.isArray(group) || !group.length) continue;
      const items = await getSelectedItems(group);
      resolvedGroups.push(items.filter(Boolean));
    }

    return resolvedGroups.length ? resolvedGroups : undefined;
  }

  const handlePauseShooting = async (
    selectedItems: SelectedShoot[],
    actionGroupsItems?: any[][],
  ) => {
    const groups = actionGroupsItems ?? (await buildActionGroupsItems());

    window.dispatchEvent(
      new CustomEvent("pauseShoting", {
        detail: { id: item.id },
      }),
    );

    window.dispatchEvent(
      new CustomEvent("sendShooting", {
        detail: {
          chatsId: shooting?.chats,
          interval: item.interval,
          items: selectedItems,
          id: item.id,
          play: false,
          randomizeActions: item.randomizeActions,
          actionGroups: groups,
        },
      }),
    );
  };

  const handleStartShooting = async (
    selectedItems: SelectedShoot[],
    actionGroupsItems?: any[][],
  ) => {
    // ATUALIZAÇÃO OTIMISTA: Atualiza UI e banco local IMEDIATAMENTE
    setIsShooting(true);

    // Verifica se precisa resetar antes de atualizar status
    const isShooted = shootingStatus === "shooted";
    const chatsToUse =
      isShooted && shooting?.chats
        ? resetShootingStatus(shooting.chats)
        : shooting?.chats;

    // Atualiza estado local do shooting imediatamente
    setShooting({
      id: item.id ?? 0,
      play: true,
      chats: chatsToUse,
    });

    // Atualiza status na UI imediatamente
    setShootingStatus("shooting");

    // Atualiza no banco local imediatamente (não bloqueia UI)
    if (item.id) {
      const db = await import("../../models/db").then((m) => m.default);
      db.shoots.update(item.id, { status: "shooting" }).catch((error) => {
        console.error(
          "[Shooting] Erro ao atualizar status no banco local:",
          error,
        );
      });
    }

    setIsPreparing(false);

    // Dispara o evento de envio IMEDIATAMENTE (não espera 2 segundos)
    const finalActionGroups =
      actionGroupsItems ?? (await buildActionGroupsItems());

    window.dispatchEvent(
      new CustomEvent("sendShooting", {
        detail: {
          chatsId: chatsToUse,
          interval: item.interval,
          items: selectedItems,
          id: item.id,
          play: true,
          randomizeActions: item.randomizeActions,
          actionGroups: finalActionGroups,
        },
      }),
    );
  };

  const handleClick = async () => {
    try {
      let allowed = false;

      if (session?.permissions) {
        allowed = session.permissions.includes("EXTENSION");
      }

      if (!allowed) {
        const tab: LoginTab = "plans_video";
        let value = !showCheckout;

        if (!session?.logged) {
          setModelTab("login");
          setShowCheckout(true);
          return;
        }

        if (tab) {
          if (tab !== modelTab) value = true;
          setModelTab(tab);
        }

        setShowCheckout(value);
        return;
      }

      if (
        session?.logged &&
        session?.trialStatus === "TRIAL_EXPIRED" &&
        !session?.hasPlan
      ) {
        console.log(
          "[shooting.handleClick] BLOQUEIO POR TRIAL EXPIRADO:",
          "\n  trialStatus:",
          session.trialStatus,
          "\n  hasPlan:",
          session.hasPlan,
          "\n  permissions:",
          session.permissions,
          "\n  email:",
          session.email,
        );
        setModelTab("free-trial");
        setShowCheckout(true);
        return;
      }

      if (!shooting?.chats) return;

      // Verifica se o maturador está ativo antes de verificar disparo em andamento
      const maturadorAtivo = await verificarMaturadorAtivo();

      // Se o maturador está desligado mas há um disparo do maturador em andamento, cancela ele
      if (!maturadorAtivo) {
        try {
          const db = await import("../../models/db").then((m) => m.default);
          const allShoots = await db.shoots.toArray();
          const maturadorShoots = allShoots.filter(
            (s: any) => s.hidden === true && s.status === "shooting",
          );

          if (maturadorShoots && maturadorShoots.length > 0) {
            console.log(
              "[Maturador] Maturador desligado mas há disparos em andamento, cancelando...",
            );
            for (const shoot of maturadorShoots) {
              if (shoot.id) {
                window.dispatchEvent(
                  new CustomEvent("pauseShoting", {
                    detail: { id: shoot.id },
                  }),
                );
                await new Promise((resolve) => setTimeout(resolve, 100));
                await db.shoots.update(shoot.id, { status: "shooted" });
                window.dispatchEvent(
                  new CustomEvent("finishShooting", {
                    detail: { id: shoot.id },
                  }),
                );
              }
            }
            // Aguarda um pouco para garantir que os eventos foram processados
            await new Promise((resolve) => setTimeout(resolve, 200));
          }
        } catch (error) {
          console.error("[Maturador] Erro ao cancelar disparos órfãos:", error);
        }
      }

      if (maturadorAtivo) {
        // Mostra popup de confirmação
        showConfirmModal(
          async () => {
            // Usuário confirmou - desativa o maturador e prossegue
            const desativado = await desativarMaturadorCompleto();
            if (!desativado) {
              setError("Erro ao desativar o RevProtect. Tente novamente.");
              return;
            }

            // Agora verifica se pode prosseguir com o disparo
            const canProceed = await waitForShootingPermission(item.id ?? 0);

            if (!canProceed) {
              setError(
                "Já existe um disparo em andamento. Aguarde a conclusão.",
              );
              return;
            }

            setError(null);
            setIsPreparing(true);
            const selectedItems = await getSelectedItems(item.items);
            const actionGroupsItems = await buildActionGroupsItems();

            if (shooting?.play) {
              await handlePauseShooting(selectedItems, actionGroupsItems);
              setIsPreparing(false);
            } else {
              await handleStartShooting(selectedItems, actionGroupsItems);
            }
          },
          "RevProtect está ativo",
          "O RevProtect será desligado automaticamente para iniciar o disparo.",
        );
        return;
      }

      // Se o maturador não está ativo, verifica normalmente se pode prosseguir
      const canProceed = await waitForShootingPermission(item.id ?? 0);

      if (!canProceed) {
        setError("Já existe um disparo em andamento. Aguarde a conclusão.");
        return;
      }

      setError(null);
      setIsPreparing(true);
      const selectedItems = await getSelectedItems(item.items);
      const actionGroupsItems = await buildActionGroupsItems();

      if (shooting?.play) {
        await handlePauseShooting(selectedItems, actionGroupsItems);
        setIsPreparing(false);
      } else {
        await handleStartShooting(selectedItems, actionGroupsItems);
      }
    } catch (error) {
      console.error("Error:", error);
      setError("Ocorreu um erro desconhecido ao disparar as mensagens");
      setIsPreparing(false);
    }
  };

  async function handleRemoveContact(chatId: string) {
    if (!item.id) return;

    try {
      setIsRemoving(true);
      const result = await removePhoneFromShooting(item.id, chatId);

      if (result) {
        window.dispatchEvent(
          new CustomEvent("updateShootingProgress", {
            detail: {
              id: item.id,
              chats: shooting?.chats?.filter((c) => c.chatId !== chatId),
            },
          }),
        );
      }
    } catch (error) {
      console.error(`Erro ao remover contato ${chatId}:`, error);
    } finally {
      setIsRemoving(false);
    }
  }

  function handleReschedule() {
    setActiveItem({ shoot: item });
    setTab("shoot");
  }

  async function handleCancelSchedule() {
    if (!item.id) return;

    try {
      const db = await import("../../models/db").then((m) => m.default);
      await db.shoots.update(item.id, { schedule: undefined });
      // Recarregar para atualizar a UI
      window.location.reload();
    } catch (error) {
      console.error("Erro ao cancelar agendamento:", error);
      setError("Erro ao cancelar agendamento");
    }
  }

  return (
    <div className="w-full h-full flex flex-col items-center gap-5 overflow-auto">
      <div className="w-full flex items-center gap-2 bg-gradient-to-r from-neutral via-neutral to-transparent rounded px-5 py-2">
        <Icon className="size-4" />
        <span className="text-center text-sm">
          {/* Disparar */ item?.title ? `Disparar: ${item.title}` : "Disparar"}
        </span>
      </div>

      <div className="w-full flex justify-center flex-col gap-5 bg-gradient-to-r from-neutral via-neutral to-transparent rounded p-5 text-sm">
        <div className="w-full flex items-center justify-between">
          <label htmlFor="title">Status</label>
          {total > 0 && (
            <span className="font-bold">
              {sent} / {total} {errors > 0 && ` (${errors}x)`}
            </span>
          )}
        </div>

        <div className="w-full bg-gray-200 rounded-full h-2.5 dark:bg-gray-700">
          <div
            style={{
              width: `${shooting?.chats?.length ? (shooting.chats.filter((i) => i.sent).length / shooting.chats.length) * 100 : 0}%`,
            }}
            className={twMerge(
              "h-2.5 rounded-full duration-200 ease-in-out",
              shooting?.chats?.length &&
                !shooting.chats.filter((i) => !i.sent).length
                ? "bg-primary animate-none"
                : "bg-blue-500 animate-pulse",
            )}
          ></div>
        </div>
      </div>

      {item.schedule && ( // mostrar agendamento se há
        <div className="w-full flex items-center justify-center flex-col gap-2">
          <p>
            Agendado para{" "}
            <span className="font-bold">
              {item.schedule ? new Date(item.schedule).toLocaleString() : ""}
            </span>
          </p>
          {scheduledPast && item.status !== "shooted" && (
            <div className="flex flex-col gap-2 w-full">
              <span className="text-center text-sm text-red-500">
                O disparo foi acionando enquanto o Whatsapp Web estava fechado,
                reagende o disparo para outra data.
              </span>
            </div>
          )}
        </div>
      )}

      <button
        onClick={item.schedule ? handleCancelSchedule : handleClick}
        disabled={isPreparing}
        className={twMerge(
          "w-full flex items-center justify-center gap-2 text-white p-2 rounded duration-300 disabled:opacity-50 disabled:cursor-not-allowed",
          isShooting && shooting?.play ? "bg-red-500" : "bg-primary",
        )}
      >
        {isPreparing ? (
          <>
            <Loader className="size-4 animate-spin" />
            <span>Preparando...</span>
          </>
        ) : isShooting ? (
          shooting?.play ? (
            <>
              <Pause className="size-4" />
              <span>Pausar</span>
            </>
          ) : (
            <>
              <Play className="size-4" />
              <span>Retomar</span>
            </>
          )
        ) : (
          <>
            <Play className="size-4" />
            <span>
              {item.schedule
                ? "Cancelar agendamento"
                : shootingStatus === "shooted"
                  ? "Disparar novamente"
                  : "Disparar"}
            </span>
          </>
        )}
      </button>

      <ShootingItem
        chats={shooting?.chats}
        onRemove={handleRemoveContact}
        canRemove={!shooting?.play}
        isRemoving={isRemoving}
      />

      {error && <span className="text-red-500">{error}</span>}
    </div>
  );
}
