import { ChevronDown, Search } from "lucide-react";
import { useEffect, useState } from "react";
import { twMerge } from "tailwind-merge";
import { getIconByType } from "./header";
import { Label } from "./providers/header-context";
import { getAllLabels } from "./utils/functions";

export default function LabelsSelect({
  setItems,
  defaultItem,
}: {
  setItems: (labels: string[]) => void;
  defaultItem?: string[];
}) {
  const [labels, setLabels] = useState<Label[]>([]);
  const [show, setShow] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [selecteds, setSelecteds] = useState<string[]>([]);

  useEffect(() => {
    getAllLabels().then((labels) => {
      setLabels(labels);
    });
  }, []);

  useEffect(() => {
    setItems(selecteds);
  }, [selecteds]);

  useEffect(() => {
    if (defaultItem) {
      setSelecteds(defaultItem);
    }
  }, [defaultItem]);

  function handleClick(itemId?: string) {
    if (!itemId) return;

    if (selecteds.includes(itemId)) {
      setSelecteds(selecteds.filter((id) => id !== itemId));
    } else {
      setSelecteds([...selecteds, itemId]);
    }
  }

  return (
    <div className="w-full max-h-56 flex flex-col gap-5 rounded p-2 bg-secondary">
      <button
        onClick={() => setShow(!show)}
        className="w-full flex items-center justify-between gap-2"
      >
        <span>Selecione as etiquetas</span>
        <ChevronDown
          className={twMerge(
            "size-4 text-gray-400 duration-300 ease-in-out",
            show ? "rotate-180" : "rotate-0"
          )}
        />
      </button>
      {show && (
        <>
          <div className="w-full flex items-center gap-2 bg-neutral rounded px-5 py-1 cursor-pointer">
            <label htmlFor="search">
              <Search className="w-5 text-gray-400" />
            </label>
            <input
              id="search"
              className="w-full bg-transparent py-1 focus:outline-none"
              type="text"
              placeholder="Buscar..."
              value={searchTerm}
              onChange={(event) => setSearchTerm(event.target.value)}
            />
          </div>

          <div className="flex w-full flex-col gap-2 overflow-auto">
            {labels
              .filter((item) =>
                item.name?.toLowerCase().includes(searchTerm.toLowerCase())
              )
              .map((item) => (
                <LabelItem
                  key={item.id}
                  item={item}
                  selected={selecteds.includes(item.id)}
                  onClick={() => handleClick(item.id)}
                />
              ))}
          </div>
        </>
      )}
    </div>
  );
}

function LabelItem({
  item,
  selected,
  ...props
}: {
  item: Label;
  selected?: boolean;
} & React.HTMLAttributes<HTMLDivElement>) {
  const Icon = getIconByType("label");

  return (
    <div
      className={twMerge(
        "w-full gap-2 p-2 rounded",
        selected ? "bg-primary/50" : "bg-neutral"
      )}
      {...props}
    >
      <button className="w-full flex items-center justify-between gap-2">
        <div className="w-full flex items-center gap-2 whitespace-nowrap overflow-hidden">
          <Icon className="size-3" />
          <span className="text-ellipsis overflow-hidden">{item.name}</span>
        </div>
        <span className="font-bold">{item.count || 0}</span>
      </button>
    </div>
  );
}
