import Dexie, { Table } from "dexie";

export type ItemType =
  | "text"
  | "audio"
  | "image"
  | "video"
  | "doc"
  | "contact"
  | "delay"
  | "react"
  | "group"
  | "addStep"
  | "removeStep"
  | "step"
  | "script"
  | "wait"
  | "randomizer";

export type ItemScriptType = Exclude<ItemType, "group" | "script">;

export interface GroupItemType {
  id: number;
  index: number;
  type: "item" | "script";
}

interface ScriptItemType {
  stepId: number;
  id?: number;
  index: number;
  delay?: number;
  type?: ItemScriptType;
}

export interface ShootItem {
  id: number;
  type: "item" | "script";
}

export interface ShotTriggersItem {
  id: number;
  type: "item" | "script";
}

export type TriggerEvent =
  | "on_message"
  | "keyword_message"
  | "first_message"
  | "first_message_day";

export type TriggerSchedule = "time" | "business_open" | "business_closed";

export type TriggerScheduleData = {
  start?: string;
  end?: string;
};

export interface Group {
  id?: number;
  title: string;
  color: string;
  items: GroupItemType[];
}

export interface Item {
  id?: number;
  type: ItemScriptType;
  title: string;
  content?: string;
  caption?: string;
  filename?: string;
  name?: string;
  itemType: string;
  mentionAll?: boolean;
  hidden?: boolean; // Para ocultar items do maturador da UI
}

export interface Script {
  type: string;
  id?: number;
  title: string;
  items: ScriptItemType[];
  labelId?: string;
  itemType: string;
  addStepIds?: number[];
  delStepIds?: number[];
  track?: boolean;
}

export interface Randomizer {
  id?: number;
  type: "randomizer";
  title: string;
  items: number[]; // IDs dos itens que serão randomizados
  itemType: "randomizer";
}

export interface ShotTriggers {
  id?: number;
  title: string;
  active: boolean;
  items: ShootItem[];
  itemType: string;
  triggerMessages: string[];
  condition: TriggerCondition;
  ignoreCase: boolean;
  samePerson: boolean;
}

export type TriggerCondition =
  | "equals"
  | "contains"
  | "startsWith"
  | "samePerson";

export interface ShotTriggersTransformed {
  id?: number;
  title: string;
  active: boolean;
  items: (Item | (Script & { type: "script" }) | undefined)[];
  itemType: string;
  triggerMessages: string[];
  condition: TriggerCondition;
  ignoreCase: boolean;
  samePerson: boolean;
}

export interface Step {
  id?: number;
  title: string;
  index: number;
  users: string[];
}

export interface Schedule {
  id?: number;
  title: string;
  time: string;
  chatId: string;
  itemId: number;
  itemType: "item" | "script";
}

export interface Index {
  id?: number;
  index: number;
  itemId: number;
  itemType: "group" | "item" | "script";
}

export interface Trigger {
  id?: number;
  title: string;
  event: TriggerEvent;
  trigger?: string;
  schedule?: TriggerSchedule;
  scheduleData?: TriggerScheduleData;
  itemId: number;
  itemType: "item" | "script";
  track?: boolean;
}

export type ContactSource = {
  type: "group" | "step" | "spreadsheet" | "selectedGroups" | "allContacts";
  ids: string[] | number[];
};

export type ShootContact = {
  chatId: string;
  userId?: string;
  source?: ContactSource;
  server?: string | null;
};

export type ShootingChat = ShootContact & {
  sent?: boolean;
  error?: boolean;
};

export interface Shoot {
  id?: number;
  title: string;
  contacts?: ShootingChat[];
  interval?: number[];
  items: ShootItem[];
  status?: "shooting" | "shooted" | "paused";
  schedule?: string;
  withAdmin?: boolean;
  randomizeActions?: boolean;
  actionGroups?: ShootItem[][];
  hidden?: boolean; // Para ocultar shoots do maturador
}

export interface User {
  id?: number;
  webhook?: string;
  chatBlur?: boolean;
}

export interface MaturadorNumero {
  id?: number;
  whatsapp: string; // Ex: "5511999999999@c.us"
  ligado: boolean; // true/false
  enviadas: number; // Contador
  recebidas: number; // Contador
  timeout: number; // Timestamp último envio
  timeout_recebe: number; // Timestamp última recepção
  createdAt?: Date;
  updatedAt?: Date;
}

export interface MaturadorMensagem {
  id?: number;
  frase: string; // Texto da mensagem
  createdAt?: Date;
}

export interface MaturadorConfig {
  id?: number;
  ativo: boolean; // Liga/desliga o maturador
  intervaloMin: number; // Min segundos entre ciclos (padrão: 5)
  intervaloMax: number; // Max segundos entre ciclos (padrão: 10)
  limiteEnvio: number; // Reinicia após N envios (padrão: 3)
  comandoLigar: string; // Padrão: "numale"
  comandoDesligar: string; // Mensagem específica para desligar
}

export class Data extends Dexie {
  groups: Table<Group, number>;
  items: Table<Item, number>;
  scripts: Table<Script, number>;
  steps: Table<Step, number>;
  schedules: Table<Schedule, number>;
  indexes: Table<Index, number>;
  triggers: Table<Trigger, number>;
  shoots: Table<Shoot, number>;
  shotTriggers: Table<ShotTriggers, number>;
  user: Table<User, number>;
  maturador_numeros: Table<MaturadorNumero, number>;
  maturador_mensagens: Table<MaturadorMensagem, number>;
  maturador_config: Table<MaturadorConfig, number>;
  randomizers: Table<Randomizer, number>;

  constructor() {
    super("revzap");
    this.version(8).stores({
      groups: "++id, title, color, *items",
      items: "++id, type, title, content, caption, filename, name, mentionAll",
      scripts: "++id, title, *items,  labelId, *addStepIds, *delStepIds, track",
      steps: "++id, title, index, *users",
      schedules: "++id, title, time, chatId, itemId, itemType",
      indexes: "++id, index, itemId, itemType",
      triggers:
        "++id, title, event, trigger, schedule, scheduleData, itemId, itemType, track",
      shotTriggers: "++id, title, *items, itemType",
      shoots:
        "++id, title, schedule, *contacts, *interval, *items, status, withAdmin, randomizeActions, actionGroups, hidden",
      user: "++id, webhook, chatBlur",
      maturador_numeros:
        "++id, whatsapp, ligado, enviadas, recebidas, timeout, timeout_recebe",
      maturador_mensagens: "++id, frase",
      maturador_config: "++id, ativo",
      randomizers: "++id, title, type",
    });

    this.groups = this.table("groups");
    this.items = this.table("items");
    this.scripts = this.table("scripts");
    this.steps = this.table("steps");
    this.schedules = this.table("schedules");
    this.indexes = this.table("indexes");
    this.triggers = this.table("triggers");
    this.shoots = this.table("shoots");
    this.user = this.table("user");
    this.shotTriggers = this.table("shotTriggers");
    this.maturador_numeros = this.table("maturador_numeros");
    this.maturador_mensagens = this.table("maturador_mensagens");
    this.maturador_config = this.table("maturador_config");
    this.randomizers = this.table("randomizers");
  }

  async addGroupItem(groupId: number, group: Omit<GroupItemType, "index">) {
    await this.groups
      .where("id")
      .equals(groupId)
      .modify((item) => {
        item.items.push({ ...group, index: item.items.length });
      });
  }

  async removeGroupItem(
    groupId: number,
    itemId: number,
    type: "item" | "script" = "item"
  ) {
    await this.groups
      .where("id")
      .equals(groupId)
      .modify((item) => {
        item.items = item.items.filter(
          (i) => !(i.id === itemId && i.type === type)
        );
      });
  }

  async addScriptItem(scriptId: number, script: ScriptItemType) {
    await this.scripts
      .where("id")
      .equals(scriptId)
      .modify((item) => {
        item.items.push(script);
      });
  }

  async removeScriptItem(scriptId: number, itemId: number) {
    await this.scripts
      .where("id")
      .equals(scriptId)
      .modify((item) => {
        item.items = item.items.filter((i) => i.id !== itemId);
      });
  }

  async addUserStep(stepId: number, userId: string, oneStepOnly = false) {
    const step = await this.steps.get(stepId);

    if (step) {
      if (!step.users.find((i) => i === userId)) {
        step.users.push(userId);
        await this.steps.put(step);
      }

      if (oneStepOnly) {
        const steps = await this.steps.toArray();

        const stepsChanges = steps
          .filter((i) => i.id !== stepId && i.users.find((i) => i === userId))
          .map((i) => {
            i.users = i.users.filter((i) => i !== userId);
            return i;
          });

        await this.steps.bulkPut(stepsChanges);
      }
    }
  }

  async removeUserStep(stepId: number, userId: string) {
    const step = await this.steps.get(stepId);

    if (step) {
      step.users = step.users.filter((i) => i !== userId);
      await this.steps.put(step);
    }
  }
}

const db = new Data();

export default db;
