import { createContext, useEffect, useState, useRef } from "react";
import {
  verificarMaturadorAtivo,
  desativarMaturadorCompleto,
} from "../utils/functions";

export type Session = {
  logged: boolean;
  lastRefresh?: Date;
  email?: string;
  role?: UserRole;
  permissions?: string[];
  hasPlan?: boolean;
  trialStatus?: TrialStatus;
  trialEndsAt?: Date;
  statusReview?: string;
  scoreReview?: number;
  msgReview?: string;
};

export enum UserRole {
  ADMIN = "ADMIN",
  USER = "USER",
  PARTNER = "PARTNER",
  MASTER = "MASTER",
}

export enum TrialStatus {
  TRIAL_NOT_STARTED = "TRIAL_NOT_STARTED",
  TRIAL_ACTIVE = "TRIAL_ACTIVE",
  TRIAL_EXPIRED = "TRIAL_EXPIRED",
}

type SignIn = {
  email: string;
  password?: string;
  passwordConfirm?: string;
};

type SignInResponse = Promise<Session | undefined>;

type CheckEmailResponse = Promise<{ ok: boolean; withoutPassword?: boolean }>;

type ForgetPasswordResponse = Promise<{ ok: boolean; message?: string }>;

type ChangePasswordResponse = Promise<{ ok: boolean; message?: string }>;

type ValidateCodeResponse = Promise<{
  ok: boolean;
  message?: string;
  token?: string;
}>;

type SessionContextType = {
  session: Session | undefined;
  setSession: (session: Session | undefined) => void;
  signIn: (data: SignIn) => SignInResponse;
  checkEmail: (email: string) => CheckEmailResponse;
  signOut: () => Promise<boolean | undefined>;
  isLoading: boolean;
  forgetPassword: (email: string) => ForgetPasswordResponse;
  validateCode: (code: string, email: string) => ValidateCodeResponse;
  changePassword: (
    newPassword: string,
    token: string,
  ) => ChangePasswordResponse;
};

export const SessionContext = createContext({} as SessionContextType);

export function SessionProvider({ children }: { children: React.ReactNode }) {
  const [session, setSession] = useState<Session | undefined>();
  const [isLoading, setIsLoading] = useState(true);
  const previousPermissionsRef = useRef<string[] | undefined>(undefined);

  useEffect(() => {
    checkSession().finally(() => setIsLoading(false));

    const intervalId = setInterval(checkSession, 5 * 60000);

    return () => clearInterval(intervalId);
  }, []);

  useEffect(() => {
    const f = async (
      request: any,
      sender: chrome.runtime.MessageSender,
      sendResponse: (response?: any) => void,
    ) => {
      // Só processa mensagens de "session.updated"
      if (request.action === "session.updated") {
        if (request.data.logged !== undefined) {
          const newSession = request.data;

          // Atualiza cache local imediatamente
          if (newSession.logged) {
            await chrome.storage.local.set({ cachedSession: newSession });
          } else {
            await chrome.storage.local.remove("cachedSession");
          }

          setSession(newSession);

          // Verifica se o usuário perdeu a permissão do maturador
          const tinhaPermissao =
            previousPermissionsRef.current?.includes("MATURADOR");
          const temPermissao = newSession.permissions?.includes("MATURADOR");

          if (tinhaPermissao && !temPermissao) {
            // Usuário perdeu a permissão - desativa o maturador
            console.log(
              "[Maturador] Permissão perdida, desativando maturador...",
            );
            const maturadorAtivo = await verificarMaturadorAtivo();
            if (maturadorAtivo) {
              await desativarMaturadorCompleto();
            }
          } else if (temPermissao) {
            // Se ainda tem permissão, verifica também na API do maturador
            try {
              const response = await chrome.runtime.sendMessage({
                action: "maturador.get",
              });

              if (response?.ok && !response.temPermissao) {
                // Não tem mais permissão na API - desativa o maturador
                console.log(
                  "[Maturador] Permissão não encontrada na API, desativando maturador...",
                );
                const maturadorAtivo = await verificarMaturadorAtivo();
                if (maturadorAtivo) {
                  await desativarMaturadorCompleto();
                }
              }
            } catch (error) {
              console.error(
                "[Maturador] Erro ao verificar permissão na API:",
                error,
              );
            }
          }

          previousPermissionsRef.current = newSession.permissions;
        }
        sendResponse(true);
        return true; // Mantém canal aberto se necessário
      }

      // Retorna false para outras mensagens, permitindo que outros listeners processem
      return false;
    };

    chrome.runtime.onMessage.addListener(f);

    return () => chrome.runtime.onMessage.removeListener(f);
  }, []);

  async function checkSession() {
    // PRIMEIRO: Carrega do cache local para resposta instantânea
    try {
      const cachedSession = await chrome.storage.local.get("cachedSession");
      if (cachedSession.cachedSession) {
        const session = cachedSession.cachedSession as Session;
        setSession(session);
        previousPermissionsRef.current = session.permissions;

        // Sincroniza com servidor em background (não bloqueia UI)
        chrome.runtime
          .sendMessage({ action: "session" })
          .then(async (response) => {
            if (response?.logged) {
              const updatedSession = response;

              // Atualiza cache local
              await chrome.storage.local.set({ cachedSession: updatedSession });

              // Verifica mudanças de permissão
              const tinhaPermissao =
                previousPermissionsRef.current?.includes("MATURADOR");
              const temPermissao =
                updatedSession.permissions?.includes("MATURADOR");

              if (tinhaPermissao && !temPermissao) {
                console.log(
                  "[Maturador] Permissão perdida, desativando maturador...",
                );
                const maturadorAtivo = await verificarMaturadorAtivo();
                if (maturadorAtivo) {
                  await desativarMaturadorCompleto();
                }
              } else if (temPermissao) {
                try {
                  const maturadorResponse = await chrome.runtime.sendMessage({
                    action: "maturador.get",
                  });

                  if (
                    maturadorResponse?.ok &&
                    !maturadorResponse.temPermissao
                  ) {
                    console.log(
                      "[Maturador] Permissão não encontrada na API, desativando maturador...",
                    );
                    const maturadorAtivo = await verificarMaturadorAtivo();
                    if (maturadorAtivo) {
                      await desativarMaturadorCompleto();
                    }
                  }
                } catch (error) {
                  console.error(
                    "[Maturador] Erro ao verificar permissão na API:",
                    error,
                  );
                }
              }

              // Atualiza UI apenas se houver mudanças
              if (JSON.stringify(session) !== JSON.stringify(updatedSession)) {
                previousPermissionsRef.current = updatedSession.permissions;
                setSession(updatedSession);
              }
            } else {
              // Sessão expirada - limpa cache
              await chrome.storage.local.remove("cachedSession");
              setSession({ logged: false });
              previousPermissionsRef.current = undefined;
            }
          })
          .catch((error) => {
            console.error("[Session] Erro ao sincronizar sessão:", error);
            // Mantém cache local em caso de erro
          });

        return session;
      }
    } catch (error) {
      console.error("[Session] Erro ao carregar cache:", error);
    }

    // Se não há cache, busca do servidor (primeira vez)
    return await chrome.runtime
      .sendMessage({ action: "session" })
      .then(async (response) => {
        let session: Session;

        if (response?.logged) {
          session = response;

          // Salva no cache local
          await chrome.storage.local.set({ cachedSession: session });

          // Verifica se o usuário perdeu a permissão do maturador
          const tinhaPermissao =
            previousPermissionsRef.current?.includes("MATURADOR");
          const temPermissao = session.permissions?.includes("MATURADOR");

          if (tinhaPermissao && !temPermissao) {
            // Usuário perdeu a permissão - desativa o maturador
            console.log(
              "[Maturador] Permissão perdida, desativando maturador...",
            );
            const maturadorAtivo = await verificarMaturadorAtivo();
            if (maturadorAtivo) {
              await desativarMaturadorCompleto();
            }
          } else if (temPermissao) {
            // Se ainda tem permissão, verifica também na API do maturador
            try {
              const maturadorResponse = await chrome.runtime.sendMessage({
                action: "maturador.get",
              });

              if (maturadorResponse?.ok && !maturadorResponse.temPermissao) {
                // Não tem mais permissão na API - desativa o maturador
                console.log(
                  "[Maturador] Permissão não encontrada na API, desativando maturador...",
                );
                const maturadorAtivo = await verificarMaturadorAtivo();
                if (maturadorAtivo) {
                  await desativarMaturadorCompleto();
                }
              }
            } catch (error) {
              console.error(
                "[Maturador] Erro ao verificar permissão na API:",
                error,
              );
            }
          }

          previousPermissionsRef.current = session.permissions;
          setSession(session);
        } else {
          session = { logged: false };
          setSession(session);
          previousPermissionsRef.current = undefined;
          await chrome.storage.local.remove("cachedSession");
        }

        return session;
      });
  }

  async function signIn({
    email,
    password,
    passwordConfirm,
  }: SignIn): SignInResponse {
    return await chrome.runtime
      .sendMessage({
        action: "session.sign-in",
        data: {
          email,
          password,
          passwordConfirm,
        },
      })
      .then(async (response) => {
        if (response.error) {
          throw new Error(response.error ?? "Ocorreu um erro ao fazer login");
        }

        // Estado provisório: não confiar nas permissões do sign-in; buscar /session em seguida
        if (response) {
          const tempSession: Session = {
            logged: true,
            email: response.user?.email,
            role: response.user?.role,
            trialStatus: response.user?.trialStatus,
            trialEndsAt: response.user?.trialEndsAt,
            lastRefresh: new Date(),
          };

          setSession(tempSession);
          previousPermissionsRef.current = tempSession.permissions;

          // Remove cache antigo para não travar o handleSession
          await chrome.storage.local.remove("cachedSession");

          try {
            const fullSession = await chrome.runtime
              .sendMessage({ action: "session" })
              .catch(() => undefined);

            if (fullSession?.logged) {
              await chrome.storage.local.set({ cachedSession: fullSession });
              previousPermissionsRef.current = fullSession.permissions;
              setSession(fullSession);
            }
          } catch (error) {
            console.error("[Session] sincronização pós-login falhou", error);
          }
        }

        return response;
      });
  }

  async function checkEmail(email: string): CheckEmailResponse {
    return await chrome.runtime
      .sendMessage({ action: "session.email", data: { email } })
      .then((response) => {
        if (response.error) throw new Error(response.error);

        return response;
      });
  }

  async function changePassword(
    newPassword: string,
    token: string,
  ): ChangePasswordResponse {
    return await chrome.runtime
      .sendMessage({
        action: "session.change-password",
        data: { newPassword, token },
      })
      .then((response) => {
        if (response.error) throw new Error(response.error);

        if (!response.ok) {
          throw new Error(
            response.message || "Ocorreu um erro ao tentar alterar a senha!",
          );
        }

        return response;
      });
  }

  async function validateCode(
    code: string,
    email: string,
  ): ValidateCodeResponse {
    return await chrome.runtime
      .sendMessage({ action: "session.validate-code", data: { code, email } })
      .then((response) => {
        if (response.error) throw new Error(response.error);

        return response;
      });
  }

  async function forgetPassword(email: string): ForgetPasswordResponse {
    return await chrome.runtime
      .sendMessage({ action: "session.forget-password", data: { email } })
      .then((response) => {
        return response;
      });
  }
  async function signOut() {
    if (window.confirm("Deseja realmente sair?")) {
      setIsLoading(true);

      try {
        // Desativa o maturador antes de fazer logout
        const maturadorAtivo = await verificarMaturadorAtivo();
        if (maturadorAtivo) {
          console.log("[Maturador] Desativando maturador antes do logout...");
          await desativarMaturadorCompleto();
        }
      } catch (error) {
        console.error(
          "[Maturador] Erro ao desativar maturador no logout:",
          error,
        );
        // Continua com o logout mesmo se falhar
      }

      return await chrome.runtime
        .sendMessage({ action: "session.sign-out" })
        .then(async (response) => {
          if (!response) return false;

          // Limpa cache local imediatamente
          await chrome.storage.local.remove("cachedSession");
          setSession({ logged: false });
          previousPermissionsRef.current = undefined;
          return true;
        })
        .finally(() => setIsLoading(false));
    }
  }

  return (
    <SessionContext.Provider
      value={{
        session,
        setSession,
        signIn,
        checkEmail,
        signOut,
        isLoading,
        forgetPassword,
        validateCode,
        changePassword,
      }}
    >
      {children}
    </SessionContext.Provider>
  );
}
