import { useEffect, useState } from "react"
import db, { Step } from "../../models/db"
import { useLiveQuery } from "dexie-react-hooks"

export default function useGetSteps() {
  const [steps, setSteps] = useState<Step[]>([])
  const setpsDb = useLiveQuery(() => db.steps.orderBy("index").toArray(), [])

  useEffect(() => {
    if (setpsDb) {
      setSteps(setpsDb)
    }
  }, [setpsDb])

  function arrayMove<T>(array: T[], from: number, to: number) {
    const newArray = [...array]
    const startIndex = to < 0 ? newArray.length + to : to

    const item = newArray.splice(from, 1)[0]
    newArray.splice(startIndex, 0, item)

    return newArray
  }

  function updateStepIndex(oldIndex: number, newIndex: number) {
    const newItems = arrayMove(steps, oldIndex, newIndex)

    const result = newItems.map((item, index) => ({
      ...item,
      index
    }))

    setSteps(result)

    db.steps.bulkPut(result)
  }

  return {
    steps,
    updateStepIndex
  }
}