import { ScriptItemsContext, ScriptItemType } from "./tabs/script";
import { Item, Randomizer } from "../models/db";
import { getIconByType, getScriptTitleByType } from "./header";
import CardByType from "./card-by-type";
import { twMerge } from "tailwind-merge";
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import {
  CSSProperties,
  useCallback,
  useContext,
  useEffect,
  useState,
} from "react";
import {
  ChevronDown,
  Contact,
  Eye,
  EyeOff,
  Phone,
  TimerReset,
  Trash2,
} from "lucide-react";

export default function ScriptItem({ item }: { item: ScriptItemType }) {
  const [show, setShow] = useState(item.type === "randomizer");
  const [preview, setPreview] = useState(false);
  const [delayUnit, setDelayUnit] = useState<"segundos" | "minutos" | "horas">(
    item.delayUnit || "segundos"
  );
  const [delayInputValue, setDelayInputValue] = useState<string>(
    (item.delay ?? 1).toString()
  );
  const { setItem, removeItem } = useContext(ScriptItemsContext);
  const Icon = getIconByType(item.type);
  const title = getScriptTitleByType(item.type);

  const {
    active,
    isDragging,
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
  } = useSortable({ id: item.id });

  const style: CSSProperties = {
    transform: active
      ? `translate3d(${transform?.x}px, ${transform?.y}px, 0)`
      : CSS.Transform.toString(transform),
    transition,
  };

  // Sincronizar delayInputValue quando item.delay mudar
  useEffect(() => {
    if (item.delay !== undefined) {
      setDelayInputValue(item.delay.toString());
    }
  }, [item.delay]);

  const changeDelay = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const inputValue = event.target.value;
      // Permite valores vazios durante a digitação
      setDelayInputValue(inputValue);
    },
    []
  );

  const handleDelayBlur = useCallback(() => {
    // Valida apenas ao perder o foco
    const value = delayInputValue === "" || delayInputValue === "-" ? 1 : Number(delayInputValue);

    if (!isNaN(value) && value >= 0) {
      const unitLabel =
        delayUnit === "segundos"
          ? "segundos"
          : delayUnit === "minutos"
            ? "minutos"
            : "horas";

      setItem({
        ...item,
        item: item.item
          ? {
              ...item.item,
              title: `Aguardar ${value} ${unitLabel}...`,
            }
          : undefined,
        delay: value,
        delayUnit,
      });
      // Atualiza o estado local com o valor validado
      setDelayInputValue(value.toString());
    } else {
      // Se o valor for inválido, restaura o valor anterior
      setDelayInputValue((item.delay ?? 1).toString());
    }
  }, [delayInputValue, delayUnit, item, setItem]);

  const changeDelayUnit = useCallback(
    (event: React.ChangeEvent<HTMLSelectElement>) => {
      const newUnit = event.target.value as "segundos" | "minutos" | "horas";
      setDelayUnit(newUnit);

      // Usa o valor atual do input (pode estar vazio durante digitação)
      const inputValue = delayInputValue;
      const currentDelay = inputValue === "" || inputValue === "-" ? (item.delay || 1) : Number(inputValue);
      const validDelay = isNaN(currentDelay) || currentDelay < 0 ? (item.delay || 1) : currentDelay;
      
      const unitLabel =
        newUnit === "segundos"
          ? "segundos"
          : newUnit === "minutos"
            ? "minutos"
            : "horas";

      setItem({
        ...item,
        item: item.item
          ? {
              ...item.item,
              title: `Aguardar ${validDelay} ${unitLabel}...`,
            }
          : undefined,
        delay: validDelay,
        delayUnit: newUnit,
      });
      
      // Atualiza o estado local com o valor validado
      setDelayInputValue(validDelay.toString());
    },
    [item, setItem, delayInputValue]
  );

  // Sincronizar delayUnit quando o item mudar
  useEffect(() => {
    if (item.delayUnit) {
      setDelayUnit(item.delayUnit);
    }
  }, [item.delayUnit]);

  function handleRemove() {
    removeItem(item.id);
  }

  function renderSelected() {
    if (!item.item) return;

    if (item.type === "delay") {
      return (
        <div className="w-full flex flex-col gap-3">
          <div className="w-full flex items-center justify-between gap-2">
            <div className="flex items-center gap-2">
              <Icon className="size-4" />
              <span className="text-sm">
                {item.item?.title || "Aguardar..."}
              </span>
            </div>
            <button onClick={handleRemove}>
              <Trash2 className="size-4 text-red-500" />
            </button>
          </div>

          <div
            className={twMerge(
              "items-center gap-2 text-sm text-gray-400",
              isDragging ? "hidden" : "flex"
            )}
          >
            <TimerReset className="size-4" />
            <div className="flex items-center gap-1 rounded px-2 py-1 bg-secondary">
              <input
                onChange={changeDelay}
                onBlur={handleDelayBlur}
                className="w-10 bg-transparent border-none focus:outline-none text-foreground [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                type="number"
                id="delay"
                value={delayInputValue}
                min="0"
              />
              <select
                value={delayUnit}
                onChange={changeDelayUnit}
                className="bg-transparent border-none focus:outline-none text-foreground text-xs"
              >
                <option value="segundos">segundos</option>
                <option value="minutos">minutos</option>
                <option value="horas">horas</option>
              </select>
            </div>
            <span>aguardando...</span>
          </div>
        </div>
      );
    }

    if (item.type === "randomizer") {
      const randomizerItem = item.item as Randomizer;
      const actionsCount = randomizerItem?.items?.length ?? 0;

      return (
        <div className="w-full flex flex-col gap-3">
          <div className="w-full flex items-center justify-between gap-2">
            <div className="flex items-center gap-2">
              <Icon className="size-4" />
              <span className="text-sm">
                {actionsCount === 0
                  ? "Selecione ações para randomizar"
                  : `${actionsCount} ${actionsCount === 1 ? "ação" : "ações"} randomizadas`}
              </span>
            </div>
            <div className="flex items-center gap-3">
              <button onClick={() => setShow(!show)} className="px-1">
                <ChevronDown
                  className={twMerge(
                    "size-4 duration-300 ease-in-out",
                    show ? "rotate-180" : "rotate-0"
                  )}
                />
              </button>
              <button onClick={handleRemove}>
                <Trash2 className="size-4 text-red-500" />
              </button>
            </div>
          </div>

          <div
            className={twMerge(
              "items-center gap-2 text-sm text-gray-400",
              isDragging ? "hidden" : "flex"
            )}
          >
            <TimerReset className="size-4" />
            <div className="flex items-center gap-1 rounded px-2 py-1 bg-secondary">
              <input
                onChange={changeDelay}
                onBlur={handleDelayBlur}
                className="w-10 bg-transparent border-none focus:outline-none text-foreground [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                type="number"
                id="delay"
                value={delayInputValue}
                min="0"
              />
              <select
                value={delayUnit}
                onChange={changeDelayUnit}
                className="bg-transparent border-none focus:outline-none text-foreground text-xs"
              >
                <option value="segundos">segundos</option>
                <option value="minutos">minutos</option>
                <option value="horas">horas</option>
              </select>
            </div>
            <span>aguardando randomizador...</span>
          </div>

          {show && (
            <div className={twMerge("w-full", isDragging ? "hidden" : "block")}>
              <CardByType item={item} />
            </div>
          )}
        </div>
      );
    }

    const EyeIcon = preview ? EyeOff : Eye;

    function renderContentByType() {
      switch (item.type) {
        case "text": {
          const textItem = item.item as Item;
          return (
            <div className="w-full rounded p-2 bg-secondary whitespace-pre-wrap">
              {textItem.content}
            </div>
          );
        }
        case "audio": {
          const audioItem = item.item as Item;
          return (
            <audio
              src={audioItem.content}
              controls
              controlsList="nodownload noplaybackrate"
              className="w-full rounded"
            ></audio>
          );
        }
        case "image": {
          const imageItem = item.item as Item;
          return (
            <img
              src={imageItem.content}
              alt={imageItem.filename}
              className="w-full max-h-96 rounded"
            />
          );
        }
        case "video": {
          const videoItem = item.item as Item;
          return (
            <video
              src={videoItem.content}
              controls
              controlsList="nodownload noremoteplayback"
              className="w-full max-h-96 rounded"
            >
              Seu navegador não suporta vídeos.
            </video>
          );
        }
        case "doc": {
          const docItem = item.item as Item;
          return <span>{docItem.filename}</span>;
        }
        case "contact": {
          const contactItem = item.item as Item;
          return (
            <div className="flex flex-col gap-2 text-sm">
              <div className="flex items-center gap-2">
                <Contact className="size-3" />
                <span>{contactItem.name}</span>
              </div>
              <div className="flex items-center gap-2">
                <Phone className="size-3" />
                <span>{contactItem.content}</span>
              </div>
            </div>
          );
        }
        default:
          return null;
      }
    }

    return (
      <div className="w-full flex flex-col gap-3">
        <div className="w-full flex items-center justify-between gap-2">
          <div className="flex items-center gap-2">
            <Icon className="size-4" />
            <span className="text-sm">{item.item?.title}</span>
          </div>
          <div className="flex items-center gap-3">
            {["text", "audio", "image", "video", "doc", "contact"].includes(
              item.type
            ) && (
              <button onClick={() => setPreview(!preview)} className="px-1">
                <EyeIcon className="size-4" />
              </button>
            )}
            <button onClick={handleRemove}>
              <Trash2 className="size-4 text-red-500" />
            </button>
          </div>
        </div>

        {["text", "audio"].includes(item.type) && (
          <div
            className={twMerge(
              "items-center gap-2 text-sm text-gray-400",
              isDragging ? "hidden" : "flex"
            )}
          >
            <TimerReset className="size-4" />
            <div className="flex items-center gap-1 rounded px-2 py-1 bg-secondary">
              <input
                onChange={changeDelay}
                onBlur={handleDelayBlur}
                className="w-10 bg-transparent border-none focus:outline-none text-foreground [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                type="number"
                id="delay"
                value={delayInputValue}
                min="0"
              />
              <select
                value={delayUnit}
                onChange={changeDelayUnit}
                className="bg-transparent border-none focus:outline-none text-foreground text-xs"
              >
                <option value="segundos">segundos</option>
                <option value="minutos">minutos</option>
                <option value="horas">horas</option>
              </select>
            </div>
            <span>
              {item.type === "audio" ? "gravando áudio" : "digitando"}...
            </span>
          </div>
        )}

        <div
          className={twMerge(
            "w-full rounded p-2 bg-secondary",
            preview && !isDragging ? "block" : "hidden"
          )}
        >
          {renderContentByType()}
        </div>
      </div>
    );
  }

  function renderUnselected() {
    return (
      <>
        <button
          onClick={() => {
            if (item.type !== "wait") {
              setShow(!show);
            }
          }}
          className={twMerge(
            "w-full flex items-center justify-between gap-2 ",
            item.type === "wait" ? "text-white" : "text-red-500"
          )}
        >
          <div className="flex items-center gap-2">
            <Icon className="size-4" />
            <span className="text-sm">{title}</span>
          </div>
          {item.type !== "wait" ? (
            <ChevronDown
              className={twMerge(
                "size-4 duration-300 ease-in-out",
                show ? "rotate-180" : "rotate-0"
              )}
            />
          ) : (
            <button onClick={handleRemove}>
              <Trash2 className="size-4 text-red-500" />
            </button>
          )}
        </button>

        {show && (
          <div className={twMerge("w-full", isDragging ? "hidden" : "block")}>
            <CardByType item={item} />
          </div>
        )}
      </>
    );
  }

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={twMerge(
        "w-full flex flex-col gap-5 rounded bg-secondary p-3",
        isDragging ? "opacity-70" : "opacity-100"
      )}
      {...attributes}
      {...listeners}
    >
      {item.item ? renderSelected() : renderUnselected()}
    </div>
  );
}
