import {
  Bolt,
  Bookmark,
  BookmarkMinus,
  BookmarkPlus,
  Bot,
  CalendarDays,
  CirclePlay,
  Contact,
  Crown,
  DatabaseBackup,
  FileText,
  Filter,
  Flame,
  Folder,
  Gift,
  GraduationCap,
  Image,
  Headset,
  LetterText,
  Menu as MenuIcon,
  MessagesSquare,
  Mic,
  Save,
  SendHorizontal,
  Shuffle,
  Smile,
  Star,
  Tag,
  TimerReset,
  User,
  Video,
  Webhook,
  Zap,
} from "lucide-react";
import { useContext, useEffect, useRef, useState } from "react";
import { getBaseUrl } from "../lib/base-url";
import { ItemScriptType } from "../models/db";
import ErrorModal from "./error-modal";
import useGetSteps from "./hooks/get-steps";
import useSettingsUpdate from "./hooks/settings-update";
import { useTrialCountdown } from "./hooks/use-trial-countdown";
import LoginModal from "./login-modal";
import { ConfirmModal } from "./login-models/confirm-modal";
import Menu from "./menu";
import ReviewModal from "./review-modal";
import {
  HeaderContext,
  LoginTab,
  MenuTabType,
} from "./providers/header-context";
import { SessionContext } from "./providers/session-context";
import SortableListStep from "./sortable-list-step";
import StepCardHeader from "./step-card-header";
import { urls } from "./utils/checkout";
import { changeChatViewWithStep, getAllChats } from "./utils/functions";

// Debug bridge (DEV only): permite rodar diagnósticos via Console mesmo sem WPP exposto.
// Fica eliminado do bundle quando DEV !== "true" (dotenv-webpack + terser).
const REVZAP_DEV_DEBUG = process.env.DEV === "true";

/**
 * Log condicional que só aparece quando DEV="true"
 * @param prefix - Prefixo do log (ex: "[getGroups]")
 * @param args - Argumentos para console.log
 */
const devLog = (...args: any[]) => {
  if (REVZAP_DEV_DEBUG) {
    console.log(...args);
  }
};

/**
 * Warning condicional que só aparece quando DEV="true"
 * @param prefix - Prefixo do warning
 * @param args - Argumentos para console.warn
 */
const devWarn = (...args: any[]) => {
  if (REVZAP_DEV_DEBUG) {
    console.warn(...args);
  }
};

/**
 * Error sempre aparece (mesmo em produção), mas com contexto adicional em DEV
 * @param args - Argumentos para console.error
 */
const devError = (...args: any[]) => {
  console.error(...args);
};

const baseUrl = getBaseUrl();

export function getIconByType(itemType: MenuTabType) {
  switch (itemType) {
    case "group":
      return Folder;
    case "audio":
      return Mic;
    case "image":
      return Image;
    case "video":
      return Video;
    case "doc":
      return FileText;
    case "contact":
      return Contact;
    case "script":
      return Filter;
    case "delay":
      return TimerReset;
    case "react":
      return Smile;
    case "randomizer":
      return Shuffle;
    case "settings":
      return Bolt;
    case "account":
      return User;
    case "step":
      return Bookmark;
    case "addStep":
      return BookmarkPlus;
    case "removeStep":
      return BookmarkMinus;
    case "label":
      return Tag;
    case "wait":
      return CirclePlay;
    case "trigger":
      return MessagesSquare;
    case "webhook":
      return Webhook;
    case "schedule_list":
      return CalendarDays;
    case "schedule":
      return CalendarDays;
    case "shoot":
      return SendHorizontal;
    case "shoot_list":
      return SendHorizontal;
    case "export":
      return DatabaseBackup;
    case "shot-triggers-list":
      return Bot;
    case "shooting":
      return SendHorizontal;
    case "saver":
      return Save;
    case "maturador":
      return Flame;
    default:
      return LetterText;
  }
}

