export default function Header() {
  const [selected, setSelected] = useState<number | undefined>();
  const [showErrorMessage, setShowErrorMessage] = useState(false);
  const [showReviewModal, setShowReviewModal] = useState(false);
  const [reviewStats, setReviewStats] = useState<{
    averageScore: number;
    total: number;
  } | null>(null);
  const errorTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const [countAllChats, setCountAllChats] = useState(0);
  const { steps, updateStepIndex } = useGetSteps();
  const {
    show,
    setShow,
    showCheckout,
    setShowCheckout,
    modelTab,
    setModelTab,
    confirmModal,
  } = useContext(HeaderContext);
  const { session } = useContext(SessionContext);
  const { formatTimeRemaining, isExpired } = useTrialCountdown(
    session?.trialEndsAt,
    session?.trialStatus,
  );
  useSettingsUpdate();

  useEffect(() => {
    getAllChats("all", true).then((chats) => {
      setCountAllChats(chats.length);
    });
  }, []);

  useEffect(() => {
    // Buscar estatísticas de review se for MASTER
    if (session?.role === "MASTER") {
      devLog("[REVIEW STATS] Buscando estatísticas para MASTER...");
      chrome.runtime
        .sendMessage({ action: "review.stats" })
        .then((response) => {
          devLog("[REVIEW STATS] Resposta recebida:", response);
          if (response?.ok && response.data?.statistics) {
            setReviewStats({
              averageScore: response.data.statistics.averageScore,
              total: response.data.statistics.total,
            });
            devLog("[REVIEW STATS] Stats setadas:", {
              averageScore: response.data.statistics.averageScore,
              total: response.data.statistics.total,
            });
          } else {
            devWarn("[REVIEW STATS] Resposta inválida:", response);
          }
        })
        .catch((error) => {
          devError("[REVIEW STATS] Erro ao buscar:", error);
        });
    }
  }, [session?.role]);

  useEffect(() => {
    const handleErrorMessage = (
      e: CustomEvent<{ message: string; details?: string }>,
    ) => {
      // Popup de erro desabilitado - apenas loga no console
      console.warn(
        "Erro capturado (popup desabilitado):",
        e.detail.message,
        e.detail.details,
      );

      // Código comentado para desabilitar o popup
      // setError({ message: e.detail.message, details: e.detail.details });
      // setShowErrorMessage(true);

      // // Limpa timeout anterior se existir
      // if (errorTimeoutRef.current) {
      //   clearTimeout(errorTimeoutRef.current);
      // }

      // // Cria novo timeout
      // errorTimeoutRef.current = setTimeout(() => {
      //   setShowErrorMessage(false);
      // }, 5000);
    };

    window.addEventListener(
      "showErrorMessage",
      handleErrorMessage as EventListener,
    );

    return () => {
      window.removeEventListener(
        "showErrorMessage",
        handleErrorMessage as EventListener,
      );
      // Limpa timeout ao desmontar
      if (errorTimeoutRef.current) {
        clearTimeout(errorTimeoutRef.current);
      }
    };
  }, []);

  async function setStep(stepId?: number) {
    if (stepId) {
      if (!stepId || selected === stepId) return;
    } else {
      if (!selected) return;
    }

    setSelected(stepId);
    await changeChatViewWithStep(stepId);
  }

  function toggleCheckout(tab?: LoginTab) {
    let value = !showCheckout;

    if (tab) {
      if (tab !== modelTab) value = true;
      setModelTab(tab);
    }

    setShowCheckout(value);
  }

  function handleErrorModalMouseEnter() {
    if (errorTimeoutRef.current) {
      clearTimeout(errorTimeoutRef.current);
      errorTimeoutRef.current = null;
    }
  }

  function handleErrorModalMouseLeave() {
    errorTimeoutRef.current = setTimeout(() => {
      setShowErrorMessage(false);
    }, 2000);
  }

  function handleReviewClick(e: React.MouseEvent<HTMLAnchorElement>) {
    e.preventDefault();
    setShowReviewModal(true);
  }

  async function handleReviewSubmit(score: number, message: string) {
    try {
      const response = await chrome.runtime.sendMessage({
        action: "review.submit",
        data: { score, message },
      });

      if (response?.ok) {
        // Fecha o modal
        setShowReviewModal(false);

        // Atualiza estatísticas se for MASTER
        if (session?.role === "MASTER") {
          const statsResponse = await chrome.runtime.sendMessage({
            action: "review.stats",
          });
          if (statsResponse?.ok && statsResponse.data?.statistics) {
            setReviewStats({
              averageScore: statsResponse.data.statistics.averageScore,
              total: statsResponse.data.statistics.total,
            });
          }
        }

        // Aguarda um momento para dar feedback visual
        setTimeout(() => {
          // Redireciona para a página de avaliação
          const reviewUrl = urls.review;
          window.open(reviewUrl, "_blank", "noopener,noreferrer");
        }, 500);
      } else {
        throw new Error(response?.error || "Erro ao enviar avaliação");
      }
    } catch (error) {
      console.error("Erro ao enviar avaliação:", error);
      window.dispatchEvent(
        new CustomEvent("showErrorMessage", {
          detail: {
            message:
              (error as Error).message ||
              "Erro ao enviar avaliação. Tente novamente.",
          },
        }),
      );
    }
  }

  return (
    <>
      <div className="absolute top-0 left-0 w-full h-14 flex items-center justify-between gap-3 px-3 py-2 bg-[#6F1FF0] dark:text-white">
        <div className="w-full flex items-center gap-3 overflow-auto">
          <img
            src={baseUrl + "/assets/logo-white.webp"}
            alt="Logo"
            className="w-9 mr-1"
          />
          <StepCardHeader
            text="Todos"
            total={countAllChats}
            onClick={() => setStep()}
            selected={selected === undefined}
          />
          <SortableListStep
            items={steps}
            update={updateStepIndex}
            vertical={false}
          >
            {steps
              .sort((a, b) => a.index - b.index)
              .map((item) => (
                <StepCardHeader
                  key={item.id}
                  text={item.title}
                  total={item.users?.length || 0}
                  onClick={() => setStep(item.id)}
                  selected={selected === item.id}
                />
              ))}
          </SortableListStep>
        </div>

        <div className="flex items-center gap-3">
          {session &&
            session.logged &&
            session.trialStatus &&
            !session.hasPlan && (
              <span className="text-sm font-medium text-nowrap">
                {isExpired
                  ? "Teste grátis expirado"
                  : `Tempo restante de teste grátis: ${formatTimeRemaining()}`}
              </span>
            )}
          <a
            href={urls.class}
            rel="noopener noreferrer"
            target="_blank"
            className="p-2 rounded bg-primary whitespace-nowrap text-sm font-bold flex items-center gap-2"
          >
            <GraduationCap className="size-3.5" strokeWidth={3} />
            <span>REVCLASS</span>
          </a>

          {session?.logged && (
            <>
              <a
                href={urls.suport}
                rel="noopener noreferrer"
                target="_blank"
                className="p-2 rounded bg-primary whitespace-nowrap text-sm font-bold flex items-center gap-2"
              >
                <Headset className="size-3.5" strokeWidth={3} />
                <span>SUPORTE</span>
              </a>

              {session.permissions?.includes("EXTENSION") && (
                <button
                  onClick={() => toggleCheckout("indicate")}
                  className="p-2 rounded bg-primary whitespace-nowrap text-sm font-bold flex items-center gap-2 animate-pulse"
                >
                  <Gift className="size-3.5" strokeWidth={3} />
                  <span>INDIQUE E GANHE</span>
                </button>
              )}

              {session?.role === "MASTER" &&
              session?.statusReview === "SUBMITTED" &&
              reviewStats ? (
                <div className="p-2 rounded bg-primary whitespace-nowrap text-sm font-bold flex items-center gap-2">
                  <Star
                    className="size-3.5 fill-yellow-400 text-yellow-400"
                    strokeWidth={3}
                  />
                  <span>
                    {reviewStats.averageScore.toFixed(1)} ({reviewStats.total}{" "}
                    {reviewStats.total === 1 ? "avaliação" : "avaliações"})
                  </span>
                </div>
              ) : session?.role === "MASTER" &&
                session?.statusReview !== "SUBMITTED" ? (
                <>
                  {devLog(
                    "[RENDER] Mostrando AVALIAR AGORA - role:",
                    session?.role,
                    "statusReview:",
                    session?.statusReview,
                    "reviewStats:",
                    reviewStats,
                  )}
                  <a
                    href={urls.review}
                    rel="noopener noreferrer"
                    target="_blank"
                    onClick={handleReviewClick}
                    className="p-2 rounded bg-primary whitespace-nowrap text-sm font-bold flex items-center gap-2"
                  >
                    <Star className="size-3.5" strokeWidth={3} />
                    <span>AVALIAR AGORA</span>
                  </a>
                </>
              ) : (
                <>
                  {devLog(
                    "[RENDER] Nada exibido - role:",
                    session?.role,
                    "statusReview:",
                    session?.statusReview,
                    "reviewStats:",
                    reviewStats,
                  )}
                  {null}
                </>
              )}

              {!session.permissions?.includes("SAVER") && (
                <button
                  onClick={() => toggleCheckout("saver")}
                  className="p-2 rounded bg-primary whitespace-nowrap text-sm font-bold flex items-center gap-2 animate-pulse"
                >
                  <Save className="size-3.5" strokeWidth={3} />
                  <span>REVSAVER</span>
                </button>
              )}

              {!session.permissions?.includes("MATURADOR") && (
                <button
                  onClick={() => toggleCheckout("maturador")}
                  className="p-2 rounded bg-primary whitespace-nowrap text-sm font-bold flex items-center gap-2 animate-pulse"
                >
                  <Flame className="size-3.5" strokeWidth={3} />
                  <span>REVPROTECT</span>
                </button>
              )}

              {!session.permissions?.includes("EXTENSION") && (
                <button
                  onClick={() => toggleCheckout("plans_video")}
                  className="p-2 rounded bg-primary whitespace-nowrap text-sm font-bold flex items-center gap-2 animate-pulse"
                >
                  <Zap className="size-3.5" strokeWidth={3} />
                  <span>REVZAP</span>
                </button>
              )}
            </>
          )}

          {!session?.logged && (
            <button
              onClick={() => toggleCheckout("login")}
              className="p-2 rounded bg-primary whitespace-nowrap text-sm font-bold flex items-center gap-2 animate-pulse"
            >
              <Crown className="size-3.5" strokeWidth={3} />
              <span>CONTA PREMIUM</span>
            </button>
          )}
        </div>

        <button
          className="p-2 rounded duration-300 hover:bg-white/10"
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            setShow(!show);
          }}
          type="button"
        >
          <MenuIcon className="size-5 text-white" />
        </button>
      </div>
      <Menu />
      {showCheckout && <LoginModal />}
      {showReviewModal && (
        <ReviewModal
          onClose={() => setShowReviewModal(false)}
          onSubmit={handleReviewSubmit}
        />
      )}
      {showErrorMessage && (
        <ErrorModal
          details={undefined}
          message=""
          onMouseEnter={handleErrorModalMouseEnter}
          onMouseLeave={handleErrorModalMouseLeave}
        />
      )}
      {confirmModal && <ConfirmModal />}
    </>
  );
}
