import { Star } from "lucide-react";
import { useState } from "react";
import { createPortal } from "react-dom";

interface ReviewModalProps {
  onClose: () => void;
  onSubmit: (score: number, message: string) => Promise<void>;
}

export default function ReviewModal({ onClose, onSubmit }: ReviewModalProps) {
  const [score, setScore] = useState(0);
  const [hoverScore, setHoverScore] = useState(0);
  const [message, setMessage] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  async function handleSubmit() {
    if (score === 0) return;

    setIsSubmitting(true);
    try {
      await onSubmit(score, message);
    } finally {
      setIsSubmitting(false);
    }
  }

  const modalContent = (
    <div className="fixed inset-0 z-[99999] flex items-center justify-center bg-black/50 backdrop-blur-sm">
      <div className="w-full max-w-md bg-[var(--background-default)] rounded-lg shadow-2xl p-6 mx-4 border border-[var(--border-list)]">
        <div className="flex flex-col gap-4">
          <div className="flex items-center justify-between">
            <h2 className="text-xl font-bold">Avalie o RevZap</h2>
            <button
              onClick={onClose}
              className="p-2 rounded hover:bg-neutral/50 transition-colors"
              disabled={isSubmitting}
            >
              <svg
                className="w-5 h-5"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M6 18L18 6M6 6l12 12"
                />
              </svg>
            </button>
          </div>

          <p className="text-sm text-gray-400">
            Sua opinião é muito importante para nós! Como você avalia sua
            experiência?
          </p>

          <div className="flex items-center justify-center gap-2 py-4">
            {[1, 2, 3, 4, 5].map((star) => (
              <button
                key={star}
                onClick={() => setScore(star)}
                onMouseEnter={() => setHoverScore(star)}
                onMouseLeave={() => setHoverScore(0)}
                className="transition-transform hover:scale-110"
                disabled={isSubmitting}
              >
                <Star
                  className={`size-10 ${
                    star <= (hoverScore || score)
                      ? "fill-yellow-400 text-yellow-400"
                      : "text-gray-400"
                  } transition-all`}
                />
              </button>
            ))}
          </div>

          {score > 0 && (
            <div className="flex flex-col gap-2">
              <label htmlFor="review-message" className="text-sm font-medium">
                Deixe um comentário (opcional)
              </label>
              <textarea
                id="review-message"
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                placeholder="Conte-nos sobre sua experiência..."
                className="w-full h-24 p-3 bg-neutral rounded-lg resize-none focus:outline-none focus:ring-2 focus:ring-primary text-sm"
                disabled={isSubmitting}
              />
            </div>
          )}

          <div className="flex gap-3 pt-2">
            <button
              onClick={onClose}
              className="flex-1 px-4 py-2 bg-neutral rounded-lg hover:bg-neutral/80 transition-colors text-sm font-medium"
              disabled={isSubmitting}
            >
              Cancelar
            </button>
            <button
              onClick={handleSubmit}
              disabled={score === 0 || isSubmitting}
              className="flex-1 px-4 py-2 bg-primary rounded-lg hover:bg-primary/90 transition-colors text-sm font-bold disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isSubmitting ? "Enviando..." : "Avaliar"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  return createPortal(modalContent, document.body);
}
